  function bindHmoClinicDropdown(root, onPick){
    if(!root || typeof onPick !== "function") return;
    if(root._lcHmoDdOutsideHandler){
      document.removeEventListener("click", root._lcHmoDdOutsideHandler);
      root._lcHmoDdOutsideHandler = null;
    }
    const trigger = root.querySelector("#lcHmoDdTrigger");
    const menu = root.querySelector("#lcHmoDdMenu");
    const wrap = root.querySelector("#lcHmoDdWrap");
    if(!trigger || !menu) return;
    const HMO_ROW_H = 38;
    const HMO_MENU_PAD = 10;
    const HMO_MENU_GAP = 6;
    const HMO_MENU_Z = 10050;
    const clearMenuPosition = () => {
      menu.style.position = "";
      menu.style.zIndex = "";
      menu.style.top = "";
      menu.style.bottom = "";
      menu.style.left = "";
      menu.style.width = "";
      menu.style.maxHeight = "";
      menu.style.height = "";
      menu.style.overflowY = "";
    };
    const positionMenu = () => {
      const rect = trigger.getBoundingClientRect();
      const items = menu.querySelectorAll("[data-hmo-val]").length || 5;
      const estH = items * HMO_ROW_H + HMO_MENU_PAD;
      const margin = 8;
      const spaceBelow = window.innerHeight - rect.bottom - HMO_MENU_GAP - margin;
      const spaceAbove = rect.top - HMO_MENU_GAP - margin;
      let openUp = spaceBelow < estH && spaceAbove > spaceBelow;
      if(spaceBelow < estH && spaceAbove < estH) openUp = spaceAbove >= spaceBelow;
      const avail = Math.max(0, openUp ? spaceAbove : spaceBelow);
      const menuH = Math.min(estH, avail);
      menu.style.position = "fixed";
      menu.style.zIndex = String(HMO_MENU_Z);
      menu.style.width = rect.width + "px";
      menu.style.left = Math.max(margin, Math.min(rect.left, window.innerWidth - rect.width - margin)) + "px";
      menu.style.maxHeight = menuH + "px";
      menu.style.height = menuH + "px";
      menu.style.overflowY = menuH < estH ? "auto" : "hidden";
      menu.classList.toggle("lcHmoDd__menu--up", openUp);
      if(openUp){
        menu.style.top = "auto";
        menu.style.bottom = (window.innerHeight - rect.top + HMO_MENU_GAP) + "px";
      } else {
        menu.style.bottom = "auto";
        menu.style.top = (rect.bottom + HMO_MENU_GAP) + "px";
      }
    };
    const openDd = () => {
      if(menu.parentElement !== document.body) document.body.appendChild(menu);
      document.body.classList.add("lcHmoDdOpen");
      positionMenu();
      trigger.setAttribute("aria-expanded", "true");
      menu.classList.add("is-open");
      requestAnimationFrame(positionMenu);
      window.addEventListener("resize", positionMenu, { passive: true });
      window.addEventListener("scroll", positionMenu, { passive: true, capture: true });
    };
    const closeDd = () => {
      trigger.setAttribute("aria-expanded", "false");
      menu.classList.remove("is-open", "lcHmoDd__menu--up");
      document.body.classList.remove("lcHmoDdOpen");
      window.removeEventListener("resize", positionMenu);
      window.removeEventListener("scroll", positionMenu, true);
      clearMenuPosition();
      if(wrap && menu.parentElement === document.body) wrap.appendChild(menu);
    };
    on(trigger, "click", (ev) => {
      ev.stopPropagation();
      menu.classList.contains("is-open") ? closeDd() : openDd();
    });
    on(menu, "click", (ev) => {
      const item = ev.target.closest("[data-hmo-val]");
      if(!item) return;
      const val = safeTrim(item.getAttribute("data-hmo-val") || "");
      closeDd();
      onPick(val);
    });
    root._lcHmoDdOutsideHandler = function closeDdOutside(ev){
      if(wrap && !wrap.contains(ev.target) && !menu.contains(ev.target)) closeDd();
    };
    document.addEventListener("click", root._lcHmoDdOutsideHandler, { capture: false });
  }

