    getPhoenixRiskMortgageDecision(){
      const allPolicies = this.newPolicies || [];
      const phoenixPolicies = allPolicies.filter(p => ['ריסק','ריסק משכנתא'].includes(safeTrim(p?.type)) && safeTrim(p?.company) === 'הפניקס');
      if(!phoenixPolicies.length) return null;

      const productType = phoenixPolicies.some(p => safeTrim(p?.type) === 'ריסק משכנתא') ? 'mortgage' : 'risk';
      const relevantInsureds = (this.insureds || []).filter(ins => {
        try { return this.getHealthPoliciesForInsured(ins).some(p => phoenixPolicies.includes(p)); }
        catch(_e){ return false; }
      });
      const insuredPool = relevantInsureds.length ? relevantInsureds : (this.insureds || []);
      const ages = insuredPool.map(ins => this.calcAge?.(safeTrim(ins?.data?.birthDate || ins?.birthDate || ''))).filter(age => Number.isFinite(Number(age))).map(Number);
      const maxAge = ages.length ? Math.max(...ages) : 0;

      const amountValues = [];
      phoenixPolicies.forEach(policy => {
        [policy?.compensation, policy?.sumInsured, policy?.coverageAmount, policy?.sum, policy?.premiumAmount, policy?.insuranceAmount, policy?.amount].forEach(value => {
          const n = this.parseMoneyNumber ? this.parseMoneyNumber(value) : Number(String(value ?? '').replace(/[^0-9.]/g, ''));
          if(Number.isFinite(n)) amountValues.push(n);
        });
        // Phoenix risk/mortgage sums are often stored per insured in the policy draft.
        // Include those values so automatic routing (under/over 2M) works also in multi-insured policies.
        [policy?.sumInsuredPerInsured, policy?.compensationPerInsured].forEach((map) => {
          if(!map || typeof map !== 'object') return;
          Object.values(map).forEach((value) => {
            const n = this.parseMoneyNumber ? this.parseMoneyNumber(value) : Number(String(value ?? '').replace(/[^0-9.]/g, ''));
            if(Number.isFinite(n)) amountValues.push(n);
          });
        });
      });
      const maxSumInsured = amountValues.length ? Math.max(...amountValues) : 0;
      const isExtended = maxAge > 55 || maxSumInsured > 2000000;
      return {
        productType,
        isMortgage: productType === 'mortgage',
        maxAge,
        maxSumInsured,
        isExtended,
        catalogKey: isExtended ? 'extended_risk' : 'short_risk',
        engineKey: `phoenix_${productType}_${isExtended ? 'o55_or_over2m' : 'u55_under2m'}`,
        sourcePolicies: phoenixPolicies,
        insureds: insuredPool
      };
    },

    getPhoenixRiskMortgageHealthSchema(){
      const decision = this.getPhoenixRiskMortgageDecision?.();
      if(!decision) return [];
      const catalog = this.buildPhoenixQuestionnaireCatalog();
      const picked = catalog[decision.catalogKey] || catalog.short_risk;
      const companies = ['הפניקס'];
      const policyId = decision.sourcePolicies?.[0]?.id || '';
      const productLabel = decision.isMortgage ? 'ריסק משכנתא' : 'ריסק';
      const ageLabel = decision.maxAge ? `גיל מבוטח מבוגר ביותר: ${decision.maxAge}` : 'גיל מבוטח מבוגר ביותר: לא זוהה';
      const sumLabel = decision.maxSumInsured ? `סכום ביטוח מירבי: ${this.formatMoneyValue ? this.formatMoneyValue(decision.maxSumInsured) : String(decision.maxSumInsured)}` : 'סכום ביטוח מירבי: לא זוהה';
      const routeLabel = decision.isExtended ? 'נבחרה הצהרה מורחבת (ריסק/חיים או משכנתא) — מעל גיל 55 ו/או מעל 2 מיליון ₪ · טופס 300306085' : 'נבחרה הצהרה מקוצרת (ריסק/חיים או משכנתא) — עד גיל 55 ועד 2 מיליון ₪ · טופס 300306083';
      const q = (step) => {
        const questionnaireNos = (step.questionnaireNos || []).map(String);
        const fields = this.buildPhoenixFollowupFields(questionnaireNos, step.fields || []);
        const source = questionnaireNos.length ? `הפניקס · שאלון ${questionnaireNos.join(', ')}` : 'הפניקס · פירוט לפי הצהרת הטופס';
        return {
          key: `${decision.engineKey}__${step.key}`,
          text: step.text,
          companies,
          questionnaireNos,
          questionnaireSource: source,
          questionnaireLabel: questionnaireNos.length ? `שאלון ${questionnaireNos.join(', ')}` : 'פירוט משלים',
          fields: fields.length ? fields : [{ key:'details', label:'פירוט לפי הצהרת הפניקס', type:'textarea' }]
        };
      };
      return [{
        key: decision.engineKey,
        title: `הצהרת בריאות · הפניקס ${productLabel === 'ריסק' ? 'ריסק (חיים)' : productLabel}`,
        summary: `${picked.title} · ${routeLabel}. ${ageLabel}; ${sumLabel}. כאשר יש כמה מבוטחים, הבחירה מתבצעת לפי גיל המבוטח המבוגר ביותר. כל תשובת כן פותחת מודאל מרכזי עם שאלון ההמשך המדויק לפי מספר השאלון.` ,
        policyId,
        questions: (picked.steps || []).map(q)
      }];
    },

