    // ===== מגדל — ריסק: מורחב (481) או מקוצר עד 2 מיליון (750) =====
    getMagdalRiskSumInsuredMax(){
      const policies = (this.newPolicies || []).filter(p => safeTrim(p?.company) === 'מגדל' && safeTrim(p?.type) === 'ריסק');
      const nums = policies.map(p => {
        const raw = String(p?.sumInsured || p?.coverage || '').replace(/[^\d.]/g, '');
        const n = Number(raw);
        return Number.isFinite(n) ? n : null;
      }).filter(n => n != null);
      if(!nums.length) return null;
      return Math.max(...nums);
    },

    getMagdalRiskHealthSchema(){
      const maxSum = this.getMagdalRiskSumInsuredMax();
      // עד 2 מיליון (כולל) → טופס מקוצר; מעל / ללא סכום → טופס מורחב 481
      if(maxSum != null && maxSum <= 2000000) return this.getMagdalRiskShortHealthSchema();
      return this.getMagdalRiskExtendedHealthSchema();
    },

