        '14': { title:'כלי דם / ורידים / עורקים / מפרצת', fields:[t('diagnosis','אבחנה: DVT / מפרצת / PVD / ורידים מורחבים / עורקים / תסחיף / אחר'), t('date','מועד אבחון / אירוע'), t('treatment','טיפול / מדללי דם / ניתוח / מעקב'), z('status','מצב כיום / סיבוכים / בדיקות עדכניות')] },
