      if(!cancerPolicies.length) return [];
      const amountValues = [];
      cancerPolicies.forEach(policy => {
        [policy?.compensation, policy?.sumInsured, policy?.coverageAmount].forEach(value => {
          const n = this.parseMoneyNumber ? this.parseMoneyNumber(value) : Number(String(value ?? '').replace(/[^0-9.]/g, ''));
          if(Number.isFinite(n)) amountValues.push(n);
        });
        const map = policy?.compensationPerInsured;
        if(map && typeof map === 'object'){
          Object.values(map).forEach(value => {
            const n = this.parseMoneyNumber ? this.parseMoneyNumber(value) : Number(String(value ?? '').replace(/[^0-9.]/g, ''));
            if(Number.isFinite(n)) amountValues.push(n);
          });
        }
      });
      const maxAmount = amountValues.length ? Math.max(...amountValues) : 0;
      if(maxAmount > 300000){
        const full = this.getAyalonHealthSchema()[0];
        return [{
          ...full,
          key: 'master_ayalon_cancer_full_001',
          title: 'הצהרת בריאות סרטן · איילון (מעל 300,000 ₪)',
          summary: 'סכום פיצוי מעל 300,000 ₪ — נפתח טופס בריאות מלא 001.',
          policyId: cancerPolicies[0]?.id || '',
          questions: (full.questions || []).map(q => ({ ...q, key: String(q.key || '').replace(/^ayalon__/, 'ayalon_cancer_full__') }))
        }];
      }
      const companies = ['איילון'];
      const f = (nos, extra=[]) => this.buildAyalonFollowupFields(nos, extra);
      return [{
        key: 'master_ayalon_cancer_010',
        title: 'הצהרת בריאות סרטן · איילון (עד 300,000 ₪)',
        summary: 'טופס איילון 010 — הצהרת בריאות מקוצרת לסרטן עד 300,000 ₪ (בשביל החוסן).',
        policyId: cancerPolicies[0]?.id || '',
        questions: [
          { key:'ayalon_cancer__pending', text:'1. האם הופנית וטרם סיימת הליך בירור של תופעה או מחלה ב־5 השנים האחרונות ועדיין לא נקבעה אבחנה סופית? (ממוגרפיה, מיפוי עצמות, צנתור, מיפוי לב, אקו לב, CT, MRI, אולטרסאונד שאינו מעקב הריון, ביופסיה, דם סמוי, קולונוסקופיה, גסטרוסקופיה, EEG, קולפוסקופיה)', companies, fields: f([], [{ key:'testType', label:'סוג הבדיקה / הבירור', type:'text' }, { key:'date', label:'מועד ההפניה', type:'text' }, { key:'status', label:'סטטוס הבירור כיום', type:'textarea' }]) },
          { key:'ayalon_cancer__smoking20', text:'2. האם את/ה מעשן מעל 20 סיגריות ביום? אם כן — ציין כמות', companies, fields: f([], [{ key:'amount', label:'כמות סיגריות ליום', type:'text' }]) },
          { key:'ayalon_cancer__personal_family', text:'3. האם אובחנת במהלך חייך בגידולים (כולל טרום סרטניים), פוליפים (מעי / צוואר הרחם / רחם / שלוחות), סרטן ומחלות ממאירות — ו/או האם למיטב ידיעתך אובחן אצל קרוב מדרגה ראשונה (אב/אם/אח/אחות) סרטן שד / מעי גס / שחלות? (שאלון 32 להיסטוריה משפחתית)', companies, fields: f(['32'], [{ key:'personalDiagnosis', label:'אם אישי — סוג / מועד / טיפול / מצב כיום', type:'textarea' }]) }
        ]
      }];
