  function agentApptCompanyNeedsPhoneHome(companyId){
    return ["menora", "hachshara", "phoenix", "ayalon"].includes(safeTrim(companyId));
  }
  function agentApptCompanyNeedsAgentId(companyId){
    return ["menora", "hachshara", "phoenix"].includes(safeTrim(companyId));
  }
  function agentApptCompanyNeedsAddress(companyId){
    return ["menora", "hachshara", "phoenix", "ayalon", "migdal"].includes(safeTrim(companyId));
  }
  function agentApptCompanyNeedsAgentContact(companyId){
    return ["phoenix", "ayalon", "hachshara"].includes(safeTrim(companyId));
  }

  const HealthRiskChoiceUI = {
    els: {},
    init(){
      this.els.modal = document.getElementById("lcHealthRiskChoiceModal");
      this.els.btnClose = document.getElementById("lcHealthRiskChoiceModalClose");
      if(!this.els.modal) return;
      on(this.els.btnClose, "click", (ev) => { ev.preventDefault(); this.close(); });
      on(this.els.modal, "click", (ev) => {
        const t = ev.target;
        if(t?.getAttribute?.("data-close") === "1"){ this.close(); return; }
        const card = t?.closest?.("[data-health-risk-choice]");
        if(!card) return;
        const choice = safeTrim(card.getAttribute("data-health-risk-choice"));
        this.handleChoice(choice);
      });
      document.addEventListener("keydown", (ev) => {
        if(ev.key === "Escape" && this.isOpen()) this.close();
      });
    },
    isOpen(){ return !!this.els.modal?.classList.contains("is-open"); },
    open(){
      try{ NewCustomerEntryUI?.close?.(); }catch(_e){}
      try{ AgentAppointmentWizard?.close?.(); }catch(_e){}
      this.els.modal.classList.add("is-open");
      this.els.modal.setAttribute("aria-hidden", "false");
      document.body.classList.add("modal-open");
    },
    close(){
      if(!this.els.modal) return;
      this.els.modal.classList.remove("is-open");
      this.els.modal.setAttribute("aria-hidden", "true");
      const hasOther = !!document.querySelector(".modal.is-open, .drawer.is-open, .lcWizard.is-open");
      if(!hasOther) document.body.classList.remove("modal-open");
    },
    handleChoice(choice){
      if(choice === "proposal"){
        this.close();
        NewCustomerEntryUI.openHealthProposalWizard();
        return;
      }
      if(choice === "agent_appointment"){
        this.close();
        AgentAppointmentWizard.open();
      }
    }
  };

