  UI.init();
  Auth.init();
  ForgotPasswordUI.init();
  CustomersUI.init();
  CustomerEditUI.init();
  ArchiveCustomerUI.init();
  PurgeArchivedCustomerUI.init();
  ProcessesUI.init();
  OpsEventsUI.init();
  Wizard.init();
  SecurityUI.init();
  HealthRiskChoiceUI.init();
  AgentAppointmentWizard.init();
  NewCustomerEntryUI.init();
  HarHabituachTopbarUI.init();
  CarInsuranceClickUI.init();
  SimulatorsCenterUI.init();
  LeadShellUI.init();
  // ===== REMINDER UI =====
  const REMINDERS_TABLE = "reminders";

  const ReminderUI = {
    els: {},
    reminders: [],
    currentStep: "list",   // "list" | "type" | "details"
    selectedType: "",
    editingId: null,
    alertQueue: [],
    alertActive: false,
    alertAudioCtx: null,
    checkInterval: null,
    _saving: false,

    ICONS: { callback:"📞", documents:"📄", missing:"⚠️" },
    LABELS: { callback:"חזרה ללקוח", documents:"מעקב מסמכים", missing:"השלמת חוסרים" },

    // ── init ──────────────────────────────────────────
    init(){
      this.els = {
        fab:          $("#giReminderFab"),
        fabBadge:     $("#giReminderFabBadge"),
        modal:        $("#giReminderModal"),
        backdrop:     $("#giReminderBackdrop"),
        closeBtn:     $("#giReminderModalClose"),
        title:        $("#giReminderModalTitle"),
        step1:        $("#giReminderStep1"),
        step2:        $("#giReminderStep2"),
        stepList:     $("#giReminderStep_list"),
        typeCards:    $$(".giReminderModal__typeCard"),
        // step-2 fields
        callbackNote: $("#giReminderCallbackNote"),
        docsList:     $("#giReminderDocsList"),
        missingList:  $("#giReminderMissingList"),
        customerSel:  $("#giReminderCustomer"),
        dateInput:    $("#giReminderDate"),
        timeInput:    $("#giReminderTime"),
        errorBox:     $("#giReminderError"),
        // list
        list:         $("#giReminderList"),
        listEmpty:    $("#giReminderListEmpty"),
        addNewBtn:    $("#giReminderAddNewBtn"),
        // footer
        foot:         $("#giReminderModalFoot"),
        cancelBtn:    $("#giReminderCancelBtn"),
        backBtn:      $("#giReminderBackBtn"),
        nextBtn:      $("#giReminderNextBtn"),
        saveBtn:      $("#giReminderSaveBtn"),
        // alert
        alert:        $("#giReminderAlert"),
        alertIcon:    $("#giReminderAlertIcon"),
        alertTitle:   $("#giReminderAlertTitle"),
        alertText:    $("#giReminderAlertText"),
        alertCustomer:$("#giReminderAlertCustomer"),
        alertTime:    $("#giReminderAlertTime"),
        alertDone:    $("#giReminderAlertDone"),
        alertSnooze:  $("#giReminderAlertSnooze"),
        alertOpenLead:$("#giReminderAlertOpenLead"),
      };

      on(this.els.fab,       "click",  () => this.openModal());
      on(this.els.closeBtn,  "click",  () => this.closeModal());
      on(this.els.backdrop,  "click",  () => this.closeModal());
      on(this.els.cancelBtn, "click",  () => this.closeModal());
      on(this.els.backBtn,   "click",  () => this.goBack());
      on(this.els.nextBtn,   "click",  () => this.goNext());
      on(this.els.saveBtn,   "click",  () => this.save());
      on(this.els.addNewBtn, "click",  () => this.startNew());
      on(this.els.alertDone, "click",  () => this.dismissAlert(true));
      on(this.els.alertSnooze,"click", () => this.snoozeAlert());
      on(this.els.alertOpenLead, "click", () => {
        const r = this.alertQueue[0];
        if(!r) return;
        try {
          const lead = (CampaignLeadsStore?.leads || []).find(l => String(l.id) === String(r.lead_id));
          if(lead){
            this.dismissAlert(false);
            LeadDetailsModal.open(lead);
          } else {
            // אם אין lead_id — נסה לפתוח לפי customer_id
            UI.goView("campaignMyLeads");
            this.dismissAlert(false);
          }
        } catch(_e){}
      });

      this.els.typeCards.forEach(card => {
        on(card, "click", () => this.selectType(card.dataset.type));
      });

      // Start check loop
      this.checkInterval = setInterval(() => this.checkDueReminders(), 30000);
    },

    // ── called after login ──────────────────────────
    onLogin(){
      try { DesktopNotifications.ensurePermission(); } catch(_e) {}
      if(this.els.fab) this.els.fab.classList.remove("is-hidden");
      this.loadReminders();
    },

    onLogout(){
      if(this.els.fab) this.els.fab.classList.add("is-hidden");
      this.reminders = [];
      this.updateBadge();
    },

    // ── Supabase helpers ────────────────────────────
    agentKey(){
      return safeTrim(Auth.current?.name) || "unknown";
    },

    async loadReminders(){
      try {
        const agentId = encodeURIComponent(this.agentKey());
        const data = await Storage.restRequest(
          REMINDERS_TABLE + "?agent_id=eq." + agentId + "&is_done=eq.false&order=remind_at.asc",
          { method: "GET" }
        );
        this.reminders = Array.isArray(data) ? data : [];
        this.updateBadge();
        this.checkDueReminders();
      } catch(e) {
        console.warn("[ReminderUI] loadReminders error", e);
      }
    },

    async upsertReminder(row){
      const result = await Storage.upsertSingleRow(REMINDERS_TABLE, row);
      if(!result?.ok) throw new Error(result?.error || "upsert failed");
    },

    async markDone(id){
      await Storage.restRequest(
        REMINDERS_TABLE + "?id=eq." + encodeURIComponent(id),
        { method: "PATCH", body: { is_done: true, done_at: nowISO() } }
      );
      this.reminders = this.reminders.filter(r => r.id !== id);
      this.updateBadge();
      this.renderList();
    },

    async deleteReminder(id){
      await Storage.restRequest(
        REMINDERS_TABLE + "?id=eq." + encodeURIComponent(id),
        { method: "DELETE" }
      );
      this.reminders = this.reminders.filter(r => r.id !== id);
      this.updateBadge();
      this.renderList();
    },

    // ── badge ────────────────────────────────────────
    updateBadge(){
      const count = this.reminders.filter(r => !r.is_done).length;
      if(this.els.fabBadge){
        this.els.fabBadge.textContent = count > 9 ? "9+" : String(count);
        this.els.fabBadge.classList.toggle("is-hidden", count === 0);
      }
    },

    // ── modal open/close ─────────────────────────────
    openModal(){
      this.populateCustomerList();
      this.showStep("list");
      this.renderList();
      this.els.modal.setAttribute("aria-hidden","false");
      this.els.modal.classList.add("is-open");
    },

    closeModal(){
      this.els.modal.setAttribute("aria-hidden","true");
      this.els.modal.classList.remove("is-open");
      this.resetForm();
    },

    // ── steps ────────────────────────────────────────
    showStep(step){
      this.currentStep = step;
      this.els.step1.hidden    = (step !== "type");
      this.els.step2.hidden    = (step !== "details");
      this.els.stepList.hidden = (step !== "list");

      // footer
      const cancelBtn = this.els.cancelBtn;
      const backBtn   = this.els.backBtn;
      const nextBtn   = this.els.nextBtn;
      const saveBtn   = this.els.saveBtn;

      cancelBtn.hidden = false;
      backBtn.hidden   = (step === "list");
      nextBtn.hidden   = (step !== "type");
      saveBtn.hidden   = (step !== "details");

      const titles = { list:"תזכורות", type:"תזכורת חדשה — סוג", details:"תזכורת חדשה — פרטים" };
      if(this.els.title) this.els.title.textContent = titles[step] || "תזכורות";
    },

    startNew(){
      this.editingId = null;
      this.selectedType = "";
      this.els.typeCards.forEach(c => c.classList.remove("is-selected"));
      this.showStep("type");
    },

    // פותח מודאל תזכורת ישירות לשלב הפרטים עם שם + טלפון של ליד
    openForLead(lead){
      this.populateCustomerList();
      this.renderList();
      this.editingId = null;
      this._pendingLeadId = safeTrim(lead?.id) || null;
      this.selectedType = "callback";
      this.els.typeCards.forEach(c => c.classList.toggle("is-selected", c.dataset.type === "callback"));
      this.showStep("details");
      this.showFieldsForType("callback");

      // מלא שם לקוח ב-select אם קיים, אחרת הצג ב-note
      const name = safeTrim(lead?.customerName) || "";
      const phone = safeTrim(lead?.phone) || "";

      if(this.els.customerSel){
        // חפש לפי שם
        const opts = Array.from(this.els.customerSel.options);
        const match = opts.find(o => o.textContent.trim() === name);
        if(match) this.els.customerSel.value = match.value;
      }

      // מלא את שדה ההערה עם שם + טלפון
      if(this.els.callbackNote){
        const prefill = [name, phone].filter(Boolean).join(" | ");
        this.els.callbackNote.value = prefill ? prefill + "\n" : "";
      }

      this.els.modal.setAttribute("aria-hidden","false");
      this.els.modal.classList.add("is-open");

      // פוקוס על שדה התאריך
      window.setTimeout(() => { try { this.els.dateInput?.focus(); } catch(_e){} }, 120);
    },

    goBack(){
      if(this.currentStep === "details") this.showStep("type");
      else if(this.currentStep === "type") this.showStep("list");
    },

    goNext(){
      if(this.currentStep === "type"){
        if(!this.selectedType){
          return;
        }
        this.showStep("details");
        this.showFieldsForType(this.selectedType);
      }
    },

    selectType(type){
      this.selectedType = type;
      this.els.typeCards.forEach(c => c.classList.toggle("is-selected", c.dataset.type === type));
    },

    showFieldsForType(type){
      ["callback","documents","missing"].forEach(t => {
        const el = $(`#giReminderFields_${t}`);
        if(el) el.hidden = (t !== type);
      });
    },

    // ── populate customers ───────────────────────────
    populateCustomerList(){
      const sel = this.els.customerSel;
      if(!sel) return;
      sel.innerHTML = "<option value=\"\">— ללא קישור ללקוח —</option>";
      const customers = Array.isArray(State?.data?.customers) ? State.data.customers : [];
      customers.forEach(c => {
        const name = safeTrim(c?.payload?.name || c?.name || "");
        const id   = safeTrim(c?.id || "");
        if(!name) return;
        const opt = document.createElement("option");
        opt.value = id;
        opt.textContent = name;
        sel.appendChild(opt);
      });
    },

    // ── save ─────────────────────────────────────────
    async save(){
      if(this._saving) return;
      const type = this.selectedType;
      if(!type){ this.showError("יש לבחור סוג תזכורת"); return; }

      const dateVal = safeTrim(this.els.dateInput?.value);
      const timeVal = safeTrim(this.els.timeInput?.value);
      if(!dateVal || !timeVal){ this.showError("יש לבחור תאריך ושעה"); return; }

      const remindAt = new Date(`${dateVal}T${timeVal}:00`);
      if(isNaN(remindAt.getTime())){ this.showError("תאריך/שעה לא תקינים"); return; }

      let details = "";
      if(type === "callback"){
        details = safeTrim(this.els.callbackNote?.value) || "חזרה ללקוח";
      } else if(type === "documents"){
        details = safeTrim(this.els.docsList?.value);
        if(!details){ this.showError("יש לרשום את המסמכים"); return; }
      } else if(type === "missing"){
        details = safeTrim(this.els.missingList?.value);
        if(!details){ this.showError("יש לרשום את החוסרים"); return; }
      }

      const customerId = safeTrim(this.els.customerSel?.value) || null;
      const customerName = customerId
        ? (this.els.customerSel?.options[this.els.customerSel.selectedIndex]?.text || "")
        : "";

      const row = {
        id:            this.editingId || ("rem_" + Date.now() + "_" + Math.random().toString(16).slice(2)),
        agent_id:      this.agentKey(),
        type,
        details,
        remind_at:     remindAt.toISOString(),
        customer_id:   customerId,
        customer_name: customerName || null,
        is_done:       false,
        created_at:    nowISO(),
        snoozed_until: null,
      };
      // lead_id נשמר רק בזיכרון (לא נשלח ל-Supabase כי העמודה לא קיימת בסכמה)
      const leadId = this._pendingLeadId || null;

      this._saving = true;
      this.els.saveBtn.textContent = "שומר...";
      try {
        await this.upsertReminder(row);
        // צמד lead_id רק בזיכרון אחרי שמירה מוצלחת
        row.lead_id = leadId;
        if(!this.editingId){
          this.reminders.push(row);
        } else {
          const idx = this.reminders.findIndex(r => r.id === row.id);
          if(idx >= 0) this.reminders[idx] = row;
        }
        this.reminders.sort((a,b) => new Date(a.remind_at) - new Date(b.remind_at));
        this.updateBadge();
        this.resetForm();
        this.showStep("list");
        this.renderList();
      } catch(e){
        this.showError("שגיאה בשמירה: " + (e?.message || String(e)));
        console.error("[ReminderUI] save error", e);
      } finally {
        this._saving = false;
        if(this.els.saveBtn) this.els.saveBtn.textContent = "שמור תזכורת";
      }
    },

    showError(msg){ if(this.els.errorBox) this.els.errorBox.textContent = msg; },

    resetForm(){
      this.selectedType = "";
      this.editingId = null;
      this._pendingLeadId = null;
      if(this.els.callbackNote) this.els.callbackNote.value = "";
      if(this.els.docsList)     this.els.docsList.value = "";
      if(this.els.missingList)  this.els.missingList.value = "";
      if(this.els.customerSel)  this.els.customerSel.value = "";
      if(this.els.dateInput)    this.els.dateInput.value = "";
      if(this.els.timeInput)    this.els.timeInput.value = "";
      if(this.els.errorBox)     this.els.errorBox.textContent = "";
      this.els.typeCards?.forEach(c => c.classList.remove("is-selected"));
    },

    // ── render list ──────────────────────────────────
    renderList(){
      const list = this.els.list;
      if(!list) return;
      list.innerHTML = "";
      const open = this.reminders.filter(r => !r.is_done);
      if(!open.length){
        if(this.els.listEmpty) this.els.listEmpty.hidden = false;
        return;
      }
      if(this.els.listEmpty) this.els.listEmpty.hidden = true;
      const now = Date.now();
      open.forEach(r => {
        const dt = new Date(r.remind_at);
        const overdue = dt.getTime() < now;
        const row = document.createElement("div");
        row.className = "giReminderRow" + (overdue ? " is-overdue" : "");
        row.innerHTML = `
          <div class="giReminderRow__icon">${this.ICONS[r.type] || "🔔"}</div>
          <div class="giReminderRow__body">
            <div class="giReminderRow__type">${this.LABELS[r.type] || r.type}</div>
            <div class="giReminderRow__text">${this._escHtml(r.details)}</div>
            <div class="giReminderRow__meta">
              <span class="giReminderRow__time">${this._formatDt(dt)}</span>
              ${r.customer_name ? `<span class="giReminderRow__customer">👤 ${this._escHtml(r.customer_name)}</span>` : ""}
              ${overdue ? "<span style='color:#d7204a;font-weight:700'>פג תוקף</span>" : ""}
            </div>
          </div>
          <div class="giReminderRow__actions">
            <button class="giReminderRow__btn giReminderRow__btn--done" title="בוצע" data-id="${r.id}" data-action="done">✓</button>
            <button class="giReminderRow__btn giReminderRow__btn--delete" title="מחק" data-id="${r.id}" data-action="delete">🗑</button>
          </div>
        `;
        list.appendChild(row);
      });

      list.querySelectorAll("[data-action]").forEach(btn => {
        on(btn, "click", async () => {
          const id  = btn.dataset.id;
          const act = btn.dataset.action;
          if(act === "done")   await this.markDone(id);
          if(act === "delete") await this.deleteReminder(id);
        });
      });
    },

    _escHtml(str){
      return String(str ?? "")
        .replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;")
        .replace(/"/g,"&quot;");
    },

    _formatDt(dt){
      if(!(dt instanceof Date) || isNaN(dt)) return "";
      const days = ["ראשון","שני","שלישי","רביעי","חמישי","שישי","שבת"];
      const d = dt.getDate().toString().padStart(2,"0");
      const m = (dt.getMonth()+1).toString().padStart(2,"0");
      const y = dt.getFullYear();
      const hh = dt.getHours().toString().padStart(2,"0");
      const mm = dt.getMinutes().toString().padStart(2,"0");
      return `יום ${days[dt.getDay()]} ${d}/${m}/${y} בשעה ${hh}:${mm}`;
    },

    // ── due reminders check ──────────────────────────
    checkDueReminders(){
      if(!Auth.current) return;
      const now = Date.now();
      this.reminders.filter(r => !r.is_done).forEach(r => {
        const snoozedUntil = r.snoozed_until ? new Date(r.snoozed_until).getTime() : 0;
        const remindAt = new Date(r.remind_at).getTime();
        const already  = r._alerted;
        if(remindAt <= now && !already && (!snoozedUntil || now >= snoozedUntil)){
          r._alerted = true;
          this.alertQueue.push(r);
        }
      });
      if(!this.alertActive && this.alertQueue.length) this.showNextAlert();
    },

    showNextAlert(){
      if(!this.alertQueue.length){ this.alertActive = false; return; }
      this.alertActive = true;
      const r = this.alertQueue[0];
      if(this.els.alertIcon)    this.els.alertIcon.textContent   = this.ICONS[r.type] || "🔔";
      if(this.els.alertTitle)   this.els.alertTitle.textContent  = this.LABELS[r.type] || "תזכורת";
      if(this.els.alertText)    this.els.alertText.textContent   = r.details;
      if(this.els.alertCustomer) this.els.alertCustomer.textContent = r.customer_name ? `👤 ${r.customer_name}` : "";
      if(this.els.alertTime)    this.els.alertTime.textContent   = this._formatDt(new Date(r.remind_at));
      // הצג כפתור "פתח ליד" רק אם יש lead_id תואם
      if(this.els.alertOpenLead){
        const hasLead = !!(r.lead_id && (CampaignLeadsStore?.leads || []).some(l => String(l.id) === String(r.lead_id)));
        this.els.alertOpenLead.style.display = hasLead ? "" : "none";
      }
      this.els.alert?.classList.remove("is-hidden");
      this._playAlertSound();
      this._sendBrowserNotification(r);
    },

    dismissAlert(markDone){
      if(!this.alertQueue.length) return;
      const r = this.alertQueue.shift();
      this.els.alert?.classList.add("is-hidden");
      if(markDone) this.markDone(r.id);
      setTimeout(() => {
        if(this.alertQueue.length) this.showNextAlert();
        else this.alertActive = false;
      }, 400);
    },

    snoozeAlert(){
      if(!this.alertQueue.length) return;
      const r = this.alertQueue.shift();
      r._alerted = false;
      r.snoozed_until = new Date(Date.now() + 10 * 60 * 1000).toISOString();
      this.els.alert?.classList.add("is-hidden");
      // persist snooze
      Storage.restRequest(
        REMINDERS_TABLE + "?id=eq." + encodeURIComponent(r.id),
        { method: "PATCH", body: { snoozed_until: r.snoozed_until } }
      ).catch(()=>{});
      setTimeout(() => {
        if(this.alertQueue.length) this.showNextAlert();
        else this.alertActive = false;
      }, 400);
    },

    _playAlertSound(){
      try { playGiNotifySound(); } catch(_e) {}
    },

    _sendBrowserNotification(r){
      try {
        const title = this.LABELS[r.type] || "תזכורת";
        const body = safeTrim(r.details) + (r.customer_name ? `\n👤 ${r.customer_name}` : "");
        DesktopNotifications.notify(title, {
          body,
          tag: `gi-reminder-${r.id || r.remind_at || Date.now()}`,
          requireInteraction: true,
          onClick: () => {
            try { this.openModal(); } catch(_e) {}
          }
        });
      } catch(_){}
    },
  };

  const OfferCompareUI = {
    els: {},
    state: {
      customerName: "",
      letterText: "",
      letterHtml: "",
      hasResult: false
    },

    init(){
      this.els = {
        fab: $("#giOfferFab"),
        modal: $("#giOfferModal"),
        backdrop: $("#giOfferBackdrop"),
        close: $("#giOfferClose"),
        reset: $("#giOfferReset"),
        compare: $("#giOfferCompare"),
        customerName: $("#giOfferCustomerName"),
        addExisting: $("#giOfferAddExisting"),
        addOurs: $("#giOfferAddOurs"),
        existingRows: $("#giOfferExistingRows"),
        ourRows: $("#giOfferOurRows"),
        error: $("#giOfferError"),
        result: $("#giOfferResult"),
        copyText: $("#giOfferCopyText"),
        print: $("#giOfferPrint"),
        pdf: $("#giOfferPdf")
      };
      if(!this.els.fab || !this.els.modal) return;

      on(this.els.fab, "click", () => this.open());
      on(this.els.close, "click", () => this.close());
      on(this.els.backdrop, "click", () => this.close());
      on(this.els.reset, "click", () => this.reset());
      on(this.els.compare, "click", () => this.compareRows());
      on(this.els.addExisting, "click", () => this.addRow("existing"));
      on(this.els.addOurs, "click", () => this.addRow("ours"));
      on(this.els.existingRows, "click", (ev) => this.handleRemoveRow(ev));
      on(this.els.ourRows, "click", (ev) => this.handleRemoveRow(ev));
      on(this.els.copyText, "click", () => this.copyClientText());
      on(this.els.print, "click", () => this.printOffer());
      on(this.els.pdf, "click", () => this.exportPdf());
    },

    open(){
      this.reset();
      this.els.modal.setAttribute("aria-hidden", "false");
      this.els.modal.classList.add("is-open");
    },

    close(){
      this.els.modal.setAttribute("aria-hidden", "true");
      this.els.modal.classList.remove("is-open");
    },

    reset(){
      this.state = { customerName: "", letterText: "", letterHtml: "", hasResult: false };
      if(this.els.customerName) this.els.customerName.value = "";
      if(this.els.error) this.els.error.textContent = "";
      if(this.els.result){
        this.els.result.classList.add("is-hidden");
        this.els.result.innerHTML = "";
      }
      if(this.els.existingRows) this.els.existingRows.innerHTML = "";
      if(this.els.ourRows) this.els.ourRows.innerHTML = "";
      this.addRow("existing");
      this.addRow("ours");
    },

    getCompanyOptions(kind){
      const fromWizard = (kind === "existing"
        ? (Array.isArray(Wizard?.existingCompanies) ? Wizard.existingCompanies : [])
        : (Array.isArray(Wizard?.companies) ? Wizard.companies : [])
      ).map((v) => safeTrim(v)).filter(Boolean);
      const fallback = kind === "existing"
        ? ["איילון","הראל","כלל","מגדל","מנורה","הפניקס","הכשרה","AIG","ביטוח ישיר","9 מיליון"]
        : ["איילון","כלל","מגדל","מנורה","הפניקס","הכשרה","מדיקר"];
      const values = Array.from(new Set([...(fromWizard.length ? fromWizard : fallback), "אחר"]));
      return values.map((v) => `<option value="${escapeHtml(v)}">${escapeHtml(v)}</option>`).join("");
    },

    getProductOptions(){
      const fromWizard = (Array.isArray(Wizard?.insTypes) ? Wizard.insTypes : []).map((v) => safeTrim(v)).filter(Boolean);
      const fallback = ["בריאות","מחלות קשות","סרטן","אובדן כושר עבודה","ריסק","ריסק משכנתא"];
      const values = Array.from(new Set([...(fromWizard.length ? fromWizard : fallback), "אחר"]));
      return values.map((v) => `<option value="${escapeHtml(v)}">${escapeHtml(v)}</option>`).join("");
    },

    addRow(kind){
      const host = kind === "existing" ? this.els.existingRows : this.els.ourRows;
      if(!host) return;
      const row = document.createElement("div");
      row.className = "giOfferRow";
      const companyOptions = this.getCompanyOptions(kind);
      const productOptions = this.getProductOptions();
      row.innerHTML = [
        `<select class="input" data-field="company"><option value="">בחר חברה</option>${companyOptions}</select>`,
        `<select class="input" data-field="product"><option value="">בחר מוצר</option>${productOptions}</select>`,
        "<input class=\"input\" data-field=\"price\" type=\"number\" min=\"0\" step=\"0.01\" placeholder=\"מחיר חודשי\"/>",
        "<button class=\"btn giOfferRow__remove\" data-remove-offer-row type=\"button\" aria-label=\"הסר שורה\">✕</button>"
      ].join("");
      host.appendChild(row);
    },

    handleRemoveRow(ev){
      const btn = ev.target.closest("[data-remove-offer-row]");
      if(!btn) return;
      const row = btn.closest(".giOfferRow");
      const parent = row?.parentElement;
      if(!row || !parent) return;
      if(parent.children.length <= 1) return;
      row.remove();
    },

    readRows(kind){
      const host = kind === "existing" ? this.els.existingRows : this.els.ourRows;
      if(!host) return [];
      return $$(".giOfferRow", host).map((row) => {
        const company = safeTrim($("[data-field=\"company\"]", row)?.value);
        const product = safeTrim($("[data-field=\"product\"]", row)?.value);
        const priceRaw = safeTrim($("[data-field=\"price\"]", row)?.value).replace(",", ".");
        const price = Number(priceRaw);
        return { company, product, price: Number.isFinite(price) ? price : NaN };
      }).filter((item) => item.company || item.product || Number.isFinite(item.price));
    },

    compareRows(){
      if(this.els.error) this.els.error.textContent = "";
      if(this.els.result){
        this.els.result.classList.add("is-hidden");
        this.els.result.innerHTML = "";
      }

      const customerName = safeTrim(this.els.customerName?.value);
      const existing = this.readRows("existing");
      const ours = this.readRows("ours");

      if(!customerName){
        if(this.els.error) this.els.error.textContent = "יש להזין שם לקוח לפני ביצוע השוואה.";
        return;
      }
      if(!existing.length || !ours.length){
        if(this.els.error) this.els.error.textContent = "יש להזין לפחות שורה אחת בכל צד (קיים ומוצע).";
        return;
      }
      if(existing.some((row) => !Number.isFinite(row.price)) || ours.some((row) => !Number.isFinite(row.price))){
        if(this.els.error) this.els.error.textContent = "יש להזין מחיר תקין בכל שורה שהוזנה.";
        return;
      }

      const maxLen = Math.max(existing.length, ours.length);
      const rows = [];
      let totalExisting = 0;
      let totalOurs = 0;
      for(let i = 0; i < maxLen; i += 1){
        const oldRow = existing[i] || { company:"—", product:"—", price:0 };
        const newRow = ours[i] || { company:"—", product:"—", price:0 };
        const delta = oldRow.price - newRow.price;
        totalExisting += Number(oldRow.price || 0);
        totalOurs += Number(newRow.price || 0);
        rows.push({ oldRow, newRow, delta });
      }

      const monthlyDelta = totalExisting - totalOurs;
      const yearlyDelta = monthlyDelta * 12;
      const savingsLabel = monthlyDelta >= 0 ? "חיסכון" : "תוספת";
      const formatMoney = (value) => "₪" + Number(value || 0).toLocaleString("he-IL", { maximumFractionDigits: 2 });
      const deltaClass = monthlyDelta > 0 ? "giOfferResult__delta--good" : monthlyDelta < 0 ? "giOfferResult__delta--bad" : "giOfferResult__delta--same";
      const deltaWord = monthlyDelta > 0 ? "חיסכון" : monthlyDelta < 0 ? "תוספת" : "איזון";

      const detailRows = rows.map((entry, idx) => {
        const rowDelta = Number(entry.delta || 0);
        const rowDeltaClass = rowDelta > 0 ? "giOfferResult__delta--good" : rowDelta < 0 ? "giOfferResult__delta--bad" : "giOfferResult__delta--same";
        const rowDeltaText = (rowDelta > 0 ? "-" : rowDelta < 0 ? "+" : "") + formatMoney(Math.abs(rowDelta));
        return [
          "<tr>",
          `<td>${idx + 1}</td>`,
          `<td>${entry.oldRow.company} / ${entry.oldRow.product}</td>`,
          `<td>${formatMoney(entry.oldRow.price)}</td>`,
          `<td>${entry.newRow.company} / ${entry.newRow.product}</td>`,
          `<td>${formatMoney(entry.newRow.price)}</td>`,
          `<td class="${rowDeltaClass}">${rowDeltaText}</td>`,
          "</tr>"
        ].join("");
      }).join("");

      const letterText = [
        `לכבוד ${customerName},`,
        "",
        "להלן השוואת הצעה לביטוח:",
        `סה\"כ עלות ביטוחים קיימים: ${formatMoney(totalExisting)} לחודש`,
        `סה\"כ עלות בהצעה החדשה: ${formatMoney(totalOurs)} לחודש`,
        `${deltaWord} חודשי: ${formatMoney(Math.abs(monthlyDelta))}`,
        `${deltaWord} שנתי: ${formatMoney(Math.abs(yearlyDelta))}`,
        "",
        "נשמח להתקדם יחד ולעזור לך להשלים את התהליך."
      ].join("\n");

      const letterHtml = [
        `<div class="giOfferClientLetter__title">לכבוד ${escapeHtml(customerName)}</div>`,
        "<div class=\"giOfferClientLetter__body\">",
        "להלן השוואת הצעה לביטוח:<br>",
        `סה&quot;כ עלות ביטוחים קיימים: <strong>${formatMoney(totalExisting)}</strong> לחודש<br>`,
        `סה&quot;כ עלות בהצעה החדשה: <strong>${formatMoney(totalOurs)}</strong> לחודש<br>`,
        `${deltaWord} חודשי: <strong>${formatMoney(Math.abs(monthlyDelta))}</strong><br>`,
        `${deltaWord} שנתי: <strong>${formatMoney(Math.abs(yearlyDelta))}</strong><br><br>`,
        "נשמח להתקדם יחד ולעזור לך להשלים את התהליך.",
        "</div>"
      ].join("");

      this.state.customerName = customerName;
      this.state.letterText = letterText;
      this.state.letterHtml = letterHtml;
      this.state.hasResult = true;

      if(this.els.result){
        this.els.result.innerHTML = [
          "<div class=\"giOfferResult__totals\">",
          `<span class=\"giOfferResult__pill\">לקוח: ${customerName}</span>`,
          `<span class=\"giOfferResult__pill\">סה\"כ קיים: ${formatMoney(totalExisting)}</span>`,
          `<span class=\"giOfferResult__pill\">סה\"כ מוצע: ${formatMoney(totalOurs)}</span>`,
          `<span class=\"giOfferResult__pill ${deltaClass}\">${savingsLabel} חודשי: ${formatMoney(Math.abs(monthlyDelta))}</span>`,
          `<span class=\"giOfferResult__pill ${deltaClass}\">${savingsLabel} שנתי: ${formatMoney(Math.abs(yearlyDelta))}</span>`,
          "</div>",
          `<div class="giOfferClientLetter">${letterHtml}</div>`,
          "<table class=\"giOfferResult__table\">",
          "<thead><tr><th>#</th><th>קיים</th><th>מחיר קיים</th><th>מוצע</th><th>מחיר מוצע</th><th>פער</th></tr></thead>",
          `<tbody>${detailRows}</tbody>`,
          "</table>"
        ].join("");
        this.els.result.classList.remove("is-hidden");
      }
    },

    async copyClientText(){
      if(!this.state.hasResult || !this.state.letterText){
        if(this.els.error) this.els.error.textContent = "צריך לבצע השוואה לפני העתקת נוסח ללקוח.";
        return;
      }
      if(this.els.error) this.els.error.textContent = "";
      try {
        await navigator.clipboard.writeText(this.state.letterText);
        if(typeof toast === "function") toast("נוסח ההצעה הועתק", "אפשר להדביק ולשלוח ללקוח");
      } catch(_e){
        if(this.els.error) this.els.error.textContent = "לא הצלחתי להעתיק אוטומטית. אפשר לסמן ולהעתיק ידנית.";
      }
    },

    printOffer(){
      if(!this.state.hasResult || !this.els.result || this.els.result.classList.contains("is-hidden")){
        if(this.els.error) this.els.error.textContent = "צריך לבצע השוואה לפני הפקת הצעה.";
        return;
      }
      if(this.els.error) this.els.error.textContent = "";
      const win = window.open("", "_blank", "width=1040,height=820");
      if(!win) return;
      const docHtml = this.buildDocumentHtml({ mode: "print" });
      win.document.write(`<!doctype html><html lang="he" dir="rtl"><head><meta charset="utf-8"><title>הצעה ללקוח</title>
<meta name="viewport" content="width=device-width,initial-scale=1">
<link href="https://fonts.googleapis.com/css2?family=Rubik:wght@400;500;700;800;900&display=swap" rel="stylesheet"/>
<style>
  body{margin:0;font-family:Rubik,Arial,sans-serif;background:#fff;color:#0b1f4a}
  .wrap{padding:22px}
  ${this._getOfferDocPrintCss()}
</style></head><body><div class="wrap">${docHtml}</div></body></html>`);
      win.document.close();
      setTimeout(() => {
        try { win.focus(); win.print(); } catch(_e) {}
      }, 120);
    },

    _getOfferDocPrintCss(){
      return `
        .giOfferDoc{background:#fff}
        .giOfferDoc__head{display:flex;align-items:flex-start;justify-content:space-between;gap:14px;padding-bottom:12px;border-bottom:1px solid rgba(15,23,42,.10);margin-bottom:12px}
        .giOfferDoc__brand{display:flex;align-items:center;gap:10px}
        .giOfferDoc__logo{width:46px;height:46px;border-radius:12px;border:1px solid rgba(15,23,42,.10);object-fit:contain;background:#fff}
        .giOfferDoc__brandName{font-weight:900}
        .giOfferDoc__brandSub{font-size:12px;color:rgba(15,23,42,.70);font-weight:700}
        .giOfferDoc__meta{text-align:left;font-size:12px;color:rgba(15,23,42,.70);font-weight:700;line-height:1.5}
        .giOfferDoc__title{font-size:18px;font-weight:900;margin:2px 0 8px}
        .giOfferDoc__to{font-size:14px;font-weight:900;margin:0 0 10px}
        .giOfferDoc__note{font-size:13px;color:rgba(15,23,42,.76);line-height:1.6;margin-bottom:12px}
        .giOfferDoc__summary{display:flex;gap:10px;flex-wrap:wrap;margin:10px 0 12px}
        .giOfferDoc__pill{background:#f7faff;border:1px solid rgba(42,92,245,.20);border-radius:999px;padding:7px 10px;font-size:12px;font-weight:800}
        .giOfferDoc__pill--good{border-color:rgba(15,157,109,.28);color:#0f9d6d;background:rgba(15,157,109,.06)}
        .giOfferDoc__pill--bad{border-color:rgba(215,32,74,.26);color:#d7204a;background:rgba(215,32,74,.05)}
        .giOfferDoc__table{width:100%;border-collapse:collapse;border:1px solid rgba(15,23,42,.10);border-radius:12px;overflow:hidden}
        .giOfferDoc__table th,.giOfferDoc__table td{padding:10px 8px;border-bottom:1px solid rgba(15,23,42,.08);font-size:13px;text-align:right}
        .giOfferDoc__table th{background:linear-gradient(180deg, rgba(235,242,255,.90), rgba(255,255,255,.86));font-size:12px;color:rgba(15,23,42,.76);font-weight:900}
        /* fallback if replacement didn't hit */
        .giOfferResult__table{width:100%;border-collapse:collapse;border:1px solid rgba(15,23,42,.10);border-radius:12px;overflow:hidden}
        .giOfferResult__table th,.giOfferResult__table td{padding:10px 8px;border-bottom:1px solid rgba(15,23,42,.08);font-size:13px;text-align:right}
        .giOfferResult__table th{background:linear-gradient(180deg, rgba(235,242,255,.90), rgba(255,255,255,.86));font-size:12px;color:rgba(15,23,42,.76);font-weight:900}
        .giOfferDoc__foot{margin-top:12px;padding-top:10px;border-top:1px solid rgba(15,23,42,.10);display:flex;justify-content:space-between;gap:10px;flex-wrap:wrap;font-size:12px;color:rgba(15,23,42,.70);font-weight:700}
        @page { size: A4; margin: 14mm; }
      `;
    },

    buildDocumentHtml(options = {}){
      const customerName = safeTrim(this.state.customerName);
      const generatedAt = new Date().toLocaleString("he-IL");
      const agentName = safeTrim(Auth?.current?.name) || "";
      const agentRole = safeTrim(Auth?.current?.roleLabel || "");
      const mode = safeTrim(options.mode) || "pdf";

      const resultRoot = this.els.result;
      const pills = resultRoot ? Array.from(resultRoot.querySelectorAll(".giOfferResult__pill")).map((el) => safeTrim(el.textContent)).filter(Boolean) : [];
      const tableHtml = resultRoot ? (resultRoot.querySelector("table")?.outerHTML || "") : "";

      const logoSrc = "./logo-login-clean.png";
      const title = "הצעה לביטוח";

      const deltaMonthly = pills.find(t => t.includes("חודשי")) || "";
      const deltaCls = deltaMonthly.includes("חיסכון") ? "giOfferDoc__pill--good" : (deltaMonthly.includes("תוספת") ? "giOfferDoc__pill--bad" : "");

      const summaryHtml = pills.map((t) => {
        const cls = t.includes("חודשי") || t.includes("שנתי") ? deltaCls : "";
        return `<span class="giOfferDoc__pill ${cls}">${escapeHtml(t)}</span>`;
      }).join("");

      const note = (mode === "pdf")
        ? "מסמך זה הופק אוטומטית מתוך מערכת GEMEL INVEST."
        : "מסמך זה הופק אוטומטית מתוך מערכת GEMEL INVEST (תצוגת הדפסה).";

      return [
        `<section class="giOfferDoc">`,
          `<div class="giOfferDoc__head">`,
            `<div class="giOfferDoc__brand">`,
              `<img class="giOfferDoc__logo" src="${escapeHtml(logoSrc)}" alt="GEMEL INVEST">`,
              `<div class="giOfferDoc__brandText">`,
                `<div class="giOfferDoc__brandName">GEMEL INVEST</div>`,
                `<div class="giOfferDoc__brandSub">הצעה והשוואת מחירים</div>`,
              `</div>`,
            `</div>`,
            `<div class="giOfferDoc__meta">`,
              `<div>תאריך: ${escapeHtml(generatedAt)}</div>`,
              `${agentName ? `<div>נציג: ${escapeHtml(agentName)}${agentRole ? ` (${escapeHtml(agentRole)})` : ""}</div>` : ``}`,
            `</div>`,
          `</div>`,
          `<div class="giOfferDoc__title">${escapeHtml(title)}</div>`,
          `<div class="giOfferDoc__to">לכבוד ${escapeHtml(customerName || "הלקוח")}</div>`,
          `<div class="giOfferDoc__note">${escapeHtml(note)}</div>`,
          `<div class="giOfferDoc__summary">${summaryHtml}</div>`,
          tableHtml ? tableHtml.replace("giOfferResult__table", "giOfferDoc__table") : "",
          `<div class="giOfferDoc__foot">`,
            `<div>לכל שאלה נשמח לסייע.</div>`,
            `<div>GEMEL INVEST • CRM</div>`,
          `</div>`,
        `</section>`
      ].join("");
    },

    async exportPdf(){
      if(!this.state.hasResult || !this.els.result || this.els.result.classList.contains("is-hidden")){
        if(this.els.error) this.els.error.textContent = "צריך לבצע השוואה לפני הורדת PDF.";
        return;
      }
      if(typeof window.html2pdf !== "function"){
        if(this.els.error) this.els.error.textContent = "html2pdf לא נטען. בדוק שהספרייה קיימת בעמוד.";
        return;
      }
      if(this.els.error) this.els.error.textContent = "";

      const container = document.createElement("div");
      container.setAttribute("dir", "rtl");
      container.setAttribute("lang", "he");
      container.style.position = "fixed";
      // חשוב: לא להשתמש ב-opacity:0 / z-index:-1, כי זה גורם ל-html2canvas
      // לעיתים להפיק דף ריק.
      container.style.left = "-20000px";
      container.style.top = "0";
      container.style.width = "794px"; // ~A4 at 96dpi
      container.style.background = "#fff";
      container.style.opacity = "1";
      container.style.pointerEvents = "none";
      container.style.zIndex = "0";
      container.style.display = "block";
      container.innerHTML = [
        "<style>",
        "  body{margin:0;font-family:Rubik,Arial,sans-serif;background:#fff;color:#0b1f4a}",
        this._getOfferDocPrintCss(),
        "</style>",
        this.buildDocumentHtml({ mode: "pdf" })
      ].join("\n");
      document.body.appendChild(container);

      const customerName = safeTrim(this.state.customerName) || "הצעה";
      const safeName = customerName.replace(/[\\/:*?\"<>|]+/g, "-").slice(0, 80);
      const filename = `${safeName}.pdf`;

      try {
        // Ensure fonts/images are ready before capture (prevents blank PDFs)
        try { await document.fonts?.ready; } catch(_e) {}
        await new Promise((r) => requestAnimationFrame(() => r()));
        await new Promise((r) => requestAnimationFrame(() => r()));
        const imgs = Array.from(container.querySelectorAll("img"));
        if(imgs.length){
          await Promise.all(imgs.map((img) => new Promise((resolve) => {
            if(img.complete) return resolve();
            img.onload = () => resolve();
            img.onerror = () => resolve();
          })));
        }

        const opts = {
          margin:       [10, 10, 10, 10],
          filename,
          image:        { type: "jpeg", quality: 0.98 },
          html2canvas:  { scale: 3, useCORS: true, backgroundColor: "#ffffff", logging: false },
          jsPDF:        { unit: "mm", format: "a4", orientation: "portrait" },
          pagebreak:    { mode: ["avoid-all", "css", "legacy"] }
        };
        await window.html2pdf().set(opts).from(container).save();
        if(typeof toast === "function") toast("PDF הופק בהצלחה", filename);
      } catch(err){
        console.error("OFFER_PDF_EXPORT_FAILED", err);
        if(this.els.error) this.els.error.textContent = "לא הצלחתי להפיק PDF. נסה שוב או השתמש בתצוגת הדפסה.";
      } finally {
        try { container.remove(); } catch(_e) {}
      }
    }
  };

const CampaignLeadsStore = {
    leads: [],
    tableReady: true,
    lastError: "",
    customerFieldsInDb: null,
    _customerFieldsProbeDone: false,
    _fetchAllPromise: null,
    _fetchAllScope: "",
    pendingRemoteSaveIds: new Set(),
    _recentSaveGraceUntil: new Map(),
    RECENT_SAVE_GRACE_MS: 3 * 60 * 1000,

    _noteRecentSave(id){
      const sid = safeTrim(id);
      if(!sid) return;
      this._recentSaveGraceUntil.set(sid, Date.now() + this.RECENT_SAVE_GRACE_MS);
    },

    _clearRecentSaveGrace(id){
      const sid = safeTrim(id);
      if(sid) this._recentSaveGraceUntil.delete(sid);
    },

    _shouldRetainRecentSave(id){
      const sid = safeTrim(id);
      if(!sid) return false;
      const until = this._recentSaveGraceUntil.get(sid);
      if(!until) return false;
      if(Date.now() > until){
        this._recentSaveGraceUntil.delete(sid);
        return false;
      }
      return true;
    },

    _campaignLeadFetchHasInbox(){
      try { return !!(Auth?.canAccessCampaignLeadsInbox?.()); } catch(_e) { return false; }
    },

    _loadInboxCache(){
      if(!this._campaignLeadFetchHasInbox()) return [];
      try {
        const raw = localStorage.getItem(GI_CAMPAIGN_LEADS_INBOX_CACHE_KEY);
        if(!raw) return [];
        const parsed = JSON.parse(raw);
        if(!Array.isArray(parsed)) return [];
        const cutoff = Date.now() - GI_CAMPAIGN_LEADS_INBOX_CACHE_MAX_AGE_MS;
        return parsed
          .map((row, idx) => normalizeCampaignLead(row, idx))
          .filter((lead) => {
            if(!safeTrim(lead?.id)) return false;
            if(!campaignLeadIsOpenInInbox(lead.status)) return false;
            const ms = parseCampaignLeadStampMs(lead.updatedAt || lead.createdAt);
            return !ms || ms >= cutoff;
          });
      } catch(_e) {
        return [];
      }
    },

    _saveInboxCache(leads){
      if(!this._campaignLeadFetchHasInbox()) return;
      try {
        const list = (Array.isArray(leads) ? leads : [])
          .filter((lead) => safeTrim(lead?.id) && campaignLeadIsOpenInInbox(lead.status))
          .slice(0, GI_CAMPAIGN_LEADS_INBOX_CACHE_MAX_ROWS);
        localStorage.setItem(GI_CAMPAIGN_LEADS_INBOX_CACHE_KEY, JSON.stringify(list));
      } catch(_e) {}
    },

    _clearInboxCache(){
      try { localStorage.removeItem(GI_CAMPAIGN_LEADS_INBOX_CACHE_KEY); } catch(_e) {}
    },

    _mergeCampaignLeadFetchResults(previous, fetched, scope){
      const previousById = new Map(previous.map((l) => [String(l.id), l]));
      const fetchedIds = new Set(fetched.map((l) => String(l.id)));
      const pending = previous.filter((l) => this.pendingRemoteSaveIds.has(String(l.id)) && !fetchedIds.has(String(l.id)));
      const hasInbox = this._campaignLeadFetchHasInbox();
      const myIds = new Set([...getCampaignLeadSessionAgentIds()].filter(Boolean).map((id) => String(id)));
      const retained = previous.filter((l) => {
        const id = String(l.id);
        if(fetchedIds.has(id)) return false;
        if(this.pendingRemoteSaveIds.has(id)) return false;
        if(this._shouldRetainRecentSave(id)) return true;
        // inbox (סוקרת/מנהל/אדמין): טעינה חלקית לעולם לא מוחקת לידים מקומיים — רק scope "all" מרענן.
        if(hasInbox) return true;
        if(scope === "mine"){
          const aid = String(l.assignedAgentId || "");
          if(myIds.has(aid)) return false;
          return true;
        }
        return false;
      });
      const mergedFetched = fetched.map((lead) => {
        const local = previousById.get(String(lead.id));
        if(!local) return lead;
        const keepLocal = this.pendingRemoteSaveIds.has(String(lead.id)) || this._shouldRetainRecentSave(lead.id);
        if(keepLocal) return normalizeCampaignLead({ ...lead, ...local });
        return normalizeCampaignLead({
          ...lead,
          assignedAgentId: safeTrim(lead.assignedAgentId) || local.assignedAgentId,
          assignedAgentName: safeTrim(lead.assignedAgentName) || local.assignedAgentName,
          customerName: safeTrim(lead.customerName) || local.customerName,
          status: safeTrim(lead.status) || local.status
        });
      });
      mergedFetched.forEach((l) => this._clearRecentSaveGrace(l.id));
      return [...pending, ...retained, ...mergedFetched];
    },

    resolveFetchScope(options = {}){
      if(options.scope === "all" || options.scope === "mine") return options.scope;
      return Auth.canAccessCampaignLeadsInbox() ? "all" : "mine";
    },

    async probeCustomerFieldsInDb(force = false){
      if(this._customerFieldsProbeDone && !force) return this.customerFieldsInDb;
      this._customerFieldsProbeDone = true;
      try {
        const client = Storage.getClient();
        const { error } = await client
          .from(SUPABASE_TABLES.campaignLeads)
          .select("id_number,birth_date,id_issue_date")
          .limit(0);
        this.customerFieldsInDb = !error;
      } catch(_e) {
        this.customerFieldsInDb = false;
      }
      return this.customerFieldsInDb;
    },

    /* GI-PERF 2026-07-31 (שלב ו'): מזין את הרשימה מהמטמון המקומי כדי שהמסך
       יוכל להיצבע לפני שהרשת עונה. אותו מטמון כבר שימש כ-mergeBase בתוך
       _fetchAllImpl — רק אף אחד לא צייר ממנו. */
    hydrateFromCacheIfEmpty(){
      if(Array.isArray(this.leads) && this.leads.length) return false;
      const cached = this._loadInboxCache();
      if(!cached.length) return false;
      this.leads = cached.slice().sort((a, b) => String(b.createdAt).localeCompare(String(a.createdAt)));
      return true;
    },

    async fetchAll(options = {}){
      const scope = this.resolveFetchScope(options);
      if(this._fetchAllPromise && this._fetchAllScope === scope) return this._fetchAllPromise;
      this._fetchAllScope = scope;
      this._fetchAllPromise = this._fetchAllImpl(scope).finally(() => {
        if(this._fetchAllScope === scope){
          this._fetchAllPromise = null;
          this._fetchAllScope = "";
        }
      });
      return this._fetchAllPromise;
    },

    async _fetchAllImpl(scope){
      return GiPerf.runAsync("campaignLeads:fetchAll", () => this.__fetchAllImpl(scope));
    },

    async __fetchAllImpl(scope){
      this.lastError = "";
      await this.probeCustomerFieldsInDb();
      const res = await Storage.loadCampaignLeadRows(scope, "*");
      if(!res.ok){
        this.tableReady = false;
        this.lastError = res.error || "טעינת לידים נכשלה";
        return { ok: false, error: this.lastError };
      }
      this.tableReady = true;
      const previous = this.leads || [];
      const cacheSeed = previous.length ? [] : this._loadInboxCache();
      const mergeBase = previous.length ? previous : cacheSeed;
      const fetched = (res.data || []).map((row, idx) => mapCampaignLeadFromDb(row, idx)).filter(Boolean);
      this.leads = this._mergeCampaignLeadFetchResults(mergeBase, fetched, scope);
      this.leads.sort((a, b) => String(b.createdAt).localeCompare(String(a.createdAt)));
      this._saveInboxCache(this.leads);
      return { ok: true, leads: this.leads };
    },

    applyLocal(lead){
      const normalized = normalizeCampaignLead(lead);
      const idx = this.leads.findIndex((l) => String(l.id) === String(normalized.id));
      if(idx >= 0) this.leads[idx] = normalized;
      else this.leads.unshift(normalized);
      this._noteRecentSave(normalized.id);
      this._saveInboxCache(this.leads);
      return normalized;
    },

    removeLocal(id){
      const sid = safeTrim(id);
      if(!sid) return;
      this._clearRecentSaveGrace(sid);
      this.leads = this.leads.filter((l) => String(l.id) !== sid);
      this._saveInboxCache(this.leads);
    },

    async persistRemote(lead, options = {}){
      const normalized = normalizeCampaignLead(lead);
      const existing = this.leads.find((l) => String(l.id) === String(normalized.id));
      if(!isValidIsraeliPhone(normalized.phone)){
        if(existing && isValidIsraeliPhone(existing.phone)) normalized.phone = existing.phone;
        else return { ok: false, error: "מספר טלפון לא תקין" };
      }
      normalized.updatedAt = nowISO();
      normalized.updatedByName = safeTrim(Auth?.current?.name) || normalized.updatedByName;
      if(!safeTrim(normalized.createdByName)){
        normalized.createdByName = safeTrim(Auth?.current?.name) || "מערכת";
      }
      if(this.customerFieldsInDb === null){
        await this.probeCustomerFieldsInDb();
      }
      const saveOptions = {
        retries: Math.max(1, Number(options.retries || 1) || 1),
        timeoutMs: Math.max(3000, Number(options.timeoutMs || 8000) || 8000)
      };
      let row = mapCampaignLeadToDb(normalized);
      let save = await Storage.upsertSingleRow(SUPABASE_TABLES.campaignLeads, row, saveOptions);
      if(!save.ok && isCampaignLeadCustomerFieldsSchemaError(save.error)){
        this.customerFieldsInDb = false;
        row = mapCampaignLeadToDb(normalized, { includeCustomerFields: false });
        save = await Storage.upsertSingleRow(SUPABASE_TABLES.campaignLeads, row, saveOptions);
      } else if(save.ok && this.customerFieldsInDb === null){
        this.customerFieldsInDb = true;
      }
      if(!save.ok) return { ok: false, error: formatCampaignLeadPersistError(save.error) };
      this.applyLocal(normalized);
      return { ok: true, lead: normalized };
    },

    async upsert(lead){
      const normalized = normalizeCampaignLead(lead);
      const existing = this.leads.find((l) => String(l.id) === String(normalized.id));
      if(!isValidIsraeliPhone(normalized.phone)){
        if(existing && isValidIsraeliPhone(existing.phone)) normalized.phone = existing.phone;
        else return { ok: false, error: "מספר טלפון לא תקין" };
      }
      normalized.updatedAt = nowISO();
      normalized.updatedByName = safeTrim(Auth?.current?.name) || normalized.updatedByName;
      if(!safeTrim(normalized.createdByName)){
        normalized.createdByName = safeTrim(Auth?.current?.name) || "מערכת";
      }
      this.applyLocal(normalized);
      return this.persistRemote(normalized);
    },

    async createInboundCallLead(phone, campaignLineId){
      const line = getCampaignLines().find((c) => String(c.id) === String(campaignLineId)) || getDefaultCampaignLine();
      const stamp = nowISO();
      return this.upsert({
        id: "cl_" + Date.now().toString(36) + Math.random().toString(16).slice(2, 6),
        phone: normalizePhoneValue(phone),
        customerName: "",
        description: "",
        campaignId: line.id,
        campaignLabel: line.label,
        assignedAgentId: "",
        assignedAgentName: "",
        status: "new",
        source: "call",
        createdByName: "מרכזיה",
        updatedByName: "מרכזיה",
        createdAt: stamp,
        updatedAt: stamp
      });
    }
  };

  function normalizeDailyReportAgentKey(value){
    return safeTrim(value).replace(/\s+/g, " ");
  }

  function findDailyReportHeaderCol(headers, matchers){
    const list = Array.isArray(headers) ? headers : [];
    const needles = (Array.isArray(matchers) ? matchers : [matchers])
      .map((m) => safeTrim(m).toLowerCase())
      .filter(Boolean);
    for(const needle of needles){
      const exactIdx = list.findIndex((h) => safeTrim(h).toLowerCase() === needle);
      if(exactIdx >= 0) return exactIdx;
    }
    for(const needle of needles){
      const idx = list.findIndex((h) => safeTrim(h).toLowerCase().includes(needle));
      if(idx >= 0) return idx;
    }
    return -1;
  }

  let _dailyReportColIdxReport = null;
  let _dailyReportColIdxValue = null;
  function getDailyReportColumnIndexes(report){
    if(report && report === _dailyReportColIdxReport && _dailyReportColIdxValue){
      return _dailyReportColIdxValue;
    }
    const headers = Array.isArray(report?.headerRow) ? report.headerRow : [];
    const value = {
      status: findDailyReportHeaderCol(headers, ["סטטוס הצעה", "סטטוס"]),
      team: findDailyReportHeaderCol(headers, ["צוות"]),
      plan: findDailyReportHeaderCol(headers, ["שם תוכנית", "תוכנית"]),
      premium: findDailyReportHeaderCol(headers, ["פרמיה חודשית", "פרמיה לחודש", "סכום פרמיה", "פרמיה נטו", "פרמיה"]),
      issuedPremium: findDailyReportHeaderCol(headers, ["פרמיה הפקה"]),
      name: findDailyReportHeaderCol(headers, ["שם לקוח", "שם מלא", "שם", "לקוח"]),
      company: findDailyReportHeaderCol(headers, ["חברה", "חברת ביטוח", "מבטח"])
    };
    if(report){
      _dailyReportColIdxReport = report;
      _dailyReportColIdxValue = value;
    }
    return value;
  }

  function getDailyReportIssuedPremiumValue(row, cols){
    if(!row || !cols || cols.issuedPremium < 0) return 0;
    return parseDailyReportMoney(getDailyReportCell(row, cols.issuedPremium));
  }

  function parseDailyReportMoney(value){
    const raw = safeTrim(value);
    if(!raw || raw === "—") return 0;
    const cleaned = raw.replace(/[₪\s]/g, "").replace(/,/g, "");
    const n = Number(cleaned);
    return Number.isFinite(n) && n > 0 ? Math.round(n * 100) / 100 : 0;
  }

  // GI-CANCEL-STATS: זיהוי עמודת שנת הביטול.
  // זהירות: המחרוזת "שנה" מוכלת גם ב-"פרמיה שנתית", ולכן חיפוש לפי הכלה יתפוס
  // את עמודת הכסף במקום את השנה. לכן כאן עובדים בהתאמה מדויקת בלבד,
  // ובגיליון "מדיקר" הכותרת היא "שנה" ולא "ביטול שנה".
  function findCancellationYearCol(headers){
    const list = Array.isArray(headers) ? headers : [];
    const exact = ["ביטול שנה", "שנת ביטול", "שנה"];
    for(const needle of exact){
      const idx = list.findIndex((h) => safeTrim(h).toLowerCase() === needle);
      if(idx >= 0) return idx;
    }
    return -1;
  }

  // "-" בעמודת השנה = שנה שישית ומעלה = כללי.
  const CANCEL_YEAR_GENERAL_KEY = "כללי";
  const CANCEL_YEAR_ORDER = Object.freeze(["א", "ב", "ג", "ד", "ה", CANCEL_YEAR_GENERAL_KEY]);

  function normalizeCancellationYear(value){
    const raw = safeTrim(value);
    if(!raw) return "";
    if(/^[-–—]+$/.test(raw)) return CANCEL_YEAR_GENERAL_KEY;
    const letter = raw.replace(/['"׳״\s]/g, "");
    if(CANCEL_YEAR_ORDER.includes(letter)) return letter;
    const asNum = Number(letter);
    if(Number.isFinite(asNum) && asNum >= 1){
      if(asNum >= 6) return CANCEL_YEAR_GENERAL_KEY;
      return ["א", "ב", "ג", "ד", "ה"][asNum - 1] || "";
    }
    return letter || "";
  }

  // GI-CANCEL-STATS: סיווג סטטוסי דוח הביטולים.
  // "ביטול חלקי" ו-"בוטל חלקי" נשמרים בנפרד לפי החלטה פתוחה.
  // כדי לאחד אותם בעתיד — להעביר את שניהם לאותו key כאן, וזה מספיק.
  const CANCEL_STATUS_KEYS = Object.freeze({
    cancelled:       { key: "cancelled",       label: "בוטל",              tone: "danger"  },
    cancelledPartial:{ key: "cancelledPartial", label: "בוטל חלקי",         tone: "danger"  },
    partial:         { key: "partial",          label: "ביטול חלקי",        tone: "warn"    },
    awaitingRetain:  { key: "awaitingRetain",   label: "ממתין לשימור",      tone: "info"    },
    retained:        { key: "retained",         label: "שומר",              tone: "success" }
  });

  function classifyCancellationStatus(value){
    const n = normalizeDailyReportAgentToken(value);
    if(!n) return "";
    if(n === "בוטל") return "cancelled";
    if(n === "בוטל חלקי") return "cancelledPartial";
    if(n === "ביטול חלקי") return "partial";
    if(n === "שומר" || n === "שומרה" || n === "נשמר") return "retained";
    if(n.includes("ממתין") && n.includes("שימור")) return "awaitingRetain";
    return "";
  }

  // הסטטוסים שנכנסים לשורת "סה״כ ביטולים".
  const CANCEL_TOTAL_KEYS = Object.freeze(["cancelled", "cancelledPartial", "partial"]);

  function isDailyReportIssuedStatus(value){
    const norm = normalizeDailyReportAgentToken(safeTrim(value));
    if(!norm) return false;
    if(norm.includes("ממתין")) return false;
    return norm === "הופק" || norm === "הופקה";
  }

  // GI-PREMIUM-STATS: "ממתין להפקה" בהתאמה מדויקת בלבד (אחרי נרמול רווחים/פיסוק).
  // סטטוסים אחרים שמכילים "ממתין" (למשל "ממתין לחתימות") לא נספרים כאן.
  const DAILY_REPORT_PENDING_ISSUE_STATUSES = Object.freeze([
    "ממתין להפקה",
    "ממתינה להפקה"
  ].map((s) => normalizeDailyReportAgentToken(s)));

  function isDailyReportPendingIssueStatus(value){
    const norm = normalizeDailyReportAgentToken(safeTrim(value));
    if(!norm) return false;
    return DAILY_REPORT_PENDING_ISSUE_STATUSES.includes(norm);
  }

  // בשורות שממתינות להפקה עמודת "פרמיה הפקה" ריקה (עוד לא הופק),
  // ולכן הסכום נלקח מעמודת "פרמיה". נפילה חזרה ל"פרמיה הפקה" רק אם "פרמיה" ריקה.
  function getDailyReportPendingPremiumValue(row, cols){
    if(!row || !cols) return 0;
    const base = (cols.premium >= 0) ? parseDailyReportMoney(getDailyReportCell(row, cols.premium)) : 0;
    if(base > 0) return base;
    return getDailyReportIssuedPremiumValue(row, cols);
  }

  function getDailyReportCell(row, colIdx){
    if(!row || colIdx < 0) return "";
    return safeTrim(row.cells?.[colIdx]);
  }

  function formatDailyReportAsOfDate(isoDate){
    const raw = safeTrim(isoDate);
    if(!raw) return "";
    const m = /^(\d{4})-(\d{2})-(\d{2})/.exec(raw);
    if(m) return `${m[3]}.${m[2]}.${m[1]}`;
    const d = new Date(raw);
    if(Number.isNaN(d.getTime())) return raw.slice(0, 10);
    try {
      return d.toLocaleDateString("he-IL", { day: "2-digit", month: "2-digit", year: "numeric" });
    } catch(_e) {
      return raw.slice(0, 10);
    }
  }

  function normalizeDailyReportAsOfInput(value){
    const raw = safeTrim(value);
    if(!raw) return "";
    const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(raw);
    if(m) return raw;
    const d = new Date(raw);
    if(Number.isNaN(d.getTime())) return "";
    const y = d.getFullYear();
    const mo = String(d.getMonth() + 1).padStart(2, "0");
    const da = String(d.getDate()).padStart(2, "0");
    return `${y}-${mo}-${da}`;
  }

  function getLocalYmdToday(){
    const d = new Date();
    const y = d.getFullYear();
    const mo = String(d.getMonth() + 1).padStart(2, "0");
    const da = String(d.getDate()).padStart(2, "0");
    return `${y}-${mo}-${da}`;
  }

  function dailyReportMonthKeyFromAsOf(asOf){
    const n = normalizeDailyReportAsOfInput(asOf);
    return n ? n.slice(0, 7) : "";
  }

  function dailyReportMonthArchiveId(monthKey){
    const key = safeTrim(monthKey);
    if(!/^\d{4}-\d{2}$/.test(key)) return "";
    return DAILY_REPORT_MONTH_ID_PREFIX + key;
  }

  function parseDailyReportMonthArchiveId(id){
    const m = new RegExp("^" + DAILY_REPORT_MONTH_ID_PREFIX + "(\\d{4}-\\d{2})$").exec(safeTrim(id));
    return m ? m[1] : "";
  }

  function formatDailyReportMonthLabel(monthKey){
    const m = /^(\d{4})-(\d{2})$/.exec(safeTrim(monthKey));
    if(!m) return safeTrim(monthKey);
    const months = [
      "ינואר", "פברואר", "מרץ", "אפריל", "מאי", "יוני",
      "יולי", "אוגוסט", "ספטמבר", "אוקטובר", "נובמבר", "דצמבר"
    ];
    const idx = Number(m[2]) - 1;
    const name = (idx >= 0 && idx < months.length) ? months[idx] : m[2];
    return name + " " + m[1];
  }

  function isDailyReportAsOfInCurrentMonth(asOf){
    const key = dailyReportMonthKeyFromAsOf(asOf);
    const todayKey = dailyReportMonthKeyFromAsOf(getLocalYmdToday());
    return !!key && key === todayKey;
  }

  function normalizeDailyReportAgentToken(value){
    // Normalize punctuation/quotes and collapse whitespace so export formatting
    // differences won't block matching rows to the correct agent.
    return safeTrim(value)
      .toLowerCase()
      .replace(/["'`׳״.,;:!?()[\]{}<>|\\/+\-_]+/g, " ")
      .replace(/\s+/g, " ");
  }

  // Allows the daily-report ownership/matching engine to be reused verbatim for
  // OTHER report-shaped datasets (e.g. cancellations sheets) by temporarily
  // pointing the "active report" at a supplied report object. When no override is
  // set the behavior is IDENTICAL to reading DailyReportStore.report directly, so
  // the daily report itself is unaffected.
  let _dailyReportActiveOverride = null;
  function getActiveDailyReportContext(){
    if(_dailyReportActiveOverride) return _dailyReportActiveOverride;
    return (typeof DailyReportStore !== "undefined" && DailyReportStore) ? DailyReportStore.report : null;
  }
  function withDailyReportContext(report, fn){
    const prev = _dailyReportActiveOverride;
    _dailyReportActiveOverride = report || null;
    invalidateDailyReportMatchCaches();
    try {
      return fn();
    } finally {
      _dailyReportActiveOverride = prev;
      invalidateDailyReportMatchCaches();
    }
  }

  function getDailyReportAgentLabelTokensSet(){
    const report = getActiveDailyReportContext();
    const out = new Set();
    if(!report) return out;
    (report.dataRows || []).forEach((row) => {
      const key = normalizeAgentLabelToken(normalizeDailyReportAgentKey(row?.agent));
      if(key) out.add(key);
    });
    return out;
  }

  function dailyReportHasMoreSpecificLabelForToken(token, reportLabels){
    const norm = normalizeAgentLabelToken(token);
    if(!norm) return false;
    for(const label of reportLabels){
      const tokens = agentLabelTokens(label);
      if(tokens.length >= 2 && tokens[0] === norm) return true;
    }
    return false;
  }

  // Returns a profile whose `names` set also includes any explicit report aliases
  // registered for the agent id(s) in the profile. If the agent has no aliases the
  // ORIGINAL profile is returned untouched, so matching for everyone else is identical.
  function withDailyReportAliasNames(profile){
    if(!profile || !profile.ids || !profile.ids.size) return profile;
    const extra = [];
    for(const id of profile.ids){
      getAgentReportAliases(id).forEach((alias) => {
        const norm = normalizeAgentLabelToken(alias);
        if(norm) extra.push(norm);
      });
    }
    if(!extra.length) return profile;
    const names = new Set(profile.names);
    extra.forEach((n) => names.add(n));
    return { ...profile, names };
  }

  function dailyReportAgentLabelMatchesProfile(label, profile){
    profile = withDailyReportAliasNames(profile);
    const reportLabels = getDailyReportAgentLabelTokensSet();
    const norm = normalizeAgentLabelToken(label);
    if(!norm || !profile?.names?.size) return false;
    if(profile.names.has(norm)) return true;

    const labelTokens = agentLabelTokens(label);
    if(!labelTokens.length) return false;

    if(labelTokens.length >= 2){
      for(const full of profile.names){
        const profileTokens = agentLabelTokens(full);
        if(profileTokens.length < labelTokens.length) continue;
        if(agentLabelTokensSubset(labelTokens, profileTokens)) return true;
      }
      return false;
    }

    const token = labelTokens[0];
    if(profile.names.has(token)) return true;

    if(dailyReportHasMoreSpecificLabelForToken(token, reportLabels)){
      for(const full of profile.names){
        const profileTokens = agentLabelTokens(full);
        if(profileTokens.length < 2 || profileTokens[0] !== token) continue;
        if(!reportLabels.has(normalizeAgentLabelToken(full))) return true;
      }
      return false;
    }

    for(const full of profile.names){
      const profileTokens = agentLabelTokens(full);
      if(profileTokens.length <= 1) continue;
      if(agentLabelTokensSubset(labelTokens, profileTokens)) return true;
    }
    return false;
  }

  function normalizeDailyReportTeamKey(value){
    return normalizeAgentLabelToken(safeTrim(value));
  }

  let _dailyReportOwnershipCache = null;
  let _dailyReportMatchStamp = "";

  function getDailyReportMatchStamp(){
    let aliasSig = "";
    try {
      aliasSig = JSON.stringify(State.data?.meta?.agentReportAliases || {});
    } catch(_e) {}
    return [
      safeTrim(State.data?.meta?.updatedAt),
      safeTrim(State.data?.meta?.revision?.stateVersion),
      Array.isArray(State.data?.agents) ? State.data.agents.length : 0,
      aliasSig
    ].join("|");
  }

  function ensureDailyReportMatchStampFresh(){
    const stamp = getDailyReportMatchStamp();
    if(_dailyReportMatchStamp === stamp) return;
    _dailyReportMatchStamp = stamp;
    _dailyReportOwnershipCache = null;
    _dailyReportCandidateAgentsRef = null;
    _dailyReportCandidateAgentsMap = null;
    _dailyReportActiveAgentsSig = "";
    _dailyReportActiveAgentsValue = null;
    _currentProfileCacheSig = "";
    _currentProfileCache = null;
  }

  function getDailyReportCacheStamp(report){
    if(!report) return "";
    return [
      safeTrim(report.uploadedAt),
      safeTrim(report.reportAsOfDate),
      report.dataRows?.length || 0,
      report.headerRow?.length || 0,
      getDailyReportMatchStamp()
    ].join("|");
  }

  function invalidateDailyReportMatchCaches(){
    _dailyReportMatchStamp = "";
    _dailyReportOwnershipCache = null;
    _dailyReportCandidateAgentsRef = null;
    _dailyReportCandidateAgentsMap = null;
    _dailyReportActiveAgentsSig = "";
    _dailyReportActiveAgentsValue = null;
    _currentProfileCacheSig = "";
    _currentProfileCache = null;
  }

  function invalidateDailyReportOwnershipCache(){
    invalidateDailyReportMatchCaches();
  }

  let _dailyReportActiveAgentsSig = "";
  let _dailyReportActiveAgentsValue = null;
  function getDailyReportActiveAgents(){
    ensureDailyReportMatchStampFresh();
    const sig = getDailyReportMatchStamp();
    if(_dailyReportActiveAgentsSig === sig && _dailyReportActiveAgentsValue){
      return _dailyReportActiveAgentsValue;
    }
    const value = Array.isArray(State.data?.agents)
      ? State.data.agents.filter((a) => a?.active !== false)
      : [];
    _dailyReportActiveAgentsSig = sig;
    _dailyReportActiveAgentsValue = value;
    return value;
  }

  function dailyReportAgentIdKey(agentId){
    return String(safeTrim(agentId) || "").toLowerCase();
  }

  function dailyReportRowTeamNorm(row, cols){
    if(!row || !cols || cols.team < 0) return "";
    return normalizeDailyReportTeamKey(getDailyReportCell(row, cols.team));
  }

  function dailyReportLabelIsMultiToken(label){
    return agentLabelTokens(label).length >= 2;
  }

  let _dailyReportCandidateAgentsRef = null;
  let _dailyReportCandidateAgentsMap = null;
  function dailyReportLabelCandidateAgents(label, agents){
    ensureDailyReportMatchStampFresh();
    const list = Array.isArray(agents) ? agents : [];
    if(_dailyReportCandidateAgentsRef !== list || !_dailyReportCandidateAgentsMap){
      _dailyReportCandidateAgentsRef = list;
      _dailyReportCandidateAgentsMap = new Map();
    }
    const key = safeTrim(label);
    if(_dailyReportCandidateAgentsMap.has(key)) return _dailyReportCandidateAgentsMap.get(key);
    const result = list.filter((a) => dailyReportStrictAgentLabelMatchesAgent(label, a));
    _dailyReportCandidateAgentsMap.set(key, result);
    return result;
  }

  function dailyReportAddAgentTeam(teamMap, agentId, teamNorm){
    const key = dailyReportAgentIdKey(agentId);
    if(!key || !teamNorm) return;
    if(!teamMap.has(key)) teamMap.set(key, new Set());
    teamMap.get(key).add(teamNorm);
  }

  function buildDailyReportAgentTeamMap(report){
    const teamMap = new Map();
    if(!report) return teamMap;
    const cols = getDailyReportColumnIndexes(report);
    if(cols.team < 0) return teamMap;
    const agents = getDailyReportActiveAgents();

    (report.dataRows || []).forEach((row) => {
      const label = safeTrim(row?.agent);
      const teamNorm = dailyReportRowTeamNorm(row, cols);
      if(!label || !teamNorm || !dailyReportLabelIsMultiToken(label)) return;
      const matches = dailyReportLabelCandidateAgents(label, agents);
      if(matches.length === 1) dailyReportAddAgentTeam(teamMap, matches[0].id, teamNorm);
    });

    (report.dataRows || []).forEach((row) => {
      const label = safeTrim(row?.agent);
      const teamNorm = dailyReportRowTeamNorm(row, cols);
      if(!label || !teamNorm || dailyReportLabelIsMultiToken(label)) return;
      let matches = dailyReportLabelCandidateAgents(label, agents);
      if(!matches.length) return;
      matches = matches.filter((a) => {
        const teams = teamMap.get(dailyReportAgentIdKey(a.id));
        return !teams || !teams.size || teams.has(teamNorm);
      });
      if(!matches.length) return;
      const withThisTeam = matches.filter((a) => {
        const teams = teamMap.get(dailyReportAgentIdKey(a.id));
        return teams && teams.has(teamNorm);
      });
      if(withThisTeam.length === 1){
        dailyReportAddAgentTeam(teamMap, withThisTeam[0].id, teamNorm);
        return;
      }
      if(matches.length === 1) dailyReportAddAgentTeam(teamMap, matches[0].id, teamNorm);
    });

    return teamMap;
  }

  function getDailyReportOwnershipCache(report){
    const stamp = getDailyReportCacheStamp(report);
    if(_dailyReportOwnershipCache && _dailyReportOwnershipCache.stamp === stamp){
      return _dailyReportOwnershipCache;
    }
    const cols = getDailyReportColumnIndexes(report);
    _dailyReportOwnershipCache = {
      stamp,
      cols,
      agentTeams: buildDailyReportAgentTeamMap(report)
    };
    return _dailyReportOwnershipCache;
  }

  function dailyReportNarrowCandidatesByTeam(candidates, teamNorm, agentTeams, cols){
    if(!teamNorm || !cols || cols.team < 0) return candidates;
    let narrowed = (candidates || []).filter((a) => {
      const teams = agentTeams.get(dailyReportAgentIdKey(a.id));
      return !teams || !teams.size || teams.has(teamNorm);
    });
    if(!narrowed.length) return [];
    const withThisTeam = narrowed.filter((a) => {
      const teams = agentTeams.get(dailyReportAgentIdKey(a.id));
      return teams && teams.has(teamNorm);
    });
    if(withThisTeam.length === 1) return withThisTeam;
    if(narrowed.length === 1) return narrowed;
    return [];
  }

  function getDailyReportRowTeamLabel(row, report){
    const cols = getDailyReportColumnIndexes(report);
    if(cols.team < 0) return "";
    return safeTrim(getDailyReportCell(row, cols.team));
  }

  function getDailyReportProfileAgentId(profile){
    if(!profile?.ids?.size) return "";
    for(const id of profile.ids){
      const s = safeTrim(id);
      if(s) return s;
    }
    return "";
  }

  function getDailyReportStrictOwnershipProfile(agent){
    return getAgentOwnershipProfile({
      id: safeTrim(agent?.id),
      name: safeTrim(agent?.name),
      username: safeTrim(agent?.username),
      sessionName: safeTrim(agent?.name)
    });
  }

  function dailyReportStrictAgentLabelMatchesAgent(label, agent){
    if(!agent) return false;
    return dailyReportAgentLabelMatchesProfile(label, getDailyReportStrictOwnershipProfile(agent));
  }

  function resolveDailyReportRowOwnerId(row, report){
    const label = safeTrim(row?.agent);
    if(!label || !report) return "";
    const { cols, agentTeams } = getDailyReportOwnershipCache(report);
    const teamNorm = dailyReportRowTeamNorm(row, cols);
    const agents = getDailyReportActiveAgents();
    let candidates = dailyReportLabelCandidateAgents(label, agents);
    if(!candidates.length) return "";

    if(teamNorm && cols.team >= 0){
      candidates = dailyReportNarrowCandidatesByTeam(candidates, teamNorm, agentTeams, cols);
      if(candidates.length === 1) return safeTrim(candidates[0].id);
      return "";
    }

    if(candidates.length === 1) return safeTrim(candidates[0].id);
    const norm = normalizeAgentLabelToken(label);
    const exact = candidates.find((a) => getDailyReportStrictOwnershipProfile(a).names.has(norm));
    return exact ? safeTrim(exact.id) : "";
  }

  function dailyReportRowMatchesOwnershipProfile(row, ownershipProfile){
    if(!row || typeof row !== "object" || !ownershipProfile) return false;
    const label = safeTrim(row.agent);
    if(!label) return false;
    const report = getActiveDailyReportContext();
    const cols = report ? getDailyReportColumnIndexes(report) : { team: -1 };
    const rowTeam = dailyReportRowTeamNorm(row, cols);
    if(report && cols.team >= 0 && rowTeam){
      const ownerId = resolveDailyReportRowOwnerId(row, report);
      const profileId = getDailyReportProfileAgentId(ownershipProfile);
      if(ownerId && profileId) return String(ownerId).toLowerCase() === String(profileId).toLowerCase();
      // Fallback: team-owner cache can be stale after alias edits; honor explicit report aliases.
      if(dailyReportAgentLabelMatchesProfile(label, ownershipProfile)) return true;
      return false;
    }
    if(!dailyReportAgentLabelMatchesProfile(label, ownershipProfile)) return false;
    const agents = getDailyReportActiveAgents();
    const candidates = dailyReportLabelCandidateAgents(label, agents);
    if(candidates.length <= 1) return true;
    const norm = normalizeAgentLabelToken(label);
    if(ownershipProfile.names.has(norm)) return true;
    if(agentLabelTokens(label).length === 1) return false;
    const profileId = getDailyReportProfileAgentId(ownershipProfile);
    if(!profileId) return false;
    return candidates.some((a) => dailyReportAgentIdKey(a.id) === dailyReportAgentIdKey(profileId));
  }

  function dailyReportRowVisibleToSession(row){
    if(!row || typeof row !== "object") return false;
    if(Auth.isAdmin() || Auth.isManager()) return true;
    if(Auth.isTeamManager()){
      if(dailyReportRowMatchesOwnershipProfile(row, getCurrentAgentOwnershipProfile())) return true;
      const profiles = getManagedAgentOwnershipProfiles();
      return profiles.some((p) => dailyReportRowMatchesOwnershipProfile(row, p));
    }
    return dailyReportRowMatchesOwnershipProfile(row, getCurrentAgentOwnershipProfile());
  }

  function dailyReportRowMatchesCurrentAgent(row){
    return dailyReportRowVisibleToSession(row);
  }

  function isWithinDateRange(value, range){
    const stamp = Date.parse(value || "");
    if(!Number.isFinite(stamp) || !range) return false;
    return stamp >= range.start.getTime() && stamp < range.end.getTime();
  }

  function formatMyTeamDateTime(value){
    const raw = safeTrim(value);
    if(!raw) return "—";
    const d = new Date(raw);
    if(Number.isNaN(d.getTime())) return raw;
    try {
      return d.toLocaleString("he-IL", {
        day: "2-digit",
        month: "2-digit",
        year: "numeric",
        hour: "2-digit",
        minute: "2-digit"
      });
    } catch(_e) {
      return raw;
    }
  }

  function computeAgentTeamSalesMetrics(agent){
    const ownership = getAgentOwnershipProfileForAgent(agent);
    const customers = (Array.isArray(State.data?.customers) ? State.data.customers : [])
      .filter((rec) => recordOwnedByAgent(rec, ownership));
    const todayRange = DashboardUI.getTodayRange();
    const monthRange = DashboardUI.getMonthToDateRange();
    let todayPremium = 0;
    let todayPolicies = 0;
    let monthPremium = 0;
    let monthPolicies = 0;
    let lastStampMs = 0;
    customers.forEach((rec) => {
      const stamp = safeTrim(rec?.createdAt)
        || safeTrim(rec?.payload?.createdAt)
        || safeTrim(rec?.updatedAt)
        || safeTrim(rec?.payload?.updatedAt);
      const stampMs = Date.parse(stamp);
      if(Number.isFinite(stampMs) && stampMs > lastStampMs) lastStampMs = stampMs;
      const policies = CustomersUI.collectPolicies(rec).filter((p) => String(p?.origin || "") === "new");
      policies.forEach((p) => {
        const premium = DashboardUI.policyNetPremium(p);
        if(isWithinDateRange(stamp, todayRange)){
          todayPremium += premium;
          todayPolicies += 1;
        }
        if(isWithinDateRange(stamp, monthRange)){
          monthPremium += premium;
          monthPolicies += 1;
        }
      });
    });
    let issuedPremium = 0;
    let issuedPolicies = 0;
    const report = DailyReportStore?.report;
    if(report){
      const cols = getDailyReportColumnIndexes(report);
      if(cols.status >= 0){
        (report.dataRows || []).forEach((row) => {
          if(!dailyReportRowMatchesOwnershipProfile(row, ownership)) return;
          if(!isDailyReportIssuedStatus(getDailyReportCell(row, cols.status))) return;
          issuedPolicies += 1;
          issuedPremium += getDailyReportIssuedPremiumValue(row, cols);
        });
      }
    }
    return {
      todayPremium: Math.round(todayPremium * 100) / 100,
      todayPolicies,
      monthPremium: Math.round(monthPremium * 100) / 100,
      monthPolicies,
      issuedPremium: Math.round(issuedPremium * 100) / 100,
      issuedPolicies,
      lastActivity: lastStampMs > 0 ? new Date(lastStampMs).toISOString() : ""
    };
  }

  function formatDailyReportUploadDate(iso){
    const raw = safeTrim(iso);
    if(!raw) return "";
    const d = new Date(raw);
    if(Number.isNaN(d.getTime())) return raw.slice(0, 10);
    try {
      return d.toLocaleDateString("he-IL", { day: "2-digit", month: "2-digit", year: "numeric" });
    } catch(_e) {
      return raw.slice(0, 10);
    }
  }

  function formatDailyReportCellValue(value){
    if(value === null || value === undefined) return "";
    if(typeof value === "number"){
      if(!Number.isFinite(value)) return "";
      return String(value);
    }
    if(value instanceof Date){
      try { return value.toLocaleDateString("he-IL"); } catch(_e) { return String(value); }
    }
    return safeTrim(value);
  }

  function mapDailyReportFromDb(row){
    if(!row || typeof row !== "object") return null;
    const headerRow = Array.isArray(row.header_row) ? row.header_row : (Array.isArray(row.headerRow) ? row.headerRow : []);
    const dataRows = Array.isArray(row.data_rows) ? row.data_rows : (Array.isArray(row.dataRows) ? row.dataRows : []);
    return {
      id: safeTrim(row.id) || DAILY_REPORT_ACTIVE_ID,
      uploadedAt: safeTrim(row.uploaded_at || row.uploadedAt),
      uploadedByName: safeTrim(row.uploaded_by_name || row.uploadedByName),
      reportAsOfDate: normalizeDailyReportAsOfInput(row.report_as_of_date || row.reportAsOfDate),
      sheetName: safeTrim(row.sheet_name || row.sheetName),
      headerRow: headerRow.map((c) => safeTrim(c)),
      dataRows: (Array.isArray(dataRows) ? dataRows : []).map((r, idx) => ({
        rowIndex: Number(r?.rowIndex ?? r?.row_index ?? idx + 2) || (idx + 2),
        agent: normalizeDailyReportAgentKey(r?.agent),
        cells: Array.isArray(r?.cells) ? r.cells.map((c) => formatDailyReportCellValue(c)) : []
      }))
    };
  }

  function mapDailyReportToDb(report, options = {}){
    const r = report && typeof report === "object" ? report : {};
    const id = safeTrim(options?.id) || DAILY_REPORT_ACTIVE_ID;
    return {
      id,
      uploaded_at: safeTrim(r.uploadedAt) || nowISO(),
      uploaded_by_name: safeTrim(r.uploadedByName),
      report_as_of_date: normalizeDailyReportAsOfInput(r.reportAsOfDate),
      sheet_name: safeTrim(r.sheetName),
      header_row: Array.isArray(r.headerRow) ? r.headerRow.map((c) => safeTrim(c)) : [],
      data_rows: (Array.isArray(r.dataRows) ? r.dataRows : []).map((row, idx) => ({
        row_index: Number(row?.rowIndex) || (idx + 2),
        agent: normalizeDailyReportAgentKey(row?.agent),
        cells: Array.isArray(row?.cells) ? row.cells.map((c) => formatDailyReportCellValue(c)) : []
      }))
    };
  }

  function parseDailyReportWorkbook(file){
    return new Promise((resolve) => {
      if(typeof window === "undefined" || !window.XLSX){
        resolve({ ok: false, error: "ספריית Excel לא נטענה — רענן את הדף" });
        return;
      }
      const reader = new FileReader();
      reader.onerror = () => resolve({ ok: false, error: "לא ניתן לקרוא את הקובץ" });
      reader.onload = (ev) => {
        try {
          const data = new Uint8Array(ev.target?.result || []);
          const wb = window.XLSX.read(data, { type: "array", cellDates: true });
          const sheetName = wb.SheetNames?.[0] || "";
          if(!sheetName) return resolve({ ok: false, error: "הקובץ ריק או ללא גיליון" });
          const sheet = wb.Sheets[sheetName];
          const matrix = window.XLSX.utils.sheet_to_json(sheet, { header: 1, defval: "", raw: false });
          if(!Array.isArray(matrix) || matrix.length < 2){
            return resolve({ ok: false, error: "הדוח חייב לכלול שורת כותרות ולפחות שורת נתונים אחת" });
          }
          const headerRow = (matrix[0] || []).map((c) => safeTrim(c));
          const agentColIdx = findDailyReportHeaderCol(headerRow, ["נציג"]);
          if(agentColIdx < 0){
            return resolve({ ok: false, error: 'לא נמצאה עמודת "נציג" בשורת הכותרות' });
          }
          const colCount = headerRow.length;
          const dataRows = [];
          for(let i = 1; i < matrix.length; i += 1){
            const raw = matrix[i];
            if(!Array.isArray(raw)) continue;
            const cells = [];
            let hasData = false;
            for(let c = 0; c < colCount; c += 1){
              const val = formatDailyReportCellValue(raw[c]);
              if(val) hasData = true;
              cells.push(val);
            }
            if(!hasData) continue;
            dataRows.push({
              rowIndex: i + 1,
              agent: normalizeDailyReportAgentKey(raw[agentColIdx]),
              cells
            });
          }
          if(!dataRows.length){
            return resolve({ ok: false, error: "לא נמצאו שורות נתונים בדוח" });
          }
          resolve({ ok: true, sheetName, headerRow, dataRows });
        } catch(err) {
          resolve({ ok: false, error: String(err?.message || err || "שגיאה בפענוח הקובץ") });
        }
      };
      reader.readAsArrayBuffer(file);
    });
  }

  const DailyReportStore = {
    report: null,
    // צפייה בארכיון חודשי — לא מחליף את report (active) שמשמש דשבורד/KPI.
    viewMonthKey: "",
    archiveReport: null,
    monthIndex: [],
    tableReady: true,
    lastError: "",
    archiveLastError: "",

    getViewReport(){
      if(safeTrim(this.viewMonthKey)) return this.archiveReport;
      return this.report;
    },

    getVisibleRowsFor(report){
      if(!report) return [];
      return (report.dataRows || []).filter((row) => dailyReportRowVisibleToSession(row));
    },

    getVisibleRows(){
      return this.getVisibleRowsFor(this.report);
    },

    getAgentSummaryFor(report){
      const map = new Map();
      (report?.dataRows || []).forEach((row) => {
        const key = normalizeDailyReportAgentKey(row.agent) || "— ללא נציג";
        map.set(key, (map.get(key) || 0) + 1);
      });
      return Array.from(map.entries()).sort((a, b) => a[0].localeCompare(b[0], "he"));
    },

    async fetchActive(){
      this.lastError = "";
      const res = await Storage.loadSingleRow(SUPABASE_TABLES.dailyReport, DAILY_REPORT_ACTIVE_ID, "*");
      if(!res.ok){
        const err = safeTrim(res.error).toLowerCase();
        if(err.includes("does not exist") || err.includes("relation") || err.includes("schema cache") || err.includes("permission denied")){
          this.tableReady = false;
          this.lastError = res.error || "טבלת דוח יומי חסרה ב-Supabase";
        } else {
          this.tableReady = true;
          this.lastError = res.error || "";
        }
        this.report = null;
        invalidateDailyReportOwnershipCache();
        return { ok: false, error: this.lastError };
      }
      this.tableReady = true;
      if(!res.data){
        this.report = null;
        invalidateDailyReportOwnershipCache();
        return { ok: true, report: null };
      }
      this.report = mapDailyReportFromDb(res.data);
      invalidateDailyReportOwnershipCache();
      return { ok: true, report: this.report };
    },

    async saveActive(report){
      const row = mapDailyReportToDb(report);
      let save = await Storage.upsertSingleRow(SUPABASE_TABLES.dailyReport, row);
      if(!save.ok){
        const errMsg = safeTrim(save.error);
        if(errMsg && /report_as_of_date|column|schema.cache/i.test(errMsg) && Object.prototype.hasOwnProperty.call(row, "report_as_of_date")){
          const slim = { ...row };
          delete slim.report_as_of_date;
          save = await Storage.upsertSingleRow(SUPABASE_TABLES.dailyReport, slim);
        }
        if(!save.ok) return save;
      }
      this.report = null;
      this.report = mapDailyReportFromDb(row);
      invalidateDailyReportOwnershipCache();
      this.tableReady = true;
      return { ok: true, report: this.report };
    },

    async saveMonthArchive(report){
      this.archiveLastError = "";
      const monthKey = dailyReportMonthKeyFromAsOf(report?.reportAsOfDate);
      const id = dailyReportMonthArchiveId(monthKey);
      if(!id){
        this.archiveLastError = "חסר תאריך דוח לקביעת חודש ארכיון";
        return { ok: false, error: this.archiveLastError };
      }
      const row = mapDailyReportToDb(report, { id });
      let save = await Storage.upsertSingleRow(SUPABASE_TABLES.dailyReport, row);
      if(!save.ok){
        const errMsg = safeTrim(save.error);
        if(errMsg && /report_as_of_date|column|schema.cache/i.test(errMsg) && Object.prototype.hasOwnProperty.call(row, "report_as_of_date")){
          const slim = { ...row };
          delete slim.report_as_of_date;
          save = await Storage.upsertSingleRow(SUPABASE_TABLES.dailyReport, slim);
        }
        if(!save.ok){
          this.archiveLastError = save.error || "שמירת ארכיון חודשי נכשלה";
          return save;
        }
      }
      const entry = {
        monthKey,
        reportAsOfDate: normalizeDailyReportAsOfInput(report?.reportAsOfDate),
        uploadedAt: safeTrim(row.uploaded_at),
        uploadedByName: safeTrim(row.uploaded_by_name)
      };
      const without = (this.monthIndex || []).filter((m) => m.monthKey !== monthKey);
      without.push(entry);
      without.sort((a, b) => safeTrim(b.monthKey).localeCompare(safeTrim(a.monthKey)));
      this.monthIndex = without;
      return { ok: true, monthKey, report: mapDailyReportFromDb(row) };
    },

    async listMonthArchives(){
      this.archiveLastError = "";
      const lightSelect = "id,report_as_of_date,uploaded_at,uploaded_by_name";
      let res = await Storage.loadTableRows(SUPABASE_TABLES.dailyReport, lightSelect);
      if(!res.ok){
        const errMsg = safeTrim(res.error);
        if(errMsg && /report_as_of_date|column|schema.cache/i.test(errMsg)){
          res = await Storage.loadTableRows(SUPABASE_TABLES.dailyReport, "id,uploaded_at,uploaded_by_name");
        }
      }
      if(!res.ok){
        this.archiveLastError = res.error || "טעינת ארכיון חודשים נכשלה";
        return { ok: false, error: this.archiveLastError, months: this.monthIndex };
      }
      const rows = Array.isArray(res.data) ? res.data : [];
      const months = [];
      rows.forEach((row) => {
        const monthKey = parseDailyReportMonthArchiveId(row?.id);
        if(!monthKey) return;
        months.push({
          monthKey,
          reportAsOfDate: normalizeDailyReportAsOfInput(row.report_as_of_date || row.reportAsOfDate),
          uploadedAt: safeTrim(row.uploaded_at || row.uploadedAt),
          uploadedByName: safeTrim(row.uploaded_by_name || row.uploadedByName)
        });
      });
      months.sort((a, b) => safeTrim(b.monthKey).localeCompare(safeTrim(a.monthKey)));
      this.monthIndex = months;
      return { ok: true, months };
    },

    async fetchMonthArchive(monthKey){
      this.archiveLastError = "";
      const key = safeTrim(monthKey);
      const id = dailyReportMonthArchiveId(key);
      if(!id){
        this.archiveLastError = "חודש לא תקין";
        return { ok: false, error: this.archiveLastError };
      }
      const res = await Storage.loadSingleRow(SUPABASE_TABLES.dailyReport, id, "*");
      if(!res.ok){
        this.archiveLastError = res.error || "טעינת ארכיון חודשי נכשלה";
        return { ok: false, error: this.archiveLastError };
      }
      if(!res.data){
        this.archiveLastError = "לא נמצא דוח לחודש שנבחר";
        this.viewMonthKey = "";
        this.archiveReport = null;
        return { ok: false, error: this.archiveLastError };
      }
      this.viewMonthKey = key;
      this.archiveReport = mapDailyReportFromDb(res.data);
      invalidateDailyReportOwnershipCache();
      return { ok: true, report: this.archiveReport, monthKey: key };
    },

    async selectViewMonth(monthKey){
      const key = safeTrim(monthKey);
      if(!key){
        this.viewMonthKey = "";
        this.archiveReport = null;
        invalidateDailyReportOwnershipCache();
        return { ok: true, report: this.report };
      }
      return this.fetchMonthArchive(key);
    },

    getAgentSummary(){
      return this.getAgentSummaryFor(this.report);
    },

    getIssuedRows(){
      const report = this.report;
      if(!report) return [];
      const cols = getDailyReportColumnIndexes(report);
      if(cols.status < 0) return [];
      return this.getVisibleRows().filter((row) =>
        isDailyReportIssuedStatus(getDailyReportCell(row, cols.status))
      );
    },

    getIssuedPremiumMetrics(){
      const report = this.report;
      if(!report){
        return { totalPremium: 0, policyCount: 0, items: [], hasReport: false };
      }
      const cols = getDailyReportColumnIndexes(report);
      const byCompany = new Map();
      let totalPremium = 0;
      let policyCount = 0;
      this.getIssuedRows().forEach((row) => {
        const premium = getDailyReportIssuedPremiumValue(row, cols);
        totalPremium += premium;
        policyCount += 1;
        const companyRaw = (cols.company >= 0) ? getDailyReportCell(row, cols.company) : "";
        const company = safeTrim(companyRaw) || "ללא חברה";
        const prev = byCompany.get(company) || { label: company, premium: 0, policyCount: 0 };
        prev.premium = Math.round((prev.premium + premium) * 100) / 100;
        prev.policyCount += 1;
        byCompany.set(company, prev);
      });
      const items = Array.from(byCompany.values()).sort((a, b) => {
        if(b.premium !== a.premium) return b.premium - a.premium;
        return safeTrim(a.label).localeCompare(safeTrim(b.label), "he");
      });
      return {
        totalPremium: Math.round(totalPremium * 100) / 100,
        policyCount,
        items,
        hasReport: true
      };
    }
  };

  // ===== Cancellations report (multi-sheet) =====
  // Reuses the daily-report ownership/matching engine verbatim (per-agent filtering
  // + admin/manager/team-manager visibility) via withDailyReportContext.
  function makeCancellationsSheet(parent, sheet){
    const src = sheet && typeof sheet === "object" ? sheet : {};
    const headerRow = Array.isArray(src.headerRow || src.header_row)
      ? (src.headerRow || src.header_row).map((c) => safeTrim(c))
      : [];
    const rawRows = Array.isArray(src.dataRows || src.data_rows) ? (src.dataRows || src.data_rows) : [];
    return {
      sheetName: safeTrim(src.sheetName || src.sheet_name),
      uploadedAt: safeTrim(parent?.uploadedAt),
      reportAsOfDate: normalizeDailyReportAsOfInput(parent?.reportAsOfDate),
      headerRow,
      dataRows: rawRows.map((r, idx) => ({
        rowIndex: Number(r?.rowIndex ?? r?.row_index ?? idx + 2) || (idx + 2),
        agent: normalizeDailyReportAgentKey(r?.agent),
        cells: Array.isArray(r?.cells) ? r.cells.map((c) => formatDailyReportCellValue(c)) : []
      }))
    };
  }

  function mapCancellationsFromDb(row){
    if(!row || typeof row !== "object") return null;
    const base = {
      id: safeTrim(row.id) || CANCELLATIONS_REPORT_ACTIVE_ID,
      uploadedAt: safeTrim(row.uploaded_at || row.uploadedAt),
      uploadedByName: safeTrim(row.uploaded_by_name || row.uploadedByName),
      reportAsOfDate: normalizeDailyReportAsOfInput(row.report_as_of_date || row.reportAsOfDate)
    };
    const rawSheets = Array.isArray(row.sheets) ? row.sheets : [];
    base.sheets = rawSheets.map((s) => makeCancellationsSheet(base, s));
    return base;
  }

  function mapCancellationsToDb(report){
    const r = report && typeof report === "object" ? report : {};
    const sheets = Array.isArray(r.sheets) ? r.sheets : [];
    return {
      id: CANCELLATIONS_REPORT_ACTIVE_ID,
      uploaded_at: safeTrim(r.uploadedAt) || nowISO(),
      uploaded_by_name: safeTrim(r.uploadedByName),
      report_as_of_date: normalizeDailyReportAsOfInput(r.reportAsOfDate) || null,
      sheets: sheets.map((s) => ({
        sheet_name: safeTrim(s.sheetName),
        header_row: Array.isArray(s.headerRow) ? s.headerRow.map((c) => safeTrim(c)) : [],
        data_rows: (Array.isArray(s.dataRows) ? s.dataRows : []).map((row, idx) => ({
          row_index: Number(row?.rowIndex) || (idx + 2),
          agent: normalizeDailyReportAgentKey(row?.agent),
          cells: Array.isArray(row?.cells) ? row.cells.map((c) => formatDailyReportCellValue(c)) : []
        }))
      }))
    };
  }

  function parseCancellationsWorkbook(file){
    return new Promise((resolve) => {
      if(typeof window === "undefined" || !window.XLSX){
        resolve({ ok: false, error: "ספריית Excel לא נטענה — רענן את הדף" });
        return;
      }
      const reader = new FileReader();
      reader.onerror = () => resolve({ ok: false, error: "לא ניתן לקרוא את הקובץ" });
      reader.onload = (ev) => {
        try {
          const data = new Uint8Array(ev.target?.result || []);
          const wb = window.XLSX.read(data, { type: "array", cellDates: true });
          const sheetNames = Array.isArray(wb.SheetNames) ? wb.SheetNames : [];
          if(!sheetNames.length) return resolve({ ok: false, error: "הקובץ ריק או ללא גיליונות" });
          const sheets = [];
          const missingAgent = [];
          sheetNames.forEach((sn) => {
            const ws = wb.Sheets[sn];
            if(!ws) return;
            const matrix = window.XLSX.utils.sheet_to_json(ws, { header: 1, defval: "", raw: false });
            if(!Array.isArray(matrix) || matrix.length < 2) return; // skip empty sheets
            const headerRow = (matrix[0] || []).map((c) => safeTrim(c));
            if(!headerRow.some((h) => h)) return; // skip header-less sheets
            const agentColIdx = findDailyReportHeaderCol(headerRow, ["נציג"]);
            if(agentColIdx < 0){
              missingAgent.push(safeTrim(sn) || "(ללא שם)");
              return;
            }
            const colCount = headerRow.length;
            const dataRows = [];
            for(let i = 1; i < matrix.length; i += 1){
              const raw = matrix[i];
              if(!Array.isArray(raw)) continue;
              const cells = [];
              let hasData = false;
              for(let c = 0; c < colCount; c += 1){
                const val = formatDailyReportCellValue(raw[c]);
                if(val) hasData = true;
                cells.push(val);
              }
              if(!hasData) continue;
              dataRows.push({
                rowIndex: i + 1,
                agent: normalizeDailyReportAgentKey(raw[agentColIdx]),
                cells
              });
            }
            sheets.push({ sheetName: safeTrim(sn), headerRow, dataRows });
          });
          if(missingAgent.length){
            return resolve({ ok: false, error: 'לא נמצאה עמודת "נציג" בגיליון: ' + missingAgent.join(", ") });
          }
          if(!sheets.length){
            return resolve({ ok: false, error: "לא נמצאו גיליונות עם נתונים בקובץ" });
          }
          if(!sheets.some((s) => s.dataRows.length)){
            return resolve({ ok: false, error: "לא נמצאו שורות נתונים בקובץ הביטולים" });
          }
          resolve({ ok: true, sheets });
        } catch(err) {
          resolve({ ok: false, error: String(err?.message || err || "שגיאה בפענוח הקובץ") });
        }
      };
      reader.readAsArrayBuffer(file);
    });
  }

  const CancellationsStore = {
    report: null,
    tableReady: true,
    lastError: "",

    async fetchActive(){
      this.lastError = "";
      const res = await Storage.loadSingleRow(SUPABASE_TABLES.cancellationsReport, CANCELLATIONS_REPORT_ACTIVE_ID, "*");
      if(!res.ok){
        const err = safeTrim(res.error).toLowerCase();
        if(err.includes("does not exist") || err.includes("relation") || err.includes("schema cache") || err.includes("permission denied")){
          this.tableReady = false;
          this.lastError = res.error || "טבלת דוח ביטולים חסרה ב-Supabase";
        } else {
          this.tableReady = true;
          this.lastError = res.error || "";
        }
        this.report = null;
        return { ok: false, error: this.lastError };
      }
      this.tableReady = true;
      if(!res.data){
        this.report = null;
        return { ok: true, report: null };
      }
      this.report = mapCancellationsFromDb(res.data);
      return { ok: true, report: this.report };
    },

    async saveActive(report){
      const row = mapCancellationsToDb(report);
      let save = await Storage.upsertSingleRow(SUPABASE_TABLES.cancellationsReport, row);
      if(!save.ok){
        const errMsg = safeTrim(save.error);
        if(errMsg && /report_as_of_date|column|schema.cache/i.test(errMsg) && Object.prototype.hasOwnProperty.call(row, "report_as_of_date")){
          const slim = { ...row };
          delete slim.report_as_of_date;
          save = await Storage.upsertSingleRow(SUPABASE_TABLES.cancellationsReport, slim);
        }
        if(!save.ok) return save;
      }
      this.report = mapCancellationsFromDb(row);
      this.tableReady = true;
      return { ok: true, report: this.report };
    },

    getSheets(){
      return Array.isArray(this.report?.sheets) ? this.report.sheets : [];
    },

    getSheetByName(name){
      const key = safeTrim(name);
      return this.getSheets().find((s) => safeTrim(s.sheetName) === key) || null;
    },

    getVisibleRowsForSheet(sheet){
      if(!sheet) return [];
      return withDailyReportContext(sheet, () =>
        (Array.isArray(sheet.dataRows) ? sheet.dataRows : []).filter((row) => dailyReportRowVisibleToSession(row))
      );
    },

    getAgentSummaryForSheet(sheet){
      const map = new Map();
      (Array.isArray(sheet?.dataRows) ? sheet.dataRows : []).forEach((row) => {
        const key = normalizeDailyReportAgentKey(row.agent) || "— ללא נציג";
        map.set(key, (map.get(key) || 0) + 1);
      });
      return Array.from(map.entries()).sort((a, b) => a[0].localeCompare(b[0], "he"));
    }
  };

  const AgentActivityLogUI = {
    els: {},
    _selectedDate: "",
    _activeTab: "session",
    _sessionColspan: 8,
    _leadColspan: 9,
    _cache: { session: { date: "", rows: [] }, lead: { date: "", rows: [] } },

    init(){
      this.els.sessionTbody = document.getElementById("activityLogSessionTbody");
      this.els.leadTbody = document.getElementById("activityLogLeadTbody");
      this.els.panelSession = document.getElementById("activityLogPanelSession");
      this.els.panelLead = document.getElementById("activityLogPanelLead");
      this.els.meta = document.getElementById("activityLogMeta");
      this.els.dateBanner = document.getElementById("activityLogDateBanner");
      this.els.kpis = document.getElementById("activityLogKpis");
      this.els.hint = document.getElementById("activityLogHint");
      this.els.date = document.getElementById("activityLogDate");
      this.els.btnRefresh = document.getElementById("btnActivityLogRefresh");
      this.els.btnPrev = document.getElementById("btnActivityLogPrevDay");
      this.els.btnNext = document.getElementById("btnActivityLogNextDay");
      this.els.btnToday = document.getElementById("btnActivityLogToday");
      this.els.btnYesterday = document.getElementById("btnActivityLogYesterday");
      this.els.tabs = Array.from(document.querySelectorAll("[data-actlog-tab]"));
      if(this.els.date){
        this.els.date.value = getIsraelDateString();
        on(this.els.date, "change", () => {
          this.syncQuickDateButtons();
          void this.render(true);
        });
      }
      if(this.els.btnRefresh){
        on(this.els.btnRefresh, "click", () => void this.render(true));
      }
      if(this.els.btnPrev){
        on(this.els.btnPrev, "click", () => this.shiftDate(-1));
      }
      if(this.els.btnNext){
        on(this.els.btnNext, "click", () => this.shiftDate(1));
      }
      if(this.els.btnToday){
        on(this.els.btnToday, "click", () => this.pickDate(getIsraelDateString()));
      }
      if(this.els.btnYesterday){
        on(this.els.btnYesterday, "click", () => {
          const dt = new Date();
          dt.setDate(dt.getDate() - 1);
          this.pickDate(getIsraelDateString(dt));
        });
      }
      this.els.tabs.forEach((btn) => {
        on(btn, "click", () => {
          const tab = safeTrim(btn.getAttribute("data-actlog-tab")) || "session";
          this.setTab(tab);
        });
      });
      this.syncQuickDateButtons();
    },

    pickDate(dateStr){
      const next = safeTrim(dateStr) || getIsraelDateString();
      if(this.els.date) this.els.date.value = next;
      this._cache.session.date = "";
      this._cache.lead.date = "";
      this.syncQuickDateButtons();
      void this.render(true);
    },

    syncQuickDateButtons(){
      const date = this.selectedDate();
      const today = getIsraelDateString();
      const yesterdayDt = new Date();
      yesterdayDt.setDate(yesterdayDt.getDate() - 1);
      const yesterday = getIsraelDateString(yesterdayDt);
      if(this.els.btnToday) this.els.btnToday.classList.toggle("is-active", date === today);
      if(this.els.btnYesterday) this.els.btnYesterday.classList.toggle("is-active", date === yesterday);
    },

    setTab(tab){
      const next = tab === "lead" ? "lead" : "session";
      this._activeTab = next;
      this.els.tabs.forEach((btn) => {
        const isActive = safeTrim(btn.getAttribute("data-actlog-tab")) === next;
        btn.classList.toggle("is-active", isActive);
      });
      if(this.els.panelSession) this.els.panelSession.hidden = next !== "session";
      if(this.els.panelLead) this.els.panelLead.hidden = next !== "lead";
      if(this.els.panelSession) this.els.panelSession.classList.toggle("is-active", next === "session");
      if(this.els.panelLead) this.els.panelLead.classList.toggle("is-active", next === "lead");
      void this.render(false);
    },

    activeTbody(){
      return this._activeTab === "lead" ? this.els.leadTbody : this.els.sessionTbody;
    },

    shiftDate(deltaDays){
      const base = this.selectedDate();
      const parts = base.split("-").map(Number);
      if(parts.length !== 3) return;
      const dt = new Date(parts[0], parts[1] - 1, parts[2]);
      dt.setDate(dt.getDate() + Number(deltaDays || 0));
      const next = getIsraelDateString(dt);
      if(this.els.date) this.els.date.value = next;
      this._cache.session.date = "";
      this._cache.lead.date = "";
      this.syncQuickDateButtons();
      void this.render(true);
    },

    agentRoleLabel(role){
      const r = safeTrim(role).toLowerCase();
      const map = {
        owner: "מפתח המערכת",
        admin: "מנהל מערכת",
        manager: "מנהל",
        teammanager: "מנהל צוות",
        ops: "מנהל תפעול",
        opsagent: "נציג תפעול",
        elementary: "אלמנטרי",
        referent: "סוקרת",
        agent: "נציג"
      };
      return map[r] || safeTrim(role) || "נציג";
    },

    renderAgentCell(ev){
      const name = safeTrim(ev?.agent_name) || "—";
      const id = safeTrim(ev?.agent_id);
      const sub = id ? `מזהה: ${id}` : "ללא מזהה מערכת";
      return `<div class="giActLogTable__agentWrap">
        <div class="giActLogTable__agentName">${escapeHtml(name)}</div>
        <div class="giActLogTable__agentSub">${escapeHtml(sub)}</div>
      </div>`;
    },

    renderDateBanner(date){
      const host = this.els.dateBanner;
      if(!host) return;
      const today = getIsraelDateString();
      const label = this.formatDisplayDate(date);
      const badge = date === today ? '<span class="giActLog__dateBadge">היום</span>' : "";
      host.innerHTML = `
        <div class="giActLog__dateBannerMain">
          <span class="giActLog__dateBannerLabel">יום מוצג:</span>
          <strong class="giActLog__dateBannerValue">${escapeHtml(label)}</strong>
          ${badge}
        </div>
        <div class="giActLog__dateBannerSub">${escapeHtml(date)} · ${escapeHtml(this.scopeHint())}</div>
      `;
    },

    selectedDate(){
      const fromInput = safeTrim(this.els.date?.value);
      return fromInput || this._selectedDate || getIsraelDateString();
    },

    formatDisplayDate(dateStr){
      const v = safeTrim(dateStr);
      if(!v) return "—";
      try {
        const [y, m, d] = v.split("-").map(Number);
        const dt = new Date(y, m - 1, d);
        return new Intl.DateTimeFormat("he-IL", {
          weekday: "long",
          day: "numeric",
          month: "long",
          year: "numeric"
        }).format(dt);
      } catch(_e) {
        return v;
      }
    },

    eventLabel(type){
      return AgentActivityLog.EVENT_LABELS[safeTrim(type)] || safeTrim(type) || "—";
    },

    eventTone(type, category){
      const t = safeTrim(type);
      if(category === "lead") return "lead";
      if(t === "login") return "in";
      if(t === "logout_idle") return "idle";
      if(t === "logout_browser") return "browser";
      if(t.startsWith("logout_")) return "out";
      return "neutral";
    },

    eventStatusText(type){
      const t = safeTrim(type);
      if(t === "login") return "מחובר";
      if(t === "logout_manual") return "יצא";
      if(t === "logout_idle") return "נותק אוטומטית";
      if(t === "logout_browser") return "יצא מהמערכת";
      if(t.startsWith("lead_")) return "פעילות";
      return "—";
    },

    buildSessionStats(rows){
      const list = Array.isArray(rows) ? rows : [];
      const agents = new Set(list.map((r) => safeTrim(r?.agent_id) || safeTrim(r?.agent_name)).filter(Boolean));
      return {
        total: list.length,
        agents: agents.size,
        logins: list.filter((r) => safeTrim(r?.event_type) === "login").length,
        logouts: list.filter((r) => safeTrim(r?.event_type).startsWith("logout_")).length
      };
    },

    buildLeadStats(rows){
      const list = Array.isArray(rows) ? rows : [];
      const agents = new Set(list.map((r) => safeTrim(r?.agent_id) || safeTrim(r?.agent_name)).filter(Boolean));
      return {
        total: list.length,
        agents: agents.size,
        opens: list.filter((r) => safeTrim(r?.event_type) === "lead_open").length,
        status: list.filter((r) => ["lead_status", "lead_irrelevant", "lead_closed"].includes(safeTrim(r?.event_type))).length
      };
    },

    renderKpis(stats, tab){
      const host = this.els.kpis;
      if(!host) return;
      const items = tab === "lead"
        ? [
          { label: "סה״כ פעולות", value: stats.total },
          { label: "נציגים פעילים", value: stats.agents },
          { label: "פתיחות ליד", value: stats.opens },
          { label: "שינויי סטטוס", value: stats.status }
        ]
        : [
          { label: "סה״כ אירועים", value: stats.total },
          { label: "נציגים פעילים", value: stats.agents },
          { label: "התחברויות", value: stats.logins },
          { label: "התנתקויות", value: stats.logouts }
        ];
      host.innerHTML = items.map((item) => `
        <div class="giActLog__kpi">
          <div class="giActLog__kpiValue">${escapeHtml(String(item.value))}</div>
          <div class="giActLog__kpiLabel">${escapeHtml(item.label)}</div>
        </div>
      `).join("");
    },

    renderSessionRows(rows){
      const sorted = (Array.isArray(rows) ? rows.slice() : [])
        .sort((a, b) => new Date(a?.event_at || 0) - new Date(b?.event_at || 0));
      const col = this._sessionColspan;
      if(!sorted.length){
        return `<tr><td class="giActLog__emptyCell muted" colspan="${col}">לא נרשמו אירועי התחברות בתאריך זה</td></tr>`;
      }
      return sorted.map((ev, idx) => {
        const tone = this.eventTone(ev?.event_type, "session");
        const fullWhen = formatActivityDateTimeFull(ev?.event_at);
        return `<tr class="giActLogTable__row giActLogTable__row--${tone}" title="${escapeHtml(fullWhen)}">
          <td class="giActLogTable__idx">${idx + 1}</td>
          <td class="giActLogTable__day">${escapeHtml(formatActivityWeekdayHe(ev?.event_at))}</td>
          <td class="giActLogTable__date">${escapeHtml(formatActivityDateHe(ev?.event_at))}</td>
          <td class="giActLogTable__agent">${this.renderAgentCell(ev)}</td>
          <td class="giActLogTable__role">${escapeHtml(this.agentRoleLabel(ev?.agent_role))}</td>
          <td class="giActLogTable__time">${escapeHtml(formatActivityClock(ev?.event_at))}</td>
          <td class="giActLogTable__action">${escapeHtml(this.eventLabel(ev?.event_type))}</td>
          <td class="giActLogTable__status"><span class="giActLog__pill giActLog__pill--${tone}">${escapeHtml(this.eventStatusText(ev?.event_type))}</span></td>
        </tr>`;
      }).join("");
    },

    renderLeadRows(rows){
      const sorted = (Array.isArray(rows) ? rows.slice() : [])
        .sort((a, b) => new Date(a?.event_at || 0) - new Date(b?.event_at || 0));
      const col = this._leadColspan;
      if(!sorted.length){
        return `<tr><td class="giActLog__emptyCell muted" colspan="${col}">לא נרשמה פעילות בלידים בתאריך זה</td></tr>`;
      }
      return sorted.map((ev, idx) => {
        const fullWhen = formatActivityDateTimeFull(ev?.event_at);
        const leadLabel = safeTrim(ev?.entity_label) || "—";
        const detail = safeTrim(ev?.detail_text) || "—";
        const entityId = safeTrim(ev?.entity_id);
        const detailFull = entityId ? `${detail}${detail !== "—" ? " · " : ""}מזהה ליד: ${entityId}` : detail;
        return `<tr class="giActLogTable__row giActLogTable__row--lead" title="${escapeHtml(fullWhen)}">
          <td class="giActLogTable__idx">${idx + 1}</td>
          <td class="giActLogTable__day">${escapeHtml(formatActivityWeekdayHe(ev?.event_at))}</td>
          <td class="giActLogTable__date">${escapeHtml(formatActivityDateHe(ev?.event_at))}</td>
          <td class="giActLogTable__agent">${this.renderAgentCell(ev)}</td>
          <td class="giActLogTable__role">${escapeHtml(this.agentRoleLabel(ev?.agent_role))}</td>
          <td class="giActLogTable__time">${escapeHtml(formatActivityClock(ev?.event_at))}</td>
          <td class="giActLogTable__action">${escapeHtml(this.eventLabel(ev?.event_type))}</td>
          <td class="giActLogTable__lead">${escapeHtml(leadLabel)}</td>
          <td class="giActLogTable__detail">${escapeHtml(detailFull)}</td>
        </tr>`;
      }).join("");
    },

    scopeHint(){
      if(Auth.isAdmin() || Auth.isManager()) return "כל הנציגים";
      if(Auth.isTeamManager()) return "נציגי הצוות שלך";
      return "";
    },

    async loadTabRows(tab, date, force){
      const key = tab === "lead" ? "lead" : "session";
      if(!force && this._cache[key].date === date && Array.isArray(this._cache[key].rows)){
        return { rows: this._cache[key].rows, error: "" };
      }
      const result = await AgentActivityLog.loadForDate(date, key);
      this._cache[key] = { date, rows: Array.isArray(result?.rows) ? result.rows : [] };
      return result;
    },

    paintTab(tab, rows, loadError, date){
      const tbody = tab === "lead" ? this.els.leadTbody : this.els.sessionTbody;
      const col = tab === "lead" ? this._leadColspan : this._sessionColspan;
      if(!tbody) return;
      tbody.dataset.loadedDate = date;
      if(loadError){
        tbody.innerHTML = `<tr><td class="giActLog__emptyCell giActLog__emptyCell--err" colspan="${col}">שגיאה בטעינת לוג: ${escapeHtml(loadError)}</td></tr>`;
        return;
      }
      tbody.innerHTML = tab === "lead" ? this.renderLeadRows(rows) : this.renderSessionRows(rows);
    },

    async render(force){
      if(!AgentActivityLog.canView()) return;
      const date = this.selectedDate();
      this._selectedDate = date;
      const tab = this._activeTab === "lead" ? "lead" : "session";
      const today = getIsraelDateString();
      if(this.els.btnNext) this.els.btnNext.disabled = date >= today;
      this.renderDateBanner(date);
      this.syncQuickDateButtons();
      if(this.els.hint){
        this.els.hint.textContent = tab === "lead"
          ? `פעילות בלידים לפי יום · ${this.scopeHint()}`
          : `התחברות והתנתקות לפי יום · ${this.scopeHint()}`;
      }
      const activeBody = this.activeTbody();
      if(activeBody && (force || activeBody.dataset.loadedDate !== date)){
        const col = tab === "lead" ? this._leadColspan : this._sessionColspan;
        activeBody.innerHTML = `<tr><td class="muted" colspan="${col}">טוען נתונים…</td></tr>`;
      }
      const sessionResult = await this.loadTabRows("session", date, force);
      const leadResult = await this.loadTabRows("lead", date, force);
      const sessionRows = Array.isArray(sessionResult?.rows) ? sessionResult.rows : [];
      const leadRows = Array.isArray(leadResult?.rows) ? leadResult.rows : [];
      this.paintTab("session", sessionRows, safeTrim(sessionResult?.error), date);
      this.paintTab("lead", leadRows, safeTrim(leadResult?.error), date);
      const stats = tab === "lead" ? this.buildLeadStats(leadRows) : this.buildSessionStats(sessionRows);
      this.renderKpis(stats, tab);
      if(this.els.meta){
        const updated = formatActivityClock(nowISO());
        const err = tab === "lead" ? safeTrim(leadResult?.error) : safeTrim(sessionResult?.error);
        this.els.meta.textContent = err
          ? `${this.formatDisplayDate(date)} · שגיאת טעינה · עודכן ${updated}`
          : `${this.formatDisplayDate(date)} · ${sessionRows.length} אירועי התחברות · ${leadRows.length} פעילויות לידים · עודכן ${updated}`;
      }
      AgentActivityLog.startRealtime(() => {
        if(UI.isSettingsRubricActive?.("activityLog")){
          this._cache.session.date = "";
          this._cache.lead.date = "";
          void this.render(true);
        }
      });
    },

    stopRealtime(){
      AgentActivityLog.stopRealtime();
    }
  };

  const MyTeamUI = {
    els: {},

    init(){
      this.els.tbody = document.getElementById("myTeamTbody");
      this.els.meta = document.getElementById("myTeamMeta");
      this.els.hint = document.getElementById("myTeamHint");
      this.els.btnRefresh = document.getElementById("btnMyTeamRefresh");
      if(this.els.btnRefresh){
        on(this.els.btnRefresh, "click", () => void this.render(true));
      }
    },

    formatMoney(value){
      return DashboardUI.formatMoney(value);
    },

    async render(showToast){
      if(!Auth.isTeamManager()) return;
      const tbody = this.els.tbody;
      if(!tbody) return;
      tbody.innerHTML = `<tr><td class="muted" colspan="8">טוען נתונים…</td></tr>`;
      try { await DashboardUI.ensureDailyReportLoaded(); } catch(_e) {}
      const managerId = safeTrim(Auth?.current?.id) || safeTrim(findAgentRecordForSession()?.id);
      const team = getManagedAgentRecordsForTeamManager(managerId);
      const monthLabel = DashboardUI.formatMonthTitle(new Date());
      if(this.els.meta){
        this.els.meta.textContent = team.length
          ? `${monthLabel} · ${team.length} נציגים משויכים`
          : "טרם שויכו נציגים — פנה למנהל המערכת להגדרה בניהול משתמשים";
      }
      if(!team.length){
        tbody.innerHTML = `<tr><td class="muted" colspan="8">אין נציגים משויכים לצוות שלך</td></tr>`;
        return;
      }
      const rows = team.map((agent) => {
        const m = computeAgentTeamSalesMetrics(agent);
        return {
          agent,
          metrics: m
        };
      }).sort((a, b) => b.metrics.todayPremium - a.metrics.todayPremium || safeTrim(a.agent.name).localeCompare(safeTrim(b.agent.name), "he"));
      tbody.innerHTML = rows.map(({ agent, metrics: m }) => `
        <tr>
          <td><strong>${escapeHtml(safeTrim(agent.name) || safeTrim(agent.id))}</strong></td>
          <td>${escapeHtml(this.formatMoney(m.todayPremium))}</td>
          <td>${escapeHtml(String(m.todayPolicies))}</td>
          <td dir="ltr">${escapeHtml(formatMyTeamDateTime(m.lastActivity))}</td>
          <td>${escapeHtml(this.formatMoney(m.monthPremium))}</td>
          <td>${escapeHtml(String(m.monthPolicies))}</td>
          <td>${escapeHtml(this.formatMoney(m.issuedPremium))}</td>
          <td>${escapeHtml(String(m.issuedPolicies))}</td>
        </tr>`).join("");
      if(showToast){
        try { window.showToast?.({ title: "הצוות שלי", text: "הנתונים עודכנו", variant: "ok", durationMs: 3200 }); } catch(_e) {}
      }
    }
  };

  const DailyReportUI = {
    els: {},
    activeRubric: "daily",
    searchQuery: "",
    filterAgent: "",
    filterStatus: "",
    filterTeam: "",
    filterPlan: "",
    _navFetchInFlight: false,
    _monthSelectBusy: false,
    _rubricEls: {},

    initRubrics(){
      this._rubricEls.tabDaily = document.getElementById("rubricTabDaily");
      this._rubricEls.tabCancellations = document.getElementById("rubricTabCancellations");
      this._rubricEls.panelDaily = document.getElementById("dailyReportPanelDaily");
      this._rubricEls.panelCancellations = document.getElementById("dailyReportPanelCancellations");
      this._rubricEls.btnBack = document.getElementById("btnReportsHubBack");
      this._rubricEls.navActionsDaily = document.getElementById("reportNavActionsDaily");
      this._rubricEls.navActionsCancellations = document.getElementById("reportNavActionsCancellations");
      if(this._rubricEls.tabDaily) on(this._rubricEls.tabDaily, "click", () => this.switchRubric("daily"));
      if(this._rubricEls.tabCancellations) on(this._rubricEls.tabCancellations, "click", () => this.switchRubric("cancellations"));
      if(this._rubricEls.btnBack) on(this._rubricEls.btnBack, "click", () => {
        try { UI.goView("reportsHub"); } catch(_e) {}
      });
      this.initReportsHub();
      this.applyRubricUi();
    },

    initReportsHub(){
      if(this._reportsHubBound) return;
      const hub = document.getElementById("view-reportsHub");
      if(!hub) return;
      this._reportsHubBound = true;
      hub.querySelectorAll("[data-report-open]").forEach((btn) => {
        on(btn, "click", () => {
          const which = safeTrim(btn.getAttribute("data-report-open"));
          this.openFromHub(which);
        });
      });
    },

    openFromHub(rubric){
      const next = rubric === "cancellations" ? "cancellations" : "daily";
      this.activeRubric = next;
      this.applyRubricUi();
      try { UI.goView("dailyReport"); } catch(_e) {}
    },

    syncPageTitle(){
      try {
        if(!UI?.els?.pageTitle) return;
        if(LiveRefresh.getCurrentView?.() !== "dailyReport" && !document.getElementById("view-dailyReport")?.classList.contains("is-visible")) return;
        UI.els.pageTitle.textContent = this.activeRubric === "cancellations" ? "דוח ביטולים" : "דוח מכירות";
      } catch(_e) {}
    },

    applyRubricUi(){
      const isCancellations = this.activeRubric === "cancellations";
      const { tabDaily, tabCancellations, panelDaily, panelCancellations } = this._rubricEls;
      if(tabDaily){
        tabDaily.classList.toggle("is-active", !isCancellations);
        tabDaily.setAttribute("aria-selected", String(!isCancellations));
      }
      if(tabCancellations){
        tabCancellations.classList.toggle("is-active", isCancellations);
        tabCancellations.setAttribute("aria-selected", String(isCancellations));
      }
      if(panelDaily){
        panelDaily.hidden = isCancellations;
        panelDaily.classList.toggle("is-active", !isCancellations);
      }
      if(panelCancellations){
        panelCancellations.hidden = !isCancellations;
        panelCancellations.classList.toggle("is-active", isCancellations);
      }
      // GI-NAV-ACTIONS: כפתורי שני הדוחות יושבים בשורת הניווט המשותפת,
      // ולכן כל סלוט מוצג רק כשהרובריקה שלו פעילה.
      if(this._rubricEls.navActionsDaily){
        this._rubricEls.navActionsDaily.hidden = isCancellations;
      }
      if(this._rubricEls.navActionsCancellations){
        this._rubricEls.navActionsCancellations.hidden = !isCancellations;
      }
      this.syncPageTitle();
    },

    switchRubric(rubric){
      const next = rubric === "cancellations" ? "cancellations" : "daily";
      this.activeRubric = next;
      this.applyRubricUi();
      if(next === "cancellations"){
        try { CancellationsUI.scheduleNavRender(); } catch(_e) {}
      } else {
        try { this.scheduleNavRender(); } catch(_e) {}
      }
    },

    init(){
      this.initRubrics();
      this.els.title = document.getElementById("dailyReportTitle");
      this.els.asOfLine = document.getElementById("dailyReportAsOfLine");
      // GI-PREMIUM-STATS: מוני פרמיה במקום שורת ההסבר הישנה (#dailyReportHint)
      this.els.premStats = document.getElementById("dailyReportPremStats");
      this.els.premIssuedValue = document.getElementById("dailyReportPremIssued");
      this.els.premIssuedSub = document.getElementById("dailyReportPremIssuedSub");
      this.els.premPendingValue = document.getElementById("dailyReportPremPending");
      this.els.premPendingSub = document.getElementById("dailyReportPremPendingSub");
      this.els.meta = document.getElementById("dailyReportMeta");
      this.els.alert = document.getElementById("dailyReportAlert");
      this.els.filters = document.getElementById("dailyReportFilters");
      this.els.search = document.getElementById("dailyReportSearch");
      this.els.filterAgent = document.getElementById("dailyReportFilterAgent");
      this.els.filterStatus = document.getElementById("dailyReportFilterStatus");
      this.els.filterTeam = document.getElementById("dailyReportFilterTeam");
      this.els.filterPlan = document.getElementById("dailyReportFilterPlan");
      this.els.btnClearFilters = document.getElementById("btnDailyReportClearFilters");
      this.els.asOfPickWrap = document.getElementById("dailyReportAsOfPickWrap");
      this.els.asOfDate = document.getElementById("dailyReportAsOfDate");
      this.els.monthPickWrap = document.getElementById("dailyReportMonthPickWrap");
      this.els.monthSelect = document.getElementById("dailyReportMonthSelect");
      this.els.thead = document.getElementById("dailyReportThead");
      this.els.tbody = document.getElementById("dailyReportTbody");
      this.els.btnUpload = document.getElementById("btnDailyReportUpload");
      this.els.btnExport = document.getElementById("btnDailyReportExport");
      this.els.btnRefresh = document.getElementById("btnDailyReportRefresh");
      this.els.fileInput = document.getElementById("dailyReportFileInput");
      if(this.els.btnExport) on(this.els.btnExport, "click", () => void this.exportToExcel());
      if(this.els.btnUpload) on(this.els.btnUpload, "click", () => this.onUploadClick());
      if(this.els.fileInput) on(this.els.fileInput, "change", (ev) => void this.onFileSelected(ev));
      if(this.els.btnRefresh) on(this.els.btnRefresh, "click", () => void this.refresh(true));
      if(this.els.monthSelect) on(this.els.monthSelect, "change", () => void this.onMonthSelectChange());
      if(this.els.search) on(this.els.search, "input", perfDebounce(() => {
        this.searchQuery = safeTrim(this.els.search?.value);
        this.paint();
      }, 200));
      const onFilterChange = () => {
        this.filterAgent = safeTrim(this.els.filterAgent?.value);
        this.filterStatus = safeTrim(this.els.filterStatus?.value);
        this.filterTeam = safeTrim(this.els.filterTeam?.value);
        this.filterPlan = safeTrim(this.els.filterPlan?.value);
        this.paint();
      };
      if(this.els.filterAgent) on(this.els.filterAgent, "change", onFilterChange);
      if(this.els.filterStatus) on(this.els.filterStatus, "change", onFilterChange);
      if(this.els.filterTeam) on(this.els.filterTeam, "change", onFilterChange);
      if(this.els.filterPlan) on(this.els.filterPlan, "change", onFilterChange);
      if(this.els.btnClearFilters) on(this.els.btnClearFilters, "click", () => this.clearFilters());
    },

    paintMonthSelect(){
      const el = this.els.monthSelect;
      const wrap = this.els.monthPickWrap;
      if(!el || !wrap) return;
      const months = Array.isArray(DailyReportStore.monthIndex) ? DailyReportStore.monthIndex : [];
      const selected = safeTrim(DailyReportStore.viewMonthKey);
      const opts = [`<option value="">דוח נוכחי</option>`]
        .concat(months.map((m) => {
          const key = safeTrim(m?.monthKey);
          if(!key) return "";
          return `<option value="${escapeHtml(key)}">${escapeHtml(formatDailyReportMonthLabel(key))}</option>`;
        }).filter(Boolean));
      this._monthSelectBusy = true;
      try {
        el.innerHTML = opts.join("");
        el.value = months.some((m) => safeTrim(m?.monthKey) === selected) ? selected : "";
        if(el.value !== selected && selected){
          // חודש נבחר שלא ברשימה — מציגים בכל זאת
          el.insertAdjacentHTML("beforeend", `<option value="${escapeHtml(selected)}">${escapeHtml(formatDailyReportMonthLabel(selected))}</option>`);
          el.value = selected;
        }
      } finally {
        this._monthSelectBusy = false;
      }
      wrap.hidden = false;
    },

    async onMonthSelectChange(){
      if(this._monthSelectBusy) return;
      const monthKey = safeTrim(this.els.monthSelect?.value);
      this.clearFilters();
      this.showAlert(monthKey ? "טוען דוח חודשי…" : "טוען דוח נוכחי…", "warn");
      const r = await DailyReportStore.selectViewMonth(monthKey);
      if(!r.ok){
        this.showAlert(r.error || DailyReportStore.archiveLastError || "טעינת חודש נכשלה", "err");
        this.paintMonthSelect();
        this.paint();
        return;
      }
      this.showAlert("");
      this.paint();
    },

    async exportToExcel(){
      try {
        if(window.GI_LOAD_LIBS?.xlsx) await window.GI_LOAD_LIBS.xlsx();
        if(typeof window === "undefined" || !window.XLSX){
          this.showAlert("ספריית Excel לא נטענה — רענן את הדף ונסה שוב", "err");
          return;
        }
        const report = DailyReportStore.getViewReport();
        if(!report || !Array.isArray(report.headerRow) || !report.headerRow.length){
          this.showAlert("טרם הועלה דוח יומי", "warn");
          return;
        }
        const headers = report.headerRow.map((h) => safeTrim(h) || "—");
        const colCount = headers.length;
        const rows = (Auth.isAdmin() || Auth.isManager())
          ? (Array.isArray(report.dataRows) ? report.dataRows : [])
          : DailyReportStore.getVisibleRowsFor(report);
        if(!rows.length){
          this.showAlert("אין שורות לייצוא", "warn");
          return;
        }
        const dataRows = rows.map((row) => {
          const cells = Array.isArray(row.cells) ? row.cells : [];
          const out = [];
          for(let i = 0; i < colCount; i += 1){
            out.push(safeTrim(cells[i]));
          }
          return out;
        });
        const flipRow = (row) => row.slice().reverse();
        const wsData = [flipRow(headers), ...dataRows.map(flipRow)];
        const wb = window.XLSX.utils.book_new();
        const ws = window.XLSX.utils.aoa_to_sheet(wsData);
        if(!ws["!opts"]) ws["!opts"] = {};
        ws["!opts"].RTL = true;
        const sheetLabel = safeTrim(report.sheetName) || "דוח יומי";
        window.XLSX.utils.book_append_sheet(wb, ws, sheetLabel.slice(0, 31));
        const now = new Date();
        const ds = [now.getFullYear(), String(now.getMonth() + 1).padStart(2, "0"), String(now.getDate()).padStart(2, "0")].join("-");
        const viewMonth = safeTrim(DailyReportStore.viewMonthKey);
        const asOf = normalizeDailyReportAsOfInput(report.reportAsOfDate);
        let fileName = viewMonth ? "דוח_מכירות_חודשי_GEMEL_INVEST" : "דוח_יומי_GEMEL_INVEST";
        if(viewMonth) fileName += "_" + viewMonth;
        else if(asOf) fileName += "_" + asOf;
        else fileName += "_" + ds;
        if(!Auth.isAdmin() && !Auth.isManager()){
          const agentName = safeTrim(Auth?.current?.name) || safeTrim(Auth?.current?.username) || "נציג";
          fileName += "_" + agentName.replace(/[^\w\u0590-\u05FF]+/g, "_");
        }
        fileName += ".xlsx";
        window.XLSX.writeFile(wb, fileName);
        if(typeof toast === "function") toast(viewMonth ? "דוח חודשי הופק" : "דוח יומי הופק", fileName);
      } catch(err) {
        console.error("dailyReport exportToExcel error:", err);
        this.showAlert("שגיאה בייצוא: " + (err?.message || err), "err");
      }
    },

    onUploadClick(){
      if(!Auth.canUploadDailyReport()) return;
      const asOf = normalizeDailyReportAsOfInput(this.els.asOfDate?.value);
      if(!asOf){
        this.showAlert('יש לבחור "תאריך עדכון הדוח" לפני העלאת הקובץ', "err");
        try { this.els.asOfDate?.focus(); } catch(_e) {}
        return;
      }
      this.showAlert("");
      this.els.fileInput?.click();
    },

    clearFilters(){
      this._filterOptionsStamp = "";
      this.searchQuery = "";
      this.filterAgent = "";
      this.filterStatus = "";
      this.filterTeam = "";
      this.filterPlan = "";
      if(this.els.search) this.els.search.value = "";
      if(this.els.filterAgent) this.els.filterAgent.value = "";
      if(this.els.filterStatus) this.els.filterStatus.value = "";
      if(this.els.filterTeam) this.els.filterTeam.value = "";
      if(this.els.filterPlan) this.els.filterPlan.value = "";
      this.paint();
    },

    hasActiveFilters(){
      return !!(safeTrim(this.searchQuery) || safeTrim(this.filterAgent) || safeTrim(this.filterStatus)
        || safeTrim(this.filterTeam) || safeTrim(this.filterPlan));
    },

    getColumnIndexes(report){
      return getDailyReportColumnIndexes(report);
    },

    collectUniqueColumnValues(rows, colIdx){
      const set = new Set();
      if(colIdx < 0) return [];
      (rows || []).forEach((row) => {
        const val = getDailyReportCell(row, colIdx);
        if(val) set.add(val);
      });
      return Array.from(set).sort((a, b) => a.localeCompare(b, "he"));
    },

    paintFilterOptions(report){
      const stamp = report
        ? safeTrim(report.uploadedAt) + "|" + (report.dataRows?.length || 0) + "|" + (report.headerRow?.length || 0) + "|" + safeTrim(DailyReportStore.viewMonthKey)
        : "|" + safeTrim(DailyReportStore.viewMonthKey);
      const syncValues = () => {
        if(this.els.filterAgent && !this.els.filterAgent.hidden) this.els.filterAgent.value = this.filterAgent;
        if(this.els.filterStatus) this.els.filterStatus.value = this.filterStatus;
        if(this.els.filterTeam) this.els.filterTeam.value = this.filterTeam;
        if(this.els.filterPlan) this.els.filterPlan.value = this.filterPlan;
      };
      if(stamp && this._filterOptionsStamp === stamp){
        syncValues();
        return;
      }
      this._filterOptionsStamp = stamp;
      const viewReport = DailyReportStore.getViewReport();
      const baseRows = DailyReportStore.getVisibleRowsFor(viewReport);
      const cols = this.getColumnIndexes(report);
      const fillSelect = (el, placeholder, values, current) => {
        if(!el) return;
        const opts = [`<option value="">${escapeHtml(placeholder)}</option>`]
          .concat(values.map((v) => `<option value="${escapeHtml(v)}">${escapeHtml(v)}</option>`));
        el.innerHTML = opts.join("");
        el.value = values.includes(current) ? current : "";
      };
      const canPickAgent = Auth.isAdmin() || Auth.isManager() || Auth.isTeamManager();
      if(this.els.filterAgent){
        this.els.filterAgent.hidden = !canPickAgent;
        if(canPickAgent){
          let agents = DailyReportStore.getAgentSummaryFor(viewReport).map(([name]) => name).filter((n) => n && n !== "— ללא נציג");
          if(Auth.isTeamManager()){
            const allowed = new Set(
              getManagedAgentRecordsForTeamManager(safeTrim(Auth?.current?.id))
                .flatMap((a) => {
                  const keys = [];
                  const n = normalizeDailyReportAgentKey(a?.name);
                  const u = normalizeDailyReportAgentKey(a?.username);
                  if(n) keys.push(n);
                  if(u) keys.push(u);
                  return keys;
                })
            );
            agents = agents.filter((name) => allowed.has(normalizeDailyReportAgentKey(name)));
          }
          fillSelect(this.els.filterAgent, "נציג — הכל", agents, this.filterAgent);
        }
      }
      fillSelect(this.els.filterStatus, "סטטוס — הכל", this.collectUniqueColumnValues(baseRows, cols.status), this.filterStatus);
      fillSelect(this.els.filterTeam, "צוות — הכל", this.collectUniqueColumnValues(baseRows, cols.team), this.filterTeam);
      fillSelect(this.els.filterPlan, "תוכנית — הכל", this.collectUniqueColumnValues(baseRows, cols.plan), this.filterPlan);
      syncValues();
    },

    showAlert(msg, tone = "warn"){
      if(!this.els.alert) return;
      if(!msg){
        this.els.alert.hidden = true;
        this.els.alert.textContent = "";
        this.els.alert.className = "lcDailyReport__alert";
        return;
      }
      this.els.alert.hidden = false;
      this.els.alert.textContent = msg;
      this.els.alert.className = "lcDailyReport__alert lcDailyReport__alert--" + (tone === "err" ? "err" : tone === "ok" ? "ok" : "warn");
    },

    async onFileSelected(ev){
      if(!Auth.canUploadDailyReport()) return;
      const file = ev?.target?.files?.[0];
      try { if(ev?.target) ev.target.value = ""; } catch(_e) {}
      if(!file) return;
      const reportAsOfDate = normalizeDailyReportAsOfInput(this.els.asOfDate?.value);
      if(!reportAsOfDate){
        this.showAlert('יש לבחור "תאריך עדכון הדוח" לפני העלאת הקובץ', "err");
        return;
      }
      const name = safeTrim(file.name).toLowerCase();
      if(name && !/\.(xlsx|xls|csv)$/.test(name)){
        this.showAlert("יש לבחור קובץ Excel (.xlsx, .xls) או CSV", "err");
        return;
      }
      this.showAlert("מעבד ושומר את הדוח…", "warn");
      if(this.els.btnUpload) this.els.btnUpload.disabled = true;
      try {
        if(window.GI_LOAD_LIBS?.xlsx) await window.GI_LOAD_LIBS.xlsx();
      } catch(loadErr) {
        this.showAlert("ספריית Excel לא נטענה — בדוק חיבור לאינטרנט ורענן את הדף", "err");
        if(this.els.btnUpload) this.els.btnUpload.disabled = false;
        return;
      }
      const parsed = await parseDailyReportWorkbook(file);
      if(!parsed.ok){
        this.showAlert(parsed.error || "שגיאה בקריאת הקובץ", "err");
        if(this.els.btnUpload) this.els.btnUpload.disabled = false;
        return;
      }
      const stamp = nowISO();
      this.clearFilters();
      const payload = {
        uploadedAt: stamp,
        uploadedByName: safeTrim(Auth?.current?.name) || "מנהל",
        reportAsOfDate,
        sheetName: parsed.sheetName,
        headerRow: parsed.headerRow,
        dataRows: parsed.dataRows
      };
      const monthKey = dailyReportMonthKeyFromAsOf(reportAsOfDate);
      const updateActive = isDailyReportAsOfInCurrentMonth(reportAsOfDate);

      if(updateActive){
        const save = await DailyReportStore.saveActive(payload);
        if(this.els.btnUpload) this.els.btnUpload.disabled = false;
        if(!save.ok){
          this.showAlert("שמירה נכשלה: " + (save.error || ""), "err");
          return;
        }
        const arch = await DailyReportStore.saveMonthArchive(payload);
        await DailyReportStore.selectViewMonth("");
        await DailyReportStore.listMonthArchives();
        this.paint();
        if(typeof toast === "function") toast("דוח יומי הועלה", formatDailyReportUploadDate(stamp));
        if(arch.ok){
          this.showAlert("הדוח נשמר בהצלחה — " + parsed.dataRows.length + " שורות · עודכן גם ארכיון " + formatDailyReportMonthLabel(monthKey), "ok");
        } else {
          this.showAlert("הדוח היומי נשמר (" + parsed.dataRows.length + " שורות), אך ארכיון חודשי נכשל: " + (arch.error || DailyReportStore.archiveLastError || ""), "warn");
        }
      } else {
        const arch = await DailyReportStore.saveMonthArchive(payload);
        if(this.els.btnUpload) this.els.btnUpload.disabled = false;
        if(!arch.ok){
          this.showAlert("שמירת ארכיון חודשי נכשלה: " + (arch.error || ""), "err");
          return;
        }
        await DailyReportStore.listMonthArchives();
        await DailyReportStore.selectViewMonth(monthKey);
        this.paint();
        if(typeof toast === "function") toast("ארכיון חודשי עודכן", formatDailyReportMonthLabel(monthKey));
        this.showAlert(
          "הדוח נשמר לארכיון " + formatDailyReportMonthLabel(monthKey)
            + " — " + parsed.dataRows.length + " שורות (הדוח היומי הנוכחי לא שונה)",
          "ok"
        );
      }
      try {
        if(updateActive && LiveRefresh.getCurrentView() === "dashboard" && DashboardUI.els?.root?.querySelector(".bankDash__kpis")) {
          DashboardUI.refreshKpis();
        }
        if(updateActive && LiveRefresh.getCurrentView() === "myTeam") void MyTeamUI.render();
      } catch(_e){}
    },

    paintHeader(report){
      if(!this.els.thead) return;
      const headers = Array.isArray(report?.headerRow) ? report.headerRow : [];
      if(!headers.length){
        this.els.thead.innerHTML = "<tr><th class=\"muted\">—</th></tr>";
        return;
      }
      this.els.thead.innerHTML = "<tr>" + headers.map((h) => `<th>${escapeHtml(h || "—")}</th>`).join("") + "</tr>";
    },

    paintBody(report, rows){
      if(!this.els.tbody) return;
      const headers = Array.isArray(report?.headerRow) ? report.headerRow : [];
      const colCount = Math.max(headers.length, 1);
      if(!report){
        this.els.tbody.innerHTML = `<tr><td colspan="${colCount}" class="muted">טרם הועלה דוח יומי</td></tr>`;
        return;
      }
      if(!rows.length){
        const msg = Auth.isAdmin() || Auth.isManager()
          ? "אין שורות להצגה (נסה לשנות חיפוש)"
          : Auth.isTeamManager()
            ? "אין שורות בדוח עבור הצוות שלך — נסה לשנות סינון או ודא ששמות הנציגים בעמודת \"נציג\" תואמים למערכת"
            : 'אין שורות בדוח עבורך — ודא ששמך בעמודת "נציג" תואם לשם במערכת (גם אם סדר השם שונה)';
        this.els.tbody.innerHTML = `<tr><td colspan="${colCount}" class="muted">${escapeHtml(msg)}</td></tr>`;
        return;
      }
      this.els.tbody.innerHTML = rows.map((row) => {
        const cells = Array.isArray(row.cells) ? row.cells : [];
        const tds = [];
        for(let i = 0; i < colCount; i += 1){
          const val = safeTrim(cells[i]);
          const hdr = safeTrim(headers[i]).toLowerCase();
          const isPhone = hdr.includes("טלפון") || hdr.includes("פוליסה") || hdr.includes("תז");
          tds.push(`<td${isPhone ? ' dir="ltr"' : ""}>${escapeHtml(val)}</td>`);
        }
        return `<tr>${tds.join("")}</tr>`;
      }).join("");
    },

    paintMeta(report, filteredCount, totalVisible){
      if(!this.els.meta) return;
      if(!report){
        this.els.meta.textContent = Auth.canUploadDailyReport()
          ? 'העלה קובץ Excel — העמודה "נציג" קובעת אילו שורות יראה כל נציג'
          : "";
        return;
      }
      const uploadLabel = formatDailyReportUploadDate(report.uploadedAt);
      const parts = [`תאריך העלאה: ${uploadLabel}`];
      const viewMonth = safeTrim(DailyReportStore.viewMonthKey);
      if(viewMonth) parts.unshift("ארכיון: " + formatDailyReportMonthLabel(viewMonth));
      if(safeTrim(report.uploadedByName)) parts.push("הועלה על ידי: " + report.uploadedByName);
      if(safeTrim(report.sheetName)) parts.push("גיליון: " + report.sheetName);
      const total = Number(totalVisible) || 0;
      const shown = Number(filteredCount) || 0;
      parts.push(this.hasActiveFilters() ? `מוצגות ${shown} מתוך ${total} שורות` : `מוצגות ${shown} שורות`);
      if(Auth.isAdmin() || Auth.isManager()){
        const summary = DailyReportStore.getAgentSummaryFor(report);
        if(summary.length){
          parts.push("פילוח: " + summary.map(([name, cnt]) => `${name} (${cnt})`).join(" · "));
        }
      }
      this.els.meta.textContent = parts.join(" · ");
    },

    paintTitle(report){
      if(this.els.title) this.els.title.textContent = "דוח יומי";
      const viewMonth = safeTrim(DailyReportStore.viewMonthKey);
      const asOfLabel = report ? formatDailyReportAsOfDate(report.reportAsOfDate) : "";
      if(this.els.asOfLine){
        if(viewMonth && asOfLabel){
          this.els.asOfLine.hidden = false;
          this.els.asOfLine.textContent = formatDailyReportMonthLabel(viewMonth) + " · נכון לתאריך " + asOfLabel;
        } else if(asOfLabel){
          this.els.asOfLine.hidden = false;
          this.els.asOfLine.textContent = "נכון לתאריך " + asOfLabel;
        } else if(viewMonth){
          this.els.asOfLine.hidden = false;
          this.els.asOfLine.textContent = "ארכיון " + formatDailyReportMonthLabel(viewMonth);
        } else {
          this.els.asOfLine.hidden = true;
          this.els.asOfLine.textContent = "";
        }
      }
      // GI-PREMIUM-STATS: המלל ההסברי הוסר מהכותרת והוחלף במוני פרמיה (paintPremiumStats).
      const canUpload = Auth.canUploadDailyReport();
      if(this.els.asOfPickWrap) this.els.asOfPickWrap.hidden = !canUpload;
      // לא לדרוס את תאריך ההעלאה כשצופים בארכיון חודשי.
      if(this.els.asOfDate && canUpload && report?.reportAsOfDate && !viewMonth){
        this.els.asOfDate.value = normalizeDailyReportAsOfInput(report.reportAsOfDate);
      }
    },

    // GI-PREMIUM-STATS
    formatPremiumStatMoney(v){
      const n = Number(v);
      if(!Number.isFinite(n) || n <= 0) return "₪0";
      const rounded = Math.round(n * 100) / 100;
      try {
        return "₪" + rounded.toLocaleString("he-IL", { minimumFractionDigits: 0, maximumFractionDigits: 2 });
      } catch(_e) {
        return "₪" + rounded;
      }
    },

    computePremiumStats(report, rows){
      const out = { issuedPremium: 0, issuedCount: 0, pendingPremium: 0, pendingCount: 0, hasStatusCol: false };
      if(!report) return out;
      const cols = this.getColumnIndexes(report);
      if(cols.status < 0) return out;
      out.hasStatusCol = true;
      (rows || []).forEach((row) => {
        const status = getDailyReportCell(row, cols.status);
        if(isDailyReportIssuedStatus(status)){
          out.issuedCount += 1;
          out.issuedPremium += getDailyReportIssuedPremiumValue(row, cols);
        } else if(isDailyReportPendingIssueStatus(status)){
          out.pendingCount += 1;
          out.pendingPremium += getDailyReportPendingPremiumValue(row, cols);
        }
      });
      out.issuedPremium = Math.round(out.issuedPremium * 100) / 100;
      out.pendingPremium = Math.round(out.pendingPremium * 100) / 100;
      return out;
    },

    paintPremiumStats(report, rows){
      const wrap = this.els.premStats;
      if(!wrap) return;
      if(!report){
        wrap.hidden = true;
        return;
      }
      const stats = this.computePremiumStats(report, rows);
      if(!stats.hasStatusCol){
        wrap.hidden = true;
        return;
      }
      wrap.hidden = false;
      const policyWord = (n) => (Number(n) === 1 ? "פוליסה" : "פוליסות");
      if(this.els.premIssuedValue) this.els.premIssuedValue.textContent = this.formatPremiumStatMoney(stats.issuedPremium);
      if(this.els.premIssuedSub) this.els.premIssuedSub.textContent = `${stats.issuedCount} ${policyWord(stats.issuedCount)}`;
      if(this.els.premPendingValue) this.els.premPendingValue.textContent = this.formatPremiumStatMoney(stats.pendingPremium);
      if(this.els.premPendingSub) this.els.premPendingSub.textContent = `${stats.pendingCount} ${policyWord(stats.pendingCount)}`;
      wrap.classList.toggle("is-filtered", this.hasActiveFilters());
    },

    getFilteredRows(){
      const report = DailyReportStore.getViewReport();
      const cols = this.getColumnIndexes(report);
      const q = safeTrim(this.searchQuery).toLowerCase();
      const fAgent = safeTrim(this.filterAgent);
      const fStatus = safeTrim(this.filterStatus);
      const fTeam = safeTrim(this.filterTeam);
      const fPlan = safeTrim(this.filterPlan);
      let rows = DailyReportStore.getVisibleRowsFor(report);
      if(fAgent){
        rows = rows.filter((row) => normalizeDailyReportAgentKey(row.agent) === fAgent);
      }
      if(fStatus && cols.status >= 0){
        rows = rows.filter((row) => getDailyReportCell(row, cols.status) === fStatus);
      }
      if(fTeam && cols.team >= 0){
        rows = rows.filter((row) => getDailyReportCell(row, cols.team) === fTeam);
      }
      if(fPlan && cols.plan >= 0){
        rows = rows.filter((row) => getDailyReportCell(row, cols.plan) === fPlan);
      }
      if(!q) return rows;
      return rows.filter((row) => {
        const blob = (row.cells || []).join(" ").toLowerCase();
        return blob.includes(q) || safeTrim(row.agent).toLowerCase().includes(q);
      });
    },

    paint(){
      const report = DailyReportStore.getViewReport();
      const totalVisible = DailyReportStore.getVisibleRowsFor(report).length;
      const rows = this.getFilteredRows();
      const canUpload = Auth.canUploadDailyReport();
      if(this.els.btnUpload){
        this.els.btnUpload.hidden = !canUpload;
        this.els.btnUpload.disabled = false;
      }
      if(this.els.btnExport) this.els.btnExport.hidden = !report;
      if(this.els.btnRefresh) this.els.btnRefresh.hidden = !canUpload;
      if(this.els.fileInput) this.els.fileInput.hidden = !canUpload;
      if(this.els.filters) this.els.filters.hidden = !report;
      this.paintMonthSelect();
      if(report) this.paintFilterOptions(report);
      if(!DailyReportStore.tableReady){
        this.showAlert("יש להריץ את supabase/gi-daily-report-schema.sql ב-Supabase (טבלה gi_daily_report)", "warn");
      } else if(!report && canUpload && !safeTrim(DailyReportStore.viewMonthKey)) {
        this.showAlert("", "ok");
      } else if(!report && safeTrim(DailyReportStore.viewMonthKey)) {
        this.showAlert("לא נמצא דוח לחודש שנבחר", "warn");
      } else {
        this.showAlert("");
      }
      this.paintTitle(report);
      this.paintPremiumStats(report, rows);
      this.paintMeta(report, rows.length, totalVisible);
      this.paintHeader(report);
      this.paintBody(report, rows);
    },

    showLoadingShell(){
      if(!this.els.thead) this.init();
      if(this.els.thead){
        this.els.thead.innerHTML = '<tr><th class="muted">טוען דוח יומי…</th></tr>';
      }
      if(this.els.tbody){
        this.els.tbody.innerHTML = '<tr><td class="muted">טוען נתונים מהשרת…</td></tr>';
      }
      if(this.els.meta) this.els.meta.textContent = "טוען…";
      if(this.els.filters) this.els.filters.hidden = true;
      if(this.els.alert){
        this.els.alert.hidden = true;
        this.els.alert.textContent = "";
      }
    },

    scheduleNavRender(){
      if(!Auth.current) return;
      if(this.activeRubric === "cancellations"){
        try { CancellationsUI.scheduleNavRender(); } catch(_e) {}
        return;
      }
      if(!this.els.thead) this.init();
      const hadCache = !!DailyReportStore.getViewReport();
      if(hadCache){
        try { this.paint(); } catch(_e) {}
      } else {
        try { this.showLoadingShell(); } catch(_e) {}
      }
      if(this._navFetchInFlight) return;
      this._navFetchInFlight = true;
      perfIdle(() => {
        void (async () => {
          try {
            await this.refresh(false, { onlyIfVisible: true });
          } finally {
            this._navFetchInFlight = false;
          }
        })();
      }, hadCache ? 120 : 80);
    },

    async refresh(showToast, options = {}){
      const r = await DailyReportStore.fetchActive();
      if(!r.ok && DailyReportStore.lastError){
        this.showAlert("לא נטען דוח: " + DailyReportStore.lastError, "err");
      }
      await DailyReportStore.listMonthArchives();
      const viewMonth = safeTrim(DailyReportStore.viewMonthKey);
      if(viewMonth){
        const arch = await DailyReportStore.fetchMonthArchive(viewMonth);
        if(!arch.ok){
          DailyReportStore.viewMonthKey = "";
          DailyReportStore.archiveReport = null;
        }
      }
      if(options.onlyIfVisible && LiveRefresh.getCurrentView() !== "dailyReport") return;
      this.paint();
      if(showToast && typeof toast === "function" && r.ok) toast("דוח יומי עודכן");
      try {
        if(LiveRefresh.getCurrentView() === "dashboard" && DashboardUI.els?.root?.querySelector(".bankDash__kpis")) {
          DashboardUI.refreshKpis();
        }
        if(LiveRefresh.getCurrentView() === "myTeam") void MyTeamUI.render();
      } catch(_e){}
    },

    async render(){
      if(!Auth.current) return;
      this.scheduleNavRender();
    }
  };

  const CancellationsUI = {
    els: {},
    activeSheetName: "",
    searchQuery: "",
    filterAgent: "",
    filterTeam: "",
    filterStatus: "",
    _navFetchInFlight: false,
    _filterOptionsStamp: "",

    init(){
      this.els.title = document.getElementById("cancellationsTitle");
      this.els.asOfLine = document.getElementById("cancellationsAsOfLine");
      // GI-CANCEL-STATS: מוני פרמיה במקום שורת ההסבר הישנה (#cancellationsHint)
      this.els.stats = document.getElementById("cancellationsStats");
      this.els.meta = document.getElementById("cancellationsMeta");
      this.els.alert = document.getElementById("cancellationsAlert");
      this.els.sheetTabs = document.getElementById("cancellationsSheetTabs");
      this.els.filters = document.getElementById("cancellationsFilters");
      this.els.search = document.getElementById("cancellationsSearch");
      this.els.filterAgent = document.getElementById("cancellationsFilterAgent");
      this.els.filterTeam = document.getElementById("cancellationsFilterTeam");
      this.els.filterStatus = document.getElementById("cancellationsFilterStatus");
      this.els.btnClearFilters = document.getElementById("btnCancellationsClearFilters");
      this.els.asOfPickWrap = document.getElementById("cancellationsAsOfPickWrap");
      this.els.asOfDate = document.getElementById("cancellationsAsOfDate");
      this.els.thead = document.getElementById("cancellationsThead");
      this.els.tbody = document.getElementById("cancellationsTbody");
      this.els.btnUpload = document.getElementById("btnCancellationsUpload");
      this.els.btnExport = document.getElementById("btnCancellationsExport");
      this.els.btnRefresh = document.getElementById("btnCancellationsRefresh");
      this.els.fileInput = document.getElementById("cancellationsFileInput");
      if(this.els.btnExport) on(this.els.btnExport, "click", () => void this.exportToExcel());
      if(this.els.btnUpload) on(this.els.btnUpload, "click", () => this.onUploadClick());
      if(this.els.fileInput) on(this.els.fileInput, "change", (ev) => void this.onFileSelected(ev));
      if(this.els.btnRefresh) on(this.els.btnRefresh, "click", () => void this.refresh(true));
      if(this.els.search) on(this.els.search, "input", perfDebounce(() => {
        this.searchQuery = safeTrim(this.els.search?.value);
        this.paint();
      }, 200));
      const onFilterChange = () => {
        this.filterAgent = safeTrim(this.els.filterAgent?.value);
        this.filterTeam = safeTrim(this.els.filterTeam?.value);
        this.filterStatus = safeTrim(this.els.filterStatus?.value);
        this.paint();
      };
      if(this.els.filterAgent) on(this.els.filterAgent, "change", onFilterChange);
      if(this.els.filterTeam) on(this.els.filterTeam, "change", onFilterChange);
      if(this.els.filterStatus) on(this.els.filterStatus, "change", onFilterChange);
      if(this.els.btnClearFilters) on(this.els.btnClearFilters, "click", () => this.clearFilters());
    },

    getSheets(){
      return CancellationsStore.getSheets();
    },

    getActiveSheet(){
      const sheets = this.getSheets();
      if(!sheets.length) return null;
      const found = sheets.find((s) => safeTrim(s.sheetName) === safeTrim(this.activeSheetName));
      return found || sheets[0];
    },

    clearFilters(){
      this._filterOptionsStamp = "";
      this.searchQuery = "";
      this.filterAgent = "";
      this.filterTeam = "";
      this.filterStatus = "";
      if(this.els.search) this.els.search.value = "";
      if(this.els.filterAgent) this.els.filterAgent.value = "";
      if(this.els.filterTeam) this.els.filterTeam.value = "";
      if(this.els.filterStatus) this.els.filterStatus.value = "";
      this.paint();
    },

    hasActiveFilters(){
      return !!(safeTrim(this.searchQuery) || safeTrim(this.filterAgent) || safeTrim(this.filterTeam) || safeTrim(this.filterStatus));
    },

    showAlert(msg, tone = "warn"){
      if(!this.els.alert) return;
      if(!msg){
        this.els.alert.hidden = true;
        this.els.alert.textContent = "";
        this.els.alert.className = "lcDailyReport__alert";
        return;
      }
      this.els.alert.hidden = false;
      this.els.alert.textContent = msg;
      this.els.alert.className = "lcDailyReport__alert lcDailyReport__alert--" + (tone === "err" ? "err" : tone === "ok" ? "ok" : "warn");
    },

    onUploadClick(){
      if(!Auth.canUploadDailyReport()) return;
      const asOf = normalizeDailyReportAsOfInput(this.els.asOfDate?.value);
      if(!asOf){
        this.showAlert('יש לבחור "תאריך עדכון הדוח" לפני העלאת הקובץ', "err");
        try { this.els.asOfDate?.focus(); } catch(_e) {}
        return;
      }
      this.showAlert("");
      this.els.fileInput?.click();
    },

    async onFileSelected(ev){
      if(!Auth.canUploadDailyReport()) return;
      const file = ev?.target?.files?.[0];
      try { if(ev?.target) ev.target.value = ""; } catch(_e) {}
      if(!file) return;
      const reportAsOfDate = normalizeDailyReportAsOfInput(this.els.asOfDate?.value);
      if(!reportAsOfDate){
        this.showAlert('יש לבחור "תאריך עדכון הדוח" לפני העלאת הקובץ', "err");
        return;
      }
      const name = safeTrim(file.name).toLowerCase();
      if(name && !/\.(xlsx|xls|csv)$/.test(name)){
        this.showAlert("יש לבחור קובץ Excel (.xlsx, .xls) או CSV", "err");
        return;
      }
      this.showAlert("מעבד ושומר את הדוח…", "warn");
      if(this.els.btnUpload) this.els.btnUpload.disabled = true;
      try {
        if(window.GI_LOAD_LIBS?.xlsx) await window.GI_LOAD_LIBS.xlsx();
      } catch(loadErr) {
        this.showAlert("ספריית Excel לא נטענה — בדוק חיבור לאינטרנט ורענן את הדף", "err");
        if(this.els.btnUpload) this.els.btnUpload.disabled = false;
        return;
      }
      const parsed = await parseCancellationsWorkbook(file);
      if(!parsed.ok){
        this.showAlert(parsed.error || "שגיאה בקריאת הקובץ", "err");
        if(this.els.btnUpload) this.els.btnUpload.disabled = false;
        return;
      }
      const stamp = nowISO();
      this.clearFilters();
      const save = await CancellationsStore.saveActive({
        uploadedAt: stamp,
        uploadedByName: safeTrim(Auth?.current?.name) || "מנהל",
        reportAsOfDate,
        sheets: parsed.sheets
      });
      if(this.els.btnUpload) this.els.btnUpload.disabled = false;
      if(!save.ok){
        this.showAlert("שמירה נכשלה: " + (save.error || ""), "err");
        return;
      }
      const totalRows = parsed.sheets.reduce((sum, s) => sum + (s.dataRows?.length || 0), 0);
      if(typeof toast === "function") toast("דוח ביטולים הועלה", formatDailyReportUploadDate(stamp));
      this.showAlert("הדוח נשמר בהצלחה — " + parsed.sheets.length + " גיליונות, " + totalRows + " שורות", "ok");
      this.activeSheetName = safeTrim(parsed.sheets[0]?.sheetName);
      this.paint();
    },

    async exportToExcel(){
      try {
        if(window.GI_LOAD_LIBS?.xlsx) await window.GI_LOAD_LIBS.xlsx();
        if(typeof window === "undefined" || !window.XLSX){
          this.showAlert("ספריית Excel לא נטענה — רענן את הדף ונסה שוב", "err");
          return;
        }
        const sheets = this.getSheets();
        if(!sheets.length){
          this.showAlert("טרם הועלה דוח ביטולים", "warn");
          return;
        }
        const isFull = Auth.isAdmin() || Auth.isManager();
        const wb = window.XLSX.utils.book_new();
        const flipRow = (row) => row.slice().reverse();
        let usedNames = new Set();
        let exportedAny = false;
        sheets.forEach((sheet) => {
          const headers = (Array.isArray(sheet.headerRow) ? sheet.headerRow : []).map((h) => safeTrim(h) || "—");
          const colCount = headers.length;
          if(!colCount) return;
          const rows = isFull
            ? (Array.isArray(sheet.dataRows) ? sheet.dataRows : [])
            : CancellationsStore.getVisibleRowsForSheet(sheet);
          const dataRows = rows.map((row) => {
            const cells = Array.isArray(row.cells) ? row.cells : [];
            const out = [];
            for(let i = 0; i < colCount; i += 1) out.push(safeTrim(cells[i]));
            return out;
          });
          const wsData = [flipRow(headers), ...dataRows.map(flipRow)];
          const ws = window.XLSX.utils.aoa_to_sheet(wsData);
          if(!ws["!opts"]) ws["!opts"] = {};
          ws["!opts"].RTL = true;
          let label = (safeTrim(sheet.sheetName) || "גיליון").slice(0, 31);
          let uniq = label;
          let n = 2;
          while(usedNames.has(uniq)){ uniq = (label.slice(0, 28) + " " + n).slice(0, 31); n += 1; }
          usedNames.add(uniq);
          window.XLSX.utils.book_append_sheet(wb, ws, uniq);
          exportedAny = true;
        });
        if(!exportedAny){
          this.showAlert("אין שורות לייצוא", "warn");
          return;
        }
        const report = CancellationsStore.report;
        const now = new Date();
        const ds = [now.getFullYear(), String(now.getMonth() + 1).padStart(2, "0"), String(now.getDate()).padStart(2, "0")].join("-");
        const asOf = normalizeDailyReportAsOfInput(report?.reportAsOfDate);
        let fileName = "דוח_ביטולים_GEMEL_INVEST";
        fileName += "_" + (asOf || ds);
        if(!isFull){
          const agentName = safeTrim(Auth?.current?.name) || safeTrim(Auth?.current?.username) || "נציג";
          fileName += "_" + agentName.replace(/[^\w\u0590-\u05FF]+/g, "_");
        }
        fileName += ".xlsx";
        window.XLSX.writeFile(wb, fileName);
        if(typeof toast === "function") toast("דוח ביטולים הופק", fileName);
      } catch(err) {
        console.error("cancellations exportToExcel error:", err);
        this.showAlert("שגיאה בייצוא: " + (err?.message || err), "err");
      }
    },

    renderSheetTabs(){
      if(!this.els.sheetTabs) return;
      const sheets = this.getSheets();
      if(!sheets.length){
        this.els.sheetTabs.hidden = true;
        this.els.sheetTabs.innerHTML = "";
        return;
      }
      const active = this.getActiveSheet();
      const activeName = safeTrim(active?.sheetName);
      this.els.sheetTabs.hidden = false;
      this.els.sheetTabs.innerHTML = sheets.map((sheet) => {
        const name = safeTrim(sheet.sheetName);
        const count = CancellationsStore.getVisibleRowsForSheet(sheet).length;
        const isActive = name === activeName;
        return `<button type="button" role="tab" class="lcCancellations__sheetTab${isActive ? " is-active" : ""}" aria-selected="${isActive}" data-sheet="${escapeHtml(name)}">${escapeHtml(name || "גיליון")}<span class="lcCancellations__sheetTabCount">(${count})</span></button>`;
      }).join("");
      this.els.sheetTabs.querySelectorAll("[data-sheet]").forEach((btn) => {
        on(btn, "click", () => this.switchSheet(btn.getAttribute("data-sheet") || ""));
      });
    },

    switchSheet(name){
      if(safeTrim(this.activeSheetName) === safeTrim(name)) return;
      this.activeSheetName = safeTrim(name);
      this._filterOptionsStamp = "";
      this.searchQuery = "";
      this.filterAgent = "";
      this.filterTeam = "";
      this.filterStatus = "";
      if(this.els.search) this.els.search.value = "";
      this.paint();
    },

    getFilteredRows(sheet){
      if(!sheet) return [];
      const cols = getDailyReportColumnIndexes(sheet);
      const q = safeTrim(this.searchQuery).toLowerCase();
      const fAgent = safeTrim(this.filterAgent);
      const fTeam = safeTrim(this.filterTeam);
      const fStatus = safeTrim(this.filterStatus);
      let rows = CancellationsStore.getVisibleRowsForSheet(sheet);
      if(fAgent){
        rows = rows.filter((row) => normalizeDailyReportAgentKey(row.agent) === fAgent);
      }
      if(fTeam && cols.team >= 0){
        rows = rows.filter((row) => getDailyReportCell(row, cols.team) === fTeam);
      }
      if(fStatus && cols.status >= 0){
        rows = rows.filter((row) => getDailyReportCell(row, cols.status) === fStatus);
      }
      if(!q) return rows;
      return rows.filter((row) => {
        const blob = (row.cells || []).join(" ").toLowerCase();
        return blob.includes(q) || safeTrim(row.agent).toLowerCase().includes(q);
      });
    },

    collectUniqueColumnValues(rows, colIdx){
      const set = new Set();
      if(colIdx < 0) return [];
      (rows || []).forEach((row) => {
        const val = getDailyReportCell(row, colIdx);
        if(val) set.add(val);
      });
      return Array.from(set).sort((a, b) => a.localeCompare(b, "he"));
    },

    paintFilterOptions(sheet){
      const stamp = sheet
        ? safeTrim(sheet.sheetName) + "|" + safeTrim(CancellationsStore.report?.uploadedAt) + "|" + (sheet.dataRows?.length || 0)
        : "";
      const syncValues = () => {
        if(this.els.filterAgent && !this.els.filterAgent.hidden) this.els.filterAgent.value = this.filterAgent;
        if(this.els.filterTeam) this.els.filterTeam.value = this.filterTeam;
        if(this.els.filterStatus) this.els.filterStatus.value = this.filterStatus;
      };
      if(stamp && this._filterOptionsStamp === stamp){
        syncValues();
        return;
      }
      this._filterOptionsStamp = stamp;
      const baseRows = CancellationsStore.getVisibleRowsForSheet(sheet);
      const cols = getDailyReportColumnIndexes(sheet);
      const fillSelect = (el, placeholder, values, current) => {
        if(!el) return;
        const opts = [`<option value="">${escapeHtml(placeholder)}</option>`]
          .concat(values.map((v) => `<option value="${escapeHtml(v)}">${escapeHtml(v)}</option>`));
        el.innerHTML = opts.join("");
        el.value = values.includes(current) ? current : "";
      };
      const canPickAgent = Auth.isAdmin() || Auth.isManager() || Auth.isTeamManager();
      if(this.els.filterAgent){
        this.els.filterAgent.hidden = !canPickAgent;
        if(canPickAgent){
          let agents = CancellationsStore.getAgentSummaryForSheet(sheet).map(([name]) => name).filter((n) => n && n !== "— ללא נציג");
          if(Auth.isTeamManager()){
            const allowed = new Set(
              getManagedAgentRecordsForTeamManager(safeTrim(Auth?.current?.id))
                .flatMap((a) => {
                  const keys = [];
                  const n = normalizeDailyReportAgentKey(a?.name);
                  const u = normalizeDailyReportAgentKey(a?.username);
                  if(n) keys.push(n);
                  if(u) keys.push(u);
                  return keys;
                })
            );
            agents = agents.filter((name) => allowed.has(normalizeDailyReportAgentKey(name)));
          }
          fillSelect(this.els.filterAgent, "נציג — הכל", agents, this.filterAgent);
        }
      }
      fillSelect(this.els.filterTeam, "צוות — הכל", this.collectUniqueColumnValues(baseRows, cols.team), this.filterTeam);
      fillSelect(this.els.filterStatus, "סטטוס — הכל", this.collectUniqueColumnValues(baseRows, cols.status), this.filterStatus);
      syncValues();
    },

    paintHeader(sheet){
      if(!this.els.thead) return;
      const headers = Array.isArray(sheet?.headerRow) ? sheet.headerRow : [];
      if(!headers.length){
        this.els.thead.innerHTML = "<tr><th class=\"muted\">—</th></tr>";
        return;
      }
      this.els.thead.innerHTML = "<tr>" + headers.map((h) => `<th>${escapeHtml(h || "—")}</th>`).join("") + "</tr>";
    },

    paintBody(sheet, rows){
      if(!this.els.tbody) return;
      const headers = Array.isArray(sheet?.headerRow) ? sheet.headerRow : [];
      const colCount = Math.max(headers.length, 1);
      if(!CancellationsStore.report){
        this.els.tbody.innerHTML = `<tr><td colspan="${colCount}" class="muted">טרם הועלה דוח ביטולים</td></tr>`;
        return;
      }
      if(!rows.length){
        const msg = Auth.isAdmin() || Auth.isManager()
          ? "אין שורות להצגה (נסה לשנות חיפוש)"
          : Auth.isTeamManager()
            ? "אין שורות בגיליון עבור הצוות שלך — נסה לשנות סינון או ודא ששמות הנציגים בעמודת \"נציג\" תואמים למערכת"
            : 'אין שורות בגיליון עבורך — ודא ששמך בעמודת "נציג" תואם לשם במערכת (גם אם סדר השם שונה)';
        this.els.tbody.innerHTML = `<tr><td colspan="${colCount}" class="muted">${escapeHtml(msg)}</td></tr>`;
        return;
      }
      this.els.tbody.innerHTML = rows.map((row) => {
        const cells = Array.isArray(row.cells) ? row.cells : [];
        const tds = [];
        for(let i = 0; i < colCount; i += 1){
          const val = safeTrim(cells[i]);
          const hdr = safeTrim(headers[i]).toLowerCase();
          const isNum = hdr.includes("טלפון") || hdr.includes("פוליסה") || hdr.includes("ת.ז") || hdr.includes("תז");
          tds.push(`<td${isNum ? ' dir="ltr"' : ""}>${escapeHtml(val)}</td>`);
        }
        return `<tr>${tds.join("")}</tr>`;
      }).join("");
    },

    paintMeta(sheet, filteredCount, totalVisible){
      if(!this.els.meta) return;
      const report = CancellationsStore.report;
      if(!report){
        this.els.meta.textContent = Auth.canUploadDailyReport()
          ? 'העלה קובץ Excel (עד 3 גיליונות) — העמודה "נציג" קובעת אילו שורות יראה כל נציג'
          : "";
        return;
      }
      const uploadLabel = formatDailyReportUploadDate(report.uploadedAt);
      const parts = [`תאריך העלאה: ${uploadLabel}`];
      if(safeTrim(report.uploadedByName)) parts.push("הועלה על ידי: " + report.uploadedByName);
      if(safeTrim(sheet?.sheetName)) parts.push("גיליון: " + safeTrim(sheet.sheetName));
      const total = Number(totalVisible) || 0;
      const shown = Number(filteredCount) || 0;
      parts.push(this.hasActiveFilters() ? `מוצגות ${shown} מתוך ${total} שורות` : `מוצגות ${shown} שורות`);
      if((Auth.isAdmin() || Auth.isManager()) && sheet){
        const summary = CancellationsStore.getAgentSummaryForSheet(sheet);
        if(summary.length){
          parts.push("פילוח: " + summary.map(([name, cnt]) => `${name} (${cnt})`).join(" · "));
        }
      }
      this.els.meta.textContent = parts.join(" · ");
    },

    paintTitle(){
      const report = CancellationsStore.report;
      if(this.els.title) this.els.title.textContent = "ביטולים";
      const asOfLabel = report ? formatDailyReportAsOfDate(report.reportAsOfDate) : "";
      if(this.els.asOfLine){
        if(asOfLabel){
          this.els.asOfLine.hidden = false;
          this.els.asOfLine.textContent = "נכון לתאריך " + asOfLabel;
        } else {
          this.els.asOfLine.hidden = true;
          this.els.asOfLine.textContent = "";
        }
      }
      // GI-CANCEL-STATS: המלל ההסברי הוסר; במקומו מוני פרמיה (paintCancelStats).
      const canUpload = Auth.canUploadDailyReport();
      if(this.els.asOfPickWrap) this.els.asOfPickWrap.hidden = !canUpload;
      if(this.els.asOfDate && canUpload && report?.reportAsOfDate){
        this.els.asOfDate.value = normalizeDailyReportAsOfInput(report.reportAsOfDate);
      }
    },

    // GI-CANCEL-STATS
    computeCancelStats(sheet, rows){
      const out = {
        hasStatusCol: false,
        hasYearCol: false,
        byStatus: {},
        totalCancelPremium: 0,
        totalCancelCount: 0,
        retainedByYear: []
      };
      Object.keys(CANCEL_STATUS_KEYS).forEach((k) => { out.byStatus[k] = { premium: 0, count: 0 }; });
      if(!sheet) return out;
      const cols = getDailyReportColumnIndexes(sheet);
      if(cols.status < 0 || cols.premium < 0) return out;
      out.hasStatusCol = true;
      const yearCol = findCancellationYearCol(Array.isArray(sheet.headerRow) ? sheet.headerRow : []);
      out.hasYearCol = yearCol >= 0;
      const yearMap = new Map();
      (rows || []).forEach((row) => {
        const key = classifyCancellationStatus(getDailyReportCell(row, cols.status));
        if(!key || !out.byStatus[key]) return;
        const premium = parseDailyReportMoney(getDailyReportCell(row, cols.premium));
        out.byStatus[key].premium += premium;
        out.byStatus[key].count += 1;
        if(CANCEL_TOTAL_KEYS.includes(key)){
          out.totalCancelPremium += premium;
          out.totalCancelCount += 1;
        }
        if(key === "retained" && yearCol >= 0){
          const yr = normalizeCancellationYear(getDailyReportCell(row, yearCol)) || "ללא שנה";
          const prev = yearMap.get(yr) || { label: yr, premium: 0, count: 0 };
          prev.premium += premium;
          prev.count += 1;
          yearMap.set(yr, prev);
        }
      });
      Object.keys(out.byStatus).forEach((k) => {
        out.byStatus[k].premium = Math.round(out.byStatus[k].premium * 100) / 100;
      });
      out.totalCancelPremium = Math.round(out.totalCancelPremium * 100) / 100;
      out.retainedByYear = Array.from(yearMap.values())
        .map((it) => ({ ...it, premium: Math.round(it.premium * 100) / 100 }))
        .sort((a, b) => {
          const ia = CANCEL_YEAR_ORDER.indexOf(a.label);
          const ib = CANCEL_YEAR_ORDER.indexOf(b.label);
          return (ia < 0 ? 99 : ia) - (ib < 0 ? 99 : ib);
        });
      return out;
    },

    formatCancelMoney(v){
      const n = Number(v);
      if(!Number.isFinite(n) || n <= 0) return "₪0";
      const rounded = Math.round(n * 100) / 100;
      try {
        return "₪" + rounded.toLocaleString("he-IL", { minimumFractionDigits: 0, maximumFractionDigits: 2 });
      } catch(_e) {
        return "₪" + rounded;
      }
    },

    paintCancelStats(sheet, rows){
      const wrap = this.els.stats;
      if(!wrap) return;
      const stats = this.computeCancelStats(sheet, rows);
      if(!stats.hasStatusCol){
        wrap.hidden = true;
        wrap.innerHTML = "";
        return;
      }
      wrap.hidden = false;
      const policyWord = (n) => (Number(n) === 1 ? "פוליסה" : "פוליסות");
      const cell = (label, data, dotCls, cellCls) => `
        <div class="lcStatCell${cellCls ? " " + cellCls : ""}">
          <span class="lcStatCell__label">${dotCls ? `<span class="lcStatCell__dot lcStatCell__dot--${dotCls}"></span>` : ""}${escapeHtml(label)}</span>
          <span class="lcStatCell__value">${escapeHtml(this.formatCancelMoney(data.premium))}</span>
          <span class="lcStatCell__sub">${escapeHtml(String(data.count) + " " + policyWord(data.count))}</span>
        </div>`;
      const S = stats.byStatus;
      const rowTop = [
        cell(CANCEL_STATUS_KEYS.cancelled.label, S.cancelled, "danger"),
        cell(CANCEL_STATUS_KEYS.cancelledPartial.label, S.cancelledPartial, "dangerDim"),
        cell(CANCEL_STATUS_KEYS.partial.label, S.partial, "warn"),
        cell("סה״כ פרמיית ביטול", { premium: stats.totalCancelPremium, count: stats.totalCancelCount }, "", "lcStatCell--totalDanger")
      ].join("");
      const rowBottom = [
        cell(CANCEL_STATUS_KEYS.awaitingRetain.label, S.awaitingRetain, "info"),
        cell("סה״כ פרמיה ששומרה", S.retained, "success", "lcStatCell--totalSuccess")
      ];
      if(stats.hasYearCol){
        const chips = CANCEL_YEAR_ORDER.map((label) => {
          const found = stats.retainedByYear.find((it) => it.label === label);
          const isEmpty = !found;
          const val = found ? found.premium : 0;
          return `<span class="lcStatYears__chip${isEmpty ? " lcStatYears__chip--empty" : ""}">`
            + `<span class="lcStatYears__chipLabel">${escapeHtml(label)}</span>`
            + `<span class="lcStatYears__chipValue">${escapeHtml(this.formatCancelMoney(val))}</span>`
            + (found ? `<span class="lcStatYears__chipCount">${escapeHtml(String(found.count))}</span>` : "")
            + `</span>`;
        });
        // שנים שאינן ברשימה הסטנדרטית (למשל תא ריק) מוצגות בסוף כדי שלא ייעלמו.
        stats.retainedByYear
          .filter((it) => !CANCEL_YEAR_ORDER.includes(it.label))
          .forEach((it) => {
            chips.push(`<span class="lcStatYears__chip">`
              + `<span class="lcStatYears__chipLabel">${escapeHtml(it.label)}</span>`
              + `<span class="lcStatYears__chipValue">${escapeHtml(this.formatCancelMoney(it.premium))}</span>`
              + `<span class="lcStatYears__chipCount">${escapeHtml(String(it.count))}</span>`
              + `</span>`);
          });
        rowBottom.push(`
          <div class="lcStatCell lcStatCell--years">
            <span class="lcStatYears__title">ששומרה לפי שנת ביטול · ״כללי״ = שנה 6 ומעלה</span>
            <div class="lcStatYears__chips">${chips.join("")}</div>
          </div>`);
      }
      wrap.innerHTML = `<div class="lcStatStrip__row">${rowTop}</div>`
        + `<div class="lcStatStrip__row">${rowBottom.join("")}</div>`;
      wrap.classList.toggle("is-filtered", this.hasActiveFilters());
    },

    paint(){
      const report = CancellationsStore.report;
      const sheet = this.getActiveSheet();
      const canUpload = Auth.canUploadDailyReport();
      if(this.els.btnUpload){
        this.els.btnUpload.hidden = !canUpload;
        this.els.btnUpload.disabled = false;
      }
      if(this.els.btnExport) this.els.btnExport.hidden = !report;
      if(this.els.btnRefresh) this.els.btnRefresh.hidden = !canUpload;
      if(this.els.fileInput) this.els.fileInput.hidden = !canUpload;
      if(this.els.filters) this.els.filters.hidden = !sheet;
      if(!CancellationsStore.tableReady){
        this.showAlert("טבלת דוח הביטולים (gi_cancellations_report) חסרה או לא זמינה ב-Supabase", "warn");
      } else if(!report && canUpload){
        this.showAlert("", "ok");
      } else {
        this.showAlert("");
      }
      this.paintTitle();
      this.renderSheetTabs();
      if(sheet) this.paintFilterOptions(sheet);
      const totalVisible = sheet ? CancellationsStore.getVisibleRowsForSheet(sheet).length : 0;
      const rows = sheet ? this.getFilteredRows(sheet) : [];
      this.paintCancelStats(sheet, rows);
      this.paintMeta(sheet, rows.length, totalVisible);
      this.paintHeader(sheet);
      this.paintBody(sheet, rows);
    },

    showLoadingShell(){
      if(!this.els.thead) this.init();
      if(this.els.thead) this.els.thead.innerHTML = '<tr><th class="muted">טוען דוח ביטולים…</th></tr>';
      if(this.els.tbody) this.els.tbody.innerHTML = '<tr><td class="muted">טוען נתונים מהשרת…</td></tr>';
      if(this.els.meta) this.els.meta.textContent = "טוען…";
      if(this.els.filters) this.els.filters.hidden = true;
      if(this.els.sheetTabs) this.els.sheetTabs.hidden = true;
      if(this.els.alert){
        this.els.alert.hidden = true;
        this.els.alert.textContent = "";
      }
    },

    scheduleNavRender(){
      if(!Auth.current) return;
      if(!this.els.thead) this.init();
      const hadCache = !!CancellationsStore.report;
      if(hadCache){
        try { this.paint(); } catch(_e) {}
      } else {
        try { this.showLoadingShell(); } catch(_e) {}
      }
      if(this._navFetchInFlight) return;
      this._navFetchInFlight = true;
      perfIdle(() => {
        void (async () => {
          try {
            await this.refresh(false, { onlyIfVisible: true });
          } finally {
            this._navFetchInFlight = false;
          }
        })();
      }, hadCache ? 120 : 80);
    },

    async refresh(showToast, options = {}){
      const r = await CancellationsStore.fetchActive();
      if(!r.ok && CancellationsStore.lastError){
        this.showAlert("לא נטען דוח ביטולים: " + CancellationsStore.lastError, "err");
      }
      if(options.onlyIfVisible && !(LiveRefresh.getCurrentView() === "dailyReport" && DailyReportUI.activeRubric === "cancellations")) return;
      this.paint();
      if(showToast && typeof toast === "function" && r.ok) toast("דוח ביטולים עודכן");
    },

    async render(){
      if(!Auth.current) return;
      this.scheduleNavRender();
    }
  };

  const CampaignLinesSettingsUI = {
    els: {},
    draft: [],

    init(){
      this.els.root = document.getElementById("campaignLinesSettingsRoot");
      this.els.list = document.getElementById("campaignLinesList");
      this.els.btnAdd = document.getElementById("btnCampaignLineAdd");
      this.els.btnSave = document.getElementById("btnCampaignLinesSave");
      this.els.status = document.getElementById("campaignLinesSaveStatus");
      if(this.els.btnAdd) on(this.els.btnAdd, "click", () => this.addRow());
      if(this.els.btnSave) on(this.els.btnSave, "click", () => this.save());
    },

    render(){
      if(!this.els.list || !Auth.canManageCampaignLines()) return;
      this.draft = getCampaignLines().map((l) => ({ ...l }));
      this.paint();
    },

    paint(){
      if(!this.els.list) return;
      if(!this.draft.length){
        this.els.list.innerHTML = '<div class="muted small">אין קמפיינים — לחץ «הוסף קמפיין»</div>';
        return;
      }
      this.els.list.innerHTML = this.draft.map((line, idx) => `
        <div class="lcCampaignLineRow" data-cmp-idx="${idx}">
          <input class="input" data-cmp-field="label" placeholder="שם קמפיין" value="${escapeHtml(line.label)}" type="text"/>
          <input class="input" data-cmp-field="phoneLine" dir="ltr" placeholder="מספר קו" value="${escapeHtml(line.phoneLine)}" type="text"/>
          <input class="input" data-cmp-field="topic" placeholder="נושא (פנסיה, בריאות…)" value="${escapeHtml(line.topic)}" type="text"/>
          <label class="lcCampaignLineRow__active"><input type="checkbox" data-cmp-field="active" ${line.active ? "checked" : ""}/> פעיל</label>
          <button class="btn" type="button" data-cmp-remove="${idx}">הסר</button>
        </div>
      `).join("");
      this.els.list.querySelectorAll("[data-cmp-remove]").forEach((btn) => {
        on(btn, "click", () => {
          const i = Number(btn.getAttribute("data-cmp-remove"));
          if(!Number.isFinite(i)) return;
          this.draft.splice(i, 1);
          this.paint();
        });
      });
    },

    addRow(){
      this.draft.push(normalizeCampaignLine({ label: "קמפיין חדש", active: true }, this.draft.length));
      this.paint();
    },

    collectFromDom(){
      const rows = Array.from(this.els.list?.querySelectorAll(".lcCampaignLineRow") || []);
      return rows.map((rowEl, idx) => {
        const getVal = (field) => safeTrim(rowEl.querySelector(`[data-cmp-field="${field}"]`)?.value);
        const activeEl = rowEl.querySelector('[data-cmp-field="active"]');
        const existing = this.draft[idx] || {};
        return normalizeCampaignLine({
          id: existing.id,
          label: getVal("label"),
          phoneLine: getVal("phoneLine"),
          topic: getVal("topic"),
          active: activeEl ? !!activeEl.checked : true,
          sortOrder: idx
        }, idx);
      }).filter((l) => safeTrim(l.label));
    },

    async save(){
      if(!Auth.canManageCampaignLines()) return;
      const lines = this.collectFromDom();
      if(!lines.length){
        if(this.els.status) this.els.status.textContent = "יש להוסיף לפחות קמפיין אחד";
        return;
      }
      State.data.meta.campaignLines = lines;
      if(this.els.status) this.els.status.textContent = "שומר…";
      const r = await App.persist("קמפיינים וקווים נשמרו");
      if(this.els.status) this.els.status.textContent = r?.ok === false ? (r.error || "שגיאה") : "נשמר";
      this.render();
      try { CampaignLeadsUI.fillCampaignSelect?.(); } catch(_e) {}
      try { LandingLeadIngestSettingsUI.render?.(); } catch(_e) {}
    }
  };

  const LandingLeadIngestSettingsUI = {
    els: {},

    init(){
      this.els.root = document.getElementById("landingLeadIngestSettingsRoot");
      this.els.campaignId = document.getElementById("lliCampaignId");
      this.els.campaignLabel = document.getElementById("lliCampaignLabel");
      this.els.autoEnabled = document.getElementById("lliAutoAssignEnabled");
      this.els.autoAgent = document.getElementById("lliAutoAssignAgent");
      this.els.btnSave = document.getElementById("btnLandingLeadIngestSave");
      this.els.status = document.getElementById("landingLeadIngestSaveStatus");
      if(this.els.btnSave) on(this.els.btnSave, "click", () => void this.save());
    },

    render(){
      if(!this.els.root || !Auth.canManageCampaignLines()) return;
      const cfg = getLandingLeadIngestConfig();
      if(this.els.campaignId) this.els.campaignId.value = cfg.campaignId;
      if(this.els.campaignLabel) this.els.campaignLabel.value = cfg.campaignLabel;
      if(this.els.autoEnabled) this.els.autoEnabled.checked = !!cfg.autoAssignEnabled;
      const agents = getAssignableSalesAgents();
      if(this.els.autoAgent){
        this.els.autoAgent.innerHTML = '<option value="">— בחר נציג —</option>' + agents.map((a) =>
          `<option value="${escapeHtml(a.id)}">${escapeHtml(a.name)}</option>`
        ).join("");
        if(cfg.autoAssignAgentId) this.els.autoAgent.value = cfg.autoAssignAgentId;
      }
    },

    async save(){
      if(!Auth.canManageCampaignLines()) return;
      const cfg = getLandingLeadIngestConfig();
      const next = normalizeLandingLeadIngestConfig({
        campaignId: cfg.campaignId,
        campaignLabel: safeTrim(this.els.campaignLabel?.value) || cfg.campaignLabel,
        autoAssignEnabled: false,
        autoAssignAgentId: "",
        autoAssignAgentName: ""
      });
      State.data.meta.landingLeadIngest = next;
      const lines = getCampaignLines().map((l) => {
        if(String(l.id) !== String(next.campaignId)) return l;
        return { ...l, label: next.campaignLabel, topic: l.topic || "בריאות, ריסק, משכנתא", active: true };
      });
      if(!lines.some((l) => String(l.id) === String(next.campaignId))){
        lines.unshift(normalizeCampaignLine({
          id: next.campaignId,
          label: next.campaignLabel,
          topic: "בריאות, ריסק, משכנתא",
          active: true
        }, 0));
      }
      State.data.meta.campaignLines = normalizeCampaignLineList(lines);
      if(this.els.status) this.els.status.textContent = "שומר…";
      const r = await App.persist("הגדרות דף נחיתה נשמרו");
      if(this.els.status) this.els.status.textContent = r?.ok === false ? (r.error || "שגיאה") : "נשמר";
      this.render();
      try { CampaignLeadsUI.fillCampaignSelect?.(); } catch(_e) {}
    }
  };

  const CAMPAIGN_LEAD_NOTE_BTN_ICON = '<svg class="lcTrackNoteBtn__icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="M14 3H7a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h10a2 2 0 0 0 2-2V8Z"/><path d="M14 3v5h5"/><path d="M9 13h6"/><path d="M9 17h4"/></svg>';

  function campaignLeadReassignBtnHtml(leadId){
    if(!Auth.canAccessCampaignLeadsInbox()) return "";
    return `<button class="btn btn--small btn--outline lcLeadReassignBtn" type="button" data-cl-reassign-id="${escapeHtml(String(leadId))}" title="שיוך לנציג נוסף">שיוך לנציג נוסף</button>`;
  }

  function campaignLeadAgentNoteBtnHtml(lead){
    const id = escapeHtml(lead.id);
    let html = "";
    if(lead.status === "irrelevant" && safeTrim(lead.irrelevantNote)){
      html += `<button class="lcTrackNoteBtn" type="button" data-cl-note-id="${id}" data-cl-note-kind="irrelevant" title="צפייה בתיעוד הנציג (לא רלוונטי)">${CAMPAIGN_LEAD_NOTE_BTN_ICON}</button>`;
    }
    if(lead.status === "closed" && safeTrim(lead.closedNote)){
      html += `<button class="lcTrackNoteBtn" type="button" data-cl-note-id="${id}" data-cl-note-kind="closed" title="פתח — צפייה בתיעוד המכירה">${CAMPAIGN_LEAD_NOTE_BTN_ICON}</button>`;
    }
    if(safeTrim(lead.callNote)){
      html += `<button class="lcTrackNoteBtn lcTrackNoteBtn--call" type="button" data-cl-note-id="${id}" data-cl-note-kind="call" title="צפייה בתיעוד שיחה">${CAMPAIGN_LEAD_NOTE_BTN_ICON}</button>`;
    }
    return html;
  }

  function handleCampaignLeadReassignBtn(reassignBtn){
    if(!reassignBtn) return;
    const id = reassignBtn.getAttribute("data-cl-reassign-id");
    const lead = CampaignLeadsStore.leads.find((l) => String(l.id) === String(id));
    if(lead) CampaignLeadReassignAgent.open(lead);
  }

  function handleCampaignLeadAgentNoteBtn(noteBtn){
    if(!noteBtn) return;
    const id = noteBtn.getAttribute("data-cl-note-id");
    const kind = safeTrim(noteBtn.getAttribute("data-cl-note-kind")) || "irrelevant";
    const lead = CampaignLeadsStore.leads.find((l) => String(l.id) === String(id));
    if(!lead) return;
    if(kind === "call"){
      if(safeTrim(lead.callNote)) CampaignNoteViewer.open(lead, { kind: "call" });
      return;
    }
    const note = kind === "closed" ? safeTrim(lead.closedNote) : safeTrim(lead.irrelevantNote);
    if(note) CampaignNoteViewer.open(lead, { kind });
  }

  // GI-GOLD-LEAD — manager tracking board
  const GoldLeadBoard = {
    from: "",   // YYYY-MM-DD ; empty = today
    to: "",

    _todayIL(){
      try { return currentCampaignLeadDateIL(); }
      catch(_e){ return new Date().toISOString().slice(0,10); }
    },

    _activeFrom(){ return this.from || this._todayIL(); },
    _activeTo(){ return this.to || this._activeFrom(); },

    _dayOf(lead){
      const raw = safeTrim(lead?.createdAt);
      if(!raw) return "";
      try {
        const d = new Date(raw);
        if(isNaN(d.getTime())) return "";
        const p = new Intl.DateTimeFormat("en-CA", { timeZone:"Asia/Jerusalem", year:"numeric", month:"2-digit", day:"2-digit" }).format(d);
        return p;
      } catch(_e){ return raw.slice(0,10); }
    },

    // A gold lead shows on its own day. If it is still unhandled it keeps
    // carrying forward to every later day until someone moves it along.
    _leadsInRange(){
      const from = this._activeFrom();
      const to = this._activeTo();
      const today = this._todayIL();
      const all = (Array.isArray(CampaignLeadsStore?.leads) ? CampaignLeadsStore.leads : []).filter((l) => l && l.goldLead === true);
      return all.filter((l) => {
        const d = this._dayOf(l);
        if(!d) return false;
        if(d >= from && d <= to) return true;
        if(d < from && !goldLeadIsHandled(l) && to >= today) return true;   // carried over
        return false;
      }).sort((a, b) => safeTrim(b.createdAt).localeCompare(safeTrim(a.createdAt)));
    },

    setRange(from, to){
      this.from = safeTrim(from);
      this.to = safeTrim(to);
      this.render();
    },

    resetToday(){
      this.from = ""; this.to = "";
      const f = document.getElementById("goldBoardFrom");
      const t = document.getElementById("goldBoardTo");
      if(f) f.value = this._todayIL();
      if(t) t.value = this._todayIL();
      this.render();
    },

    _statHtml(list){
      const total = list.length;
      const opened = list.filter((l) => safeTrim(l.openedAt)).length;
      const handled = list.filter((l) => goldLeadIsHandled(l)).length;
      const stuck = list.filter((l) => goldLeadIsUntouched(l)).length;
      const cell = (label, val, danger) =>
        `<div class="goldBoard__stat${danger ? " goldBoard__stat--danger" : ""}">`
        + `<div class="goldBoard__statLabel">${escapeHtml(label)}</div>`
        + `<div class="goldBoard__statVal">${val}</div></div>`;
      return cell("סה\u05f4כ", total, false) + cell("נפתחו", opened, false)
        + cell("בטיפול", handled, false) + cell("לא נגעו", stuck, stuck > 0);
    },

    _timelineHtml(lead){
      const steps = goldLeadTimelineSteps(lead);
      const parts = [];
      steps.forEach((st, i) => {
        if(i > 0) parts.push(`<div class="goldBoard__tlBar${st.done ? " is-done" : ""}"></div>`);
        parts.push(
          `<div class="goldBoard__tlStep">`
          + `<div class="goldBoard__tlDot${st.done ? " is-done" : ""}"></div>`
          + `<div class="goldBoard__tlLabel${st.done ? " is-done" : ""}">${escapeHtml(st.label)}</div>`
          + `<div class="goldBoard__tlTime">${escapeHtml(st.time || "—")}</div></div>`
        );
      });
      return `<div class="goldBoard__timeline">${parts.join("")}</div>`;
    },

    _noteHtml(lead){
      const note = safeTrim(lead.callNote) || safeTrim(lead.closedNote) || safeTrim(lead.irrelevantNote);
      if(!note) return "";
      const who = safeTrim(lead.updatedByName) || safeTrim(lead.openedByName) || "נציג";
      const when = goldLeadClock(safeTrim(lead.lastModifiedAt) || safeTrim(lead.updatedAt));
      return `<div class="goldBoard__note"><div class="goldBoard__noteHead">תיעוד הנציג · ${escapeHtml(who)}${when ? " · " + escapeHtml(when) : ""}</div>`
        + `<div class="goldBoard__noteBody">${escapeHtml(note)}</div></div>`;
    },

    _cardHtml(lead){
      const stuck = goldLeadIsUntouched(lead);
      const carried = this._dayOf(lead) < this._activeFrom();
      const products = Array.isArray(lead.goldProducts) ? lead.goldProducts : [];
      const chips = products.map((t) => `<span class="goldBoard__chip">${escapeHtml(t)}</span>`).join("")
        + (Number(lead.goldPolicyCount) > 0 ? `<span class="goldBoard__chip">${Number(lead.goldPolicyCount)} פוליסות</span>` : "");
      const st = safeTrim(lead.status);
      const statusPill = `<span class="goldBoard__pill goldBoard__pill--${escapeHtml(st)}">${escapeHtml(campaignLeadStatusLabel(st))}</span>`;
      const stuckPill = stuck
        ? `<span class="goldBoard__pill goldBoard__pill--stuck">לא נגעו · ${escapeHtml(goldLeadFormatSpan(goldLeadUntouchedMs(lead)))}</span>` : "";
      const carriedPill = carried ? `<span class="goldBoard__pill goldBoard__pill--carried">הועבר מיום קודם</span>` : "";
      const src = safeTrim(lead.goldSourceAgentName);
      const trackPill = lead.goldTrack === "pension"
        ? `<span class="goldBoard__pill goldBoard__pill--pension">פנסיה</span>`
        : (lead.goldTrack === "elementary" ? `<span class="goldBoard__pill goldBoard__pill--elementary">אלמנטרי</span>` : "");
      let trackInfo = "";
      if(lead.goldTrack === "pension"){
        const clr = lead.goldClearing === "available" ? "מסלקה זמינה בשורנס"
          : (lead.goldClearing === "pending" ? "מסלקה ממתינה בשורנס" : "");
        const sal = safeTrim(lead.goldSalary) ? ("שכר " + safeTrim(lead.goldSalary)) : "";
        const av = lead.goldAvailAllDay === true
          ? "זמין כל היום"
          : ([safeTrim(lead.goldAvailDate), safeTrim(lead.goldAvailTime)].filter(Boolean).join(" ") || "");
        const bits = [clr, sal, av ? ("זמינות: " + av) : ""].filter(Boolean);
        if(bits.length) trackInfo = `<div class="goldBoard__track">${bits.map((b) => `<span class="goldBoard__chip">${escapeHtml(b)}</span>`).join("")}</div>`;
      }
      return `<div class="goldBoard__card${stuck ? " is-stuck" : ""}" data-gold-card="${escapeHtml(String(lead.id))}">
  <div class="goldBoard__top">
    <div class="goldBoard__ident">
      <div class="goldBoard__nameRow">
        <span class="goldBoard__name">${escapeHtml(safeTrim(lead.customerName) || "—")}</span>
        <span class="lcGoldBadge">ליד זהב</span>${trackPill}${statusPill}${stuckPill}${carriedPill}
      </div>
      <div class="goldBoard__facts">${escapeHtml(lead.phone || "—")} · ת&quot;ז ${escapeHtml(lead.idNumber || "—")} · ת. לידה ${escapeHtml(lead.birthDate || "—")} · הנפקה ${escapeHtml(lead.idIssueDate || "—")}</div>
    </div>
    <div class="goldBoard__assign">
      <div class="goldBoard__assignLabel">שויך אל</div>
      <div class="goldBoard__assignName">${escapeHtml(safeTrim(lead.assignedAgentName) || "לא שויך")}</div>
      ${src ? `<div class="goldBoard__assignSrc">מקור: ${escapeHtml(src)}</div>` : ""}
    </div>
  </div>
  ${chips ? `<div class="goldBoard__chips">${chips}</div>` : ""}

  ${trackInfo}
  ${this._timelineHtml(lead)}
  ${this._noteHtml(lead)}
</div>`;
    },

    render(){
      const wrap = document.getElementById("goldBoardBody");
      const stats = document.getElementById("goldBoardStats");
      if(!wrap) return;
      if(!goldLeadCanUse()){ wrap.innerHTML = ""; if(stats) stats.innerHTML = ""; return; }
      const list = this._leadsInRange();
      if(stats) stats.innerHTML = this._statHtml(list);
      wrap.innerHTML = list.length
        ? list.map((l) => this._cardHtml(l)).join("")
        : `<div class="goldBoard__empty">אין לידי זהב בטווח שנבחר</div>`;
    }
  };

  // GI-GOLD-LEAD — manager-only modal: search customer -> pick agents -> create lead
  const GoldLeadModal = {
    _results: [],
    _selected: null,
    _pendingDuplicate: null,

    _el(id){ return document.getElementById(id); },

    open(){
      if(!goldLeadCanUse()){
        showCampaignLeadToast("אין הרשאה", "הקמת ליד זהב זמינה למנהל מערכת או למנהל בלבד.");
        return;
      }
      this._results = []; this._selected = null; this._pendingDuplicate = null; this._track = "";
      const q = this._el("goldLeadSearchInput");
      if(q) q.value = "";
      this._renderResults();
      this._renderDetail();
      this._syncSteps();
      const m = this._el("goldLeadModal");
      if(m){ m.classList.add("is-open"); m.setAttribute("aria-hidden","false"); }
      try { document.body.classList.add("modal-open"); } catch(_e){}
      setTimeout(() => { try { q?.focus(); } catch(_e){} }, 60);
    },

    close(){
      const m = this._el("goldLeadModal");
      if(m){ m.classList.remove("is-open"); m.setAttribute("aria-hidden","true"); }
      try { document.body.classList.remove("modal-open"); } catch(_e){}
      this._results = []; this._selected = null; this._pendingDuplicate = null; this._track = "";
    },

    search(){
      const q = this._el("goldLeadSearchInput");
      this._results = goldLeadSearchCustomers(q ? q.value : "");
      this._selected = null;
      this._renderResults();
      this._renderDetail();
      if(this._results.length === 1) this.select(safeTrim(this._results[0].id));
    },

    _renderResults(){
      const box = this._el("goldLeadResults");
      if(!box) return;
      const q = safeTrim(this._el("goldLeadSearchInput")?.value);
      if(!q){ box.innerHTML = `<div class="goldFs__empty"><div class="goldFs__emptyIcon">⌕</div>התחל בהקלדת ת&quot;ז, טלפון או שם</div>`; return; }
      if(!this._results.length){ box.innerHTML = `<div class="goldFs__empty">לא נמצא לקוח תואם</div>`; return; }
      box.innerHTML = `<div class="goldFs__resultsCount">${this._results.length} תוצאות</div>` + this._results.map((c) => {
        const id = escapeHtml(safeTrim(c.id));
        const nm = escapeHtml(goldLeadCustomerName(c) || "ללא שם");
        const ph = escapeHtml(goldLeadCustomerPhone(c) || "—");
        const idn = escapeHtml(goldLeadCustomerId(c) || "—");
        const initial = escapeHtml((goldLeadCustomerName(c) || "?").charAt(0));
        const on = this._selected && String(this._selected.id) === String(c.id) ? " is-active" : "";
        return `<button type="button" class="goldFs__result${on}" data-gold-pick="${id}">`
          + `<span class="goldFs__avatar">${initial}</span>`
          + `<span class="goldFs__resultTxt"><span class="goldFs__resultName">${nm}</span>`
          + `<span class="goldFs__resultMeta">${ph} · ת&quot;ז ${idn}</span></span></button>`;
      }).join("");
    },

    select(customerId){
      const cid = safeTrim(customerId);
      this._selected = this._results.find((c) => String(c.id) === String(cid)) || null;
      this._pendingDuplicate = this._selected ? goldLeadFindOpenLead(this._selected) : null;
      this._renderResults();
      this._renderDetail();
      this._syncSteps();
    },

    _renderDetail(){
      const box = this._el("goldLeadDetail");
      const foot = this._el("goldLeadCreate");
      if(!box) return;
      const c = this._selected;
      if(!c){
        box.innerHTML = `<div class="goldFs__placeholder"><div class="goldFs__placeholderIcon">◷</div>`
          + `<div class="goldFs__placeholderTitle">לא נבחר לקוח</div>`
          + `<div class="goldFs__placeholderText">חפש לקוח בצד ימין ובחר אותו כדי לראות את פרטיו ולהקים ליד.</div></div>`;
        if(foot) foot.disabled = true;
        return;
      }
      const { products, policyCount } = goldLeadCustomerProducts(c);
      const chips = products.length
        ? products.map((t) => `<span class="goldLead__chip">${escapeHtml(t)}</span>`).join("")
          + `<span class="goldLead__chip">${policyCount} פוליסות</span>`
        : `<span class="goldLead__chip goldLead__chip--muted">אין מוצרים רשומים</span>`;
      const agents = goldLeadActiveAgents();
      const opts = agents.length
        ? agents.map((a) => `<option value="${escapeHtml(safeTrim(a.id))}">${escapeHtml(safeTrim(a.name) || "נציג")}</option>`).join("")
        : `<option value="">— אין נציגים פעילים —</option>`;
      const dup = this._pendingDuplicate;
      const dupHtml = dup
        ? `<div class="goldFs__warn"><span class="goldFs__warnIcon">!</span><span>ללקוח זה קיימת פנייה פתוחה המשויכת ל<strong>${escapeHtml(safeTrim(dup.assignedAgentName) || "נציג לא ידוע")}</strong>. ניתן להמשיך — תתבקש לאשר.</span></div>`
        : "";
      box.innerHTML = `
        <div class="goldFs__hero">
          <div class="goldFs__heroAvatar">${escapeHtml((goldLeadCustomerName(c) || "?").charAt(0))}</div>
          <div>
            <div class="goldFs__heroName">${escapeHtml(goldLeadCustomerName(c) || "ללא שם")}</div>
            <div class="goldFs__heroSub">לקוח קיים${policyCount > 0 ? " · " + policyCount + " פוליסות פעילות" : ""}</div>
          </div>
        </div>
        <div class="goldFs__grid">
          <div class="goldFs__field"><span class="goldFs__fieldLabel">טלפון</span><span class="goldFs__fieldVal">${escapeHtml(goldLeadCustomerPhone(c) || "—")}</span></div>
          <div class="goldFs__field"><span class="goldFs__fieldLabel">תעודת זהות</span><span class="goldFs__fieldVal">${escapeHtml(goldLeadCustomerId(c) || "—")}</span></div>
          <div class="goldFs__field"><span class="goldFs__fieldLabel">תאריך לידה</span><span class="goldFs__fieldVal">${escapeHtml(goldLeadCustomerBirth(c) || "—")}</span></div>
          <div class="goldFs__field"><span class="goldFs__fieldLabel">תאריך הנפקה</span><span class="goldFs__fieldVal">${escapeHtml(goldLeadCustomerIssue(c) || "—")}</span></div>
        </div>
        <div class="goldFs__sectionTitle">מוצרים בסוכנות</div>
        <div class="goldLead__chips">${chips}</div>
        ${dupHtml}
        <div class="goldFs__sectionTitle">שיוך</div>
        <div class="goldFs__two">
          <label class="goldFs__label">מקור השיוך
            <select id="goldLeadSourceAgent" class="goldFs__input" dir="rtl"><option value="">— ללא —</option>${opts}</select>
          </label>
          <label class="goldFs__label">שיוך לנציג <span class="goldFs__req">*</span>
            <select id="goldLeadTargetAgent" class="goldFs__input" dir="rtl">${opts}</select>
          </label>
        </div>
        <div class="goldFs__sectionTitle">מסלול הליד <span class="goldFs__req">*</span></div>
        <div class="goldFs__two">
          <button type="button" class="goldFs__trackCard" data-gold-track="pension">
            <span class="goldFs__trackHead"><span class="goldFs__trackName">פנסיה</span><span class="goldFs__trackMark">✓</span></span>
            <span class="goldFs__trackDesc">דורש מסלקה, שכר וזמינות</span>
          </button>
          <button type="button" class="goldFs__trackCard" data-gold-track="elementary">
            <span class="goldFs__trackHead"><span class="goldFs__trackName">אלמנטרי</span><span class="goldFs__trackMark">✓</span></span>
            <span class="goldFs__trackDesc">תווית בלבד, נשאר אצל הנציג</span>
          </button>
        </div>
        <div class="goldFs__trackForm" id="goldLeadTrackForm"></div>`;
      if(foot) foot.disabled = !goldLeadActiveAgents().length;
    },

    _syncSteps(){
      const step = !this._selected ? 1 : (this._track ? 3 : 2);
      document.querySelectorAll("[data-gold-step]").forEach((el) => {
        const n = Number(el.getAttribute("data-gold-step"));
        el.classList.toggle("is-active", n === step);
        el.classList.toggle("is-done", n < step);
      });
      const note = this._el("goldLeadFootNote");
      const btn = this._el("goldLeadCreate");
      let msg = "", ready = false;
      if(!this._selected) msg = "בחר לקוח מהרשימה כדי להמשיך";
      else if(!this._track) msg = "בחר מסלול — פנסיה או אלמנטרי";
      else {
        const chk = this._collectTrack();
        if(chk.ok){ msg = "כל השדות מולאו — ניתן להקים"; ready = true; }
        else msg = chk.msg;
      }
      if(note){ note.textContent = msg; note.classList.toggle("is-ready", ready); }
      if(btn) btn.disabled = !ready || !goldLeadActiveAgents().length;
    },

    setTrack(track){
      this._track = (track === "pension" || track === "elementary") ? track : "";
      document.querySelectorAll("[data-gold-track]").forEach((b) => {
        b.classList.toggle("is-active", b.getAttribute("data-gold-track") === this._track);
      });
      this._renderTrackForm();
      this._syncSteps();
    },

    _renderTrackForm(){
      const box = document.getElementById("goldLeadTrackForm");
      if(!box) return;
      if(this._track === "elementary"){ box.innerHTML = ""; return; }
      if(this._track !== "pension"){ box.innerHTML = ""; return; }
      box.innerHTML = `
        <div class="goldFs__panel">
          <div class="goldFs__panelTitle">מסלקה במערכת שורנס <span class="goldFs__req">*</span></div>
          <div class="goldFs__two goldFs__two--tight">
            <label class="goldFs__checkCard" for="goldClearAvail">
              <input type="checkbox" id="goldClearAvail"/><span class="goldFs__box"></span><span>הוזמנה וזמינה</span>
            </label>
            <label class="goldFs__checkCard" for="goldClearPend">
              <input type="checkbox" id="goldClearPend"/><span class="goldFs__box"></span><span>הוזמנה וממתינה</span>
            </label>
          </div>
          <div class="goldFs__two">
            <label class="goldFs__label">שכר המבוטח <span class="goldFs__req">*</span>
              <input type="text" class="goldFs__input" id="goldSalary" dir="rtl" inputmode="numeric" placeholder="למשל 14,500"/>
            </label>
            <div class="goldFs__label">זמינות הלקוח <span class="goldFs__req">*</span>
              <div class="goldFs__availRow" id="goldAvailRow">
                <input type="date" class="goldFs__input" id="goldAvailDate" dir="ltr"/>
                <input type="time" class="goldFs__input goldFs__input--time" id="goldAvailTime" dir="ltr"/>
              </div>
              <label class="goldFs__checkCard goldFs__checkCard--plain" for="goldAvailAllDay">
                <input type="checkbox" id="goldAvailAllDay"/><span class="goldFs__box"></span><span>זמין בכל שעות היום</span>
              </label>
            </div>
          </div>
        </div>`;
      const a = document.getElementById("goldClearAvail");
      const b = document.getElementById("goldClearPend");
      if(a) a.addEventListener("change", () => { if(a.checked && b) b.checked = false; });
      if(b) b.addEventListener("change", () => { if(b.checked && a) a.checked = false; });
      const all = document.getElementById("goldAvailAllDay");
      const row = document.getElementById("goldAvailRow");
      if(all && row) all.addEventListener("change", () => { row.style.display = all.checked ? "none" : ""; });
      // keep the footer status honest while the manager fills the form
      ["goldClearAvail","goldClearPend","goldSalary","goldAvailAllDay","goldAvailDate","goldAvailTime"].forEach((id) => {
        const el = document.getElementById(id);
        if(!el) return;
        el.addEventListener("change", () => this._syncSteps());
        el.addEventListener("input", () => this._syncSteps());
      });
    },

    _collectTrack(){
      if(this._track === "elementary") return { ok:true, data:{ goldTrack:"elementary" } };
      if(this._track !== "pension") return { ok:false, msg:"בחר מסלול — פנסיה או אלמנטרי." };
      const avail = document.getElementById("goldClearAvail")?.checked === true;
      const pend  = document.getElementById("goldClearPend")?.checked === true;
      if(!avail && !pend) return { ok:false, msg:"סמן את מצב המסלקה בשורנס." };
      const salary = safeTrim(document.getElementById("goldSalary")?.value);
      if(!salary) return { ok:false, msg:"מלא את שכר המבוטח." };
      const allDay = document.getElementById("goldAvailAllDay")?.checked === true;
      const d = safeTrim(document.getElementById("goldAvailDate")?.value);
      const t = safeTrim(document.getElementById("goldAvailTime")?.value);
      if(!allDay && (!d || !t)) return { ok:false, msg:"בחר תאריך ושעה לזמינות, או סמן ׳זמין בכל שעות היום׳." };
      return { ok:true, data:{
        goldTrack:"pension",
        goldClearing: avail ? "available" : "pending",
        goldSalary: salary,
        goldAvailAllDay: allDay,
        goldAvailDate: allDay ? "" : d,
        goldAvailTime: allDay ? "" : t
      } };
    },

    async create(){
      if(!goldLeadCanUse()) return;
      const c = this._selected;
      if(!c){ showCampaignLeadToast("לא נבחר לקוח", "בחר לקוח מהרשימה."); return; }
      const phone = goldLeadCustomerPhone(c);
      if(!isValidIsraeliPhone(phone)){
        showCampaignLeadToast("טלפון לא תקין", "ללקוח זה אין מספר טלפון תקין. עדכן את הרשומה ונסה שוב.");
        return;
      }
      const targetId = safeTrim(this._el("goldLeadTargetAgent")?.value);
      const target = goldLeadActiveAgents().find((a) => safeTrim(a.id) === targetId);
      if(!target){ showCampaignLeadToast("חסר נציג", "בחר נציג לשיוך הליד."); return; }
      const srcId = safeTrim(this._el("goldLeadSourceAgent")?.value);
      const src = goldLeadActiveAgents().find((a) => safeTrim(a.id) === srcId);
      const track = this._collectTrack();
      if(!track.ok){ showCampaignLeadToast("חסרים פרטים", track.msg); return; }

      if(this._pendingDuplicate && !window.confirm(
        `שים לב — ללקוח זה יש פנייה פתוחה המשויכת ל${safeTrim(this._pendingDuplicate.assignedAgentName) || "נציג לא ידוע"}.\n\nהאם ברצונך להמשיך?`
      )) return;

      const btn = this._el("goldLeadCreate");
      if(btn){ btn.disabled = true; btn.textContent = "מקים ליד…"; }
      try {
        const { products, policyCount } = goldLeadCustomerProducts(c);
        const line = getDefaultCampaignLine();
        const stamp = nowISO();
        const res = await CampaignLeadsStore.upsert({
          id: "cl_gold_" + Date.now().toString(36) + Math.random().toString(16).slice(2, 6),
          phone,
          customerName: goldLeadCustomerName(c),
          description: "",
          campaignId: line?.id || "",
          campaignLabel: "ליד זהב",
          assignedAgentId: safeTrim(target.id),
          assignedAgentName: safeTrim(target.name),
          status: "new",
          source: "gold",
          idNumber: goldLeadCustomerId(c),
          birthDate: goldLeadCustomerBirth(c),
          idIssueDate: goldLeadCustomerIssue(c),
          goldLead: true,
          goldCustomerId: safeTrim(c.id),
          goldSourceAgentId: src ? safeTrim(src.id) : "",
          goldSourceAgentName: src ? safeTrim(src.name) : "",
          goldProducts: products,
          goldPolicyCount: policyCount,
          ...track.data,
          createdByName: safeTrim(Auth?.current?.name) || "מנהל",
          updatedByName: safeTrim(Auth?.current?.name) || "מנהל",
          createdAt: stamp,
          updatedAt: stamp
        });
        if(!res?.ok){
          showCampaignLeadToast("ההקמה נכשלה", formatCampaignLeadPersistError(res?.error));
          return;
        }
        try { window.showToast?.({ title:"ליד זהב הוקם", text:`${goldLeadCustomerName(c)} שויך ל${safeTrim(target.name)}.`, variant:"success", durationMs:4200 }); } catch(_e){}
        this.close();
        try { CampaignLeadsUI.render?.(); } catch(_e){}
      } catch(err){
        showCampaignLeadToast("שגיאה", safeTrim(err?.message) || "הקמת הליד נכשלה");
      } finally {
        if(btn){ btn.disabled = false; btn.textContent = "הקם ליד זהב"; }
      }
    }
  };

  const CampaignLeadsUI = {
    els: {},
    filter: "all",
    selectedId: null,
    pollTimer: null,
    splitFilter: "new",
    splitSearch: "",
    monthFilter: "",        // YYYY-MM — empty = current month (form panel)
    dayFilter: "",          // YYYY-MM-DD — empty = current day (list panel)
    agentFilter: "",
    _midnightTimer: null,

    _currentMonthIL(){
      return currentCampaignLeadMonthIL();
    },

    _activeMonthIL(){
      return this.monthFilter || this._currentMonthIL();
    },

    _currentDayIL(){
      return currentCampaignLeadDateIL();
    },

    _activeDayIL(){
      return this.dayFilter || this._currentDayIL();
    },

    _leadsForMonth(list, monthStr){
      const target = safeTrim(monthStr);
      if(!target || target === "ALL") return list || [];
      return (list || []).filter((l) => campaignLeadMatchesMonthIL(l, target));
    },

    _leadsForDay(list, dayStr){
      const target = safeTrim(dayStr) || this._currentDayIL();
      return (list || []).filter((l) => campaignLeadMatchesDateIL(l, target));
    },

    _leadsForToday(list){
      return this._leadsForDay(list, this._currentDayIL());
    },

    _syncMonthInputs(){
      const val = this._activeMonthIL();
      if(this.els.dateFilter) this.els.dateFilter.value = val;
    },

    _syncDayInput(){
      if(this.els.dateFilter2) this.els.dateFilter2.value = this._activeDayIL();
    },

    setMonthFilter(val){
      this.monthFilter = val || "";
      this._syncMonthInputs();
      this.renderSplitLeads();
    },

    setDayFilter(val){
      this.dayFilter = safeTrim(val) || "";
      this.agentFilter = "";
      this._syncDayInput();
      this.renderList();
    },

    _renderAgentSummary(){
      const summaryWrap = document.getElementById("clAgentSummary");
      const summaryTbody = document.getElementById("clAgentSummaryTbody");
      const summaryTitle = document.getElementById("clAgentSummaryTitle");
      if(!summaryTbody) return;
      const dayStr = this._activeDayIL();
      // GI-ELDERLY-LEAD: אותו סקופ כמו הטבלה, אחרת המונים לא יתאימו למוצג.
      const allLeads = scopeElderlyCampaignLeads(this._leadsForDay(CampaignLeadsStore.leads, dayStr));
      const displayDay = formatCampaignLeadDayLabel(dayStr);
      if(summaryTitle) summaryTitle.textContent = "סיכום נציגים — " + displayDay;
      const emptyLabel = dayStr === this._currentDayIL()
        ? "אין לידים להיום"
        : ("אין לידים ליום " + displayDay);
      if(!allLeads.length){
        summaryTbody.innerHTML = '<tr><td colspan="8" class="muted">' + escapeHtml(emptyLabel) + '</td></tr>';
        if(summaryWrap) summaryWrap.style.display = "";
        return;
      }
      const agents = Array.isArray(State.data?.agents) ? State.data.agents : [];
      const agentMap = {};
      const bump = (key, status) => {
        if(!agentMap[key]) agentMap[key] = { total:0, new:0, in_progress:0, no_answer:0, agent_appointment:0, closed:0, irrelevant:0 };
        agentMap[key].total++;
        const s = status || "new";
        if(agentMap[key][s] !== undefined) agentMap[key][s]++;
      };
      allLeads.forEach((l) => {
        const names = campaignLeadAllAgentNames(l, agents).filter((n) => n && n !== "—");
        if(!names.length){
          bump("לא שויך", l.status);
          return;
        }
        names.forEach((name) => bump(name, l.status));
      });
      const rows = Object.entries(agentMap).sort((a,b) => b[1].total - a[1].total);
      summaryTbody.innerHTML = rows.map(([name, c]) =>
        `<tr>
          <td><strong>${escapeHtml(name)}</strong></td>
          <td><span class="lcAgentSummary__total">${c.total}</span></td>
          <td>${c.new || 0}</td>
          <td>${c.in_progress || 0}</td>
          <td>${c.no_answer || 0}</td>
          <td>${c.agent_appointment || 0}</td>
          <td><span class="${c.closed ? "lcAgentSummary__closed" : ""}">${c.closed || 0}</span></td>
          <td><span class="${c.irrelevant ? "lcAgentSummary__irr" : ""}">${c.irrelevant || 0}</span></td>
        </tr>`
      ).join("");
      if(summaryWrap) summaryWrap.style.display = "";
    },

    scheduleMidnightReset(){
      if(this._midnightTimer) clearTimeout(this._midnightTimer);
      const now = new Date();
      const ilNow = new Date(now.toLocaleString("en-US", { timeZone: "Asia/Jerusalem" }));
      const ilMidnight = new Date(ilNow);
      ilMidnight.setHours(24, 0, 0, 0);
      const msUntilMidnight = ilMidnight - ilNow;
      this._midnightTimer = setTimeout(() => {
        this.monthFilter = "";
        this.dayFilter = "";
        this._syncMonthInputs();
        this._syncDayInput();
        this.renderSplitLeads();
        this.renderList();
        this._renderAgentSummary();
        this.scheduleMidnightReset();
      }, msUntilMidnight);
    },

    _buildListAgentChips(monthScopedLeads){
      const agentChipsEl = document.getElementById("campaignLeadsAgentChips");
      const agentFilterEl = document.getElementById("campaignLeadsAgentFilter");
      if(!agentChipsEl) return;
      const agents = Array.isArray(State.data?.agents) ? State.data.agents : [];
      const namesSet = new Set();
      // GI-ELDERLY-LEAD
      scopeElderlyCampaignLeads(monthScopedLeads).forEach((l) => {
        campaignLeadAllAgentNames(l, agents).forEach((n) => {
          if(n && n !== "—") namesSet.add(n);
        });
      });
      const names = Array.from(namesSet).sort((a, b) => a.localeCompare(b, "he"));
      if(!names.length){
        if(agentFilterEl) agentFilterEl.style.display = "none";
        return;
      }
      if(agentFilterEl) agentFilterEl.style.display = "";
      const cur = this.agentFilter;
      agentChipsEl.innerHTML =
        `<button class="mcSearch__chip${!cur ? " is-active" : ""}" data-cl-list-agent="" type="button">הכל</button>` +
        names.map((n) =>
          `<button class="mcSearch__chip${n === cur ? " is-active" : ""}" data-cl-list-agent="${escapeHtml(n)}" type="button">${escapeHtml(n)}</button>`
        ).join("");
    },

    init(){
      this.els.tbody = document.getElementById("campaignLeadsTbody");
      this.els.badge = document.getElementById("campaignLeadsCountBadge");
      this.els.alert = document.getElementById("campaignLeadsTableAlert");
      this.els.filters = document.getElementById("campaignLeadsFilters");
      this.els.form = document.getElementById("campaignLeadForm");
      this.els.phone = document.getElementById("clPhone");
      this.els.customerName = document.getElementById("clCustomerName");
      this.els.idNumber = document.getElementById("clIdNumber");
      this.els.idIssueDate = document.getElementById("clIdIssueDate");
      this.els.birthDate = document.getElementById("clBirthDate");
      this.els.description = document.getElementById("clDescription");
      this.els.btnContinueProposal = document.getElementById("btnCampaignLeadContinueProposal");
      this.els.campaign = document.getElementById("clCampaign");
      this.els.agent = document.getElementById("clAgent");
      this.els.status = document.getElementById("clStatus");
      this.els.formErr = document.getElementById("campaignLeadFormErr");
      this.els.editorTitle = document.getElementById("campaignLeadEditorTitle");
      this.els.btnRefresh = document.getElementById("btnCampaignLeadsRefresh");
      this.els.btnSimulate = document.getElementById("btnCampaignLeadSimulate");
      this.els.btnNew = document.getElementById("btnCampaignLeadNew");
      this.els.formPanel = document.getElementById("campaignLeadsFormPanel");
      this.els.listPanel = document.getElementById("campaignLeadsListPanel");
      this.els.btnShowList = document.getElementById("btnCampaignShowLeadsList");
      this.els.btnShowForm = document.getElementById("btnCampaignShowForm");
      this.els.trackingPanel = document.getElementById("campaignLeadsTrackingPanel");
      this.els.btnShowTracking1 = document.getElementById("btnCampaignShowTracking1");
      this.els.btnShowTracking2 = document.getElementById("btnCampaignShowTracking2");
      this.els.btnShowFormFromTracking = document.getElementById("btnCampaignShowFormFromTracking");
      this.els.btnShowListFromTracking = document.getElementById("btnCampaignShowListFromTracking");
      this.els.splitList = document.getElementById("clSplitLeadsList");
      this.els.splitCount = document.getElementById("clSplitLeadsCount");
      this.els.splitFilters = document.getElementById("clSplitLeadsFilters");
      this.els.splitSearch = document.getElementById("clSplitLeadsSearch");
      if(this.els.splitFilters) on(this.els.splitFilters, "click", (ev) => {
        const chip = ev.target.closest("[data-split-filter]");
        if(!chip) return;
        this.splitFilter = chip.getAttribute("data-split-filter") || "new";
        this.els.splitFilters.querySelectorAll(".lcSplitLeads__chip").forEach((c) => c.classList.toggle("is-active", c === chip));
        this.renderSplitLeads();
      });
      if(this.els.splitSearch) on(this.els.splitSearch, "input", perfDebounce(() => {
        this.splitSearch = (this.els.splitSearch.value || "").trim();
        this.renderSplitLeads();
      }, 250));
      if(this.els.splitList) on(this.els.splitList, "click", (ev) => {
        const reassignBtn = ev.target.closest("[data-cl-reassign-id]");
        if(reassignBtn){
          ev.stopPropagation();
          ev.preventDefault();
          handleCampaignLeadReassignBtn(reassignBtn);
          return;
        }
        const card = ev.target.closest("[data-split-cl-id]");
        if(!card) return;
        this.selectLead(card.getAttribute("data-split-cl-id"));
      });
      if(this.els.splitList) on(this.els.splitList, "keydown", (ev) => {
        if(ev.key !== "Enter" && ev.key !== " ") return;
        const card = ev.target.closest("[data-split-cl-id]");
        if(!card) return;
        ev.preventDefault();
        this.selectLead(card.getAttribute("data-split-cl-id"));
      });
      if(this.els.btnShowList) on(this.els.btnShowList, "click", () => this.showPanel("list"));
      // GI-GOLD-LEAD — wire the manager-only entry points
      ["btnGoldLeadForm","btnGoldLeadList"].forEach((btnId) => {
        const b = document.getElementById(btnId);
        if(b) on(b, "click", () => GoldLeadModal.open());
      });
      // GI-GOLD-LEAD — tracking board
      ["btnGoldBoardForm","btnGoldBoardList"].forEach((bid) => {
        const b = document.getElementById(bid);
        if(b) on(b, "click", () => this.showPanel("gold"));
      });
      this.syncGoldButtons();
      const gbBack = document.getElementById("btnGoldBoardBack");
      if(gbBack) on(gbBack, "click", () => this.showPanel("list"));
      const gbFrom = document.getElementById("goldBoardFrom");
      const gbTo = document.getElementById("goldBoardTo");
      const syncRange = () => GoldLeadBoard.setRange(gbFrom?.value, gbTo?.value);
      if(gbFrom) on(gbFrom, "change", syncRange);
      if(gbTo) on(gbTo, "change", syncRange);
      const gbToday = document.getElementById("btnGoldBoardToday");
      if(gbToday) on(gbToday, "click", () => GoldLeadBoard.resetToday());
      const gbRefresh = document.getElementById("btnGoldBoardRefresh");
      if(gbRefresh) on(gbRefresh, "click", () => GoldLeadBoard.render());

      const glModal = document.getElementById("goldLeadModal");
      if(glModal){
        const q = document.getElementById("goldLeadSearchInput");
        if(q) on(q, "input", () => GoldLeadModal.search());
        const res = document.getElementById("goldLeadResults");
        if(res) on(res, "click", (ev) => {
          const btn = ev.target.closest("[data-gold-pick]");
          if(btn) GoldLeadModal.select(btn.getAttribute("data-gold-pick"));
        });
        ["goldLeadCancel","goldLeadCancel2"].forEach((cid) => {
          const el = document.getElementById(cid);
          if(el) on(el, "click", () => GoldLeadModal.close());
        });
        const ok = document.getElementById("goldLeadCreate");
        if(ok) on(ok, "click", () => GoldLeadModal.create());
        const det = document.getElementById("goldLeadDetail");
        if(det) on(det, "click", (ev) => {
          const tb = ev.target.closest("[data-gold-track]");
          if(tb){ GoldLeadModal.setTrack(tb.getAttribute("data-gold-track")); return; }
          if(ev.target.closest(".goldFs__trackForm")) setTimeout(() => GoldLeadModal._syncSteps(), 0);
        });
      }
      if(this.els.btnShowForm) on(this.els.btnShowForm, "click", () => this.showPanel("form"));
      if(this.els.btnShowTracking1) on(this.els.btnShowTracking1, "click", () => this.showPanel("tracking"));
      if(this.els.btnShowTracking2) on(this.els.btnShowTracking2, "click", () => this.showPanel("tracking"));
      if(this.els.btnShowFormFromTracking) on(this.els.btnShowFormFromTracking, "click", () => this.showPanel("form"));
      if(this.els.btnShowListFromTracking) on(this.els.btnShowListFromTracking, "click", () => this.showPanel("list"));
      if(this.els.btnNew) on(this.els.btnNew, "click", () => this.beginNewLead());
      if(this.els.filters) on(this.els.filters, "click", (ev) => {
        const chip = ev.target.closest("[data-cl-filter]");
        if(!chip) return;
        this.filter = chip.getAttribute("data-cl-filter") || "all";
        this.els.filters.querySelectorAll(".mcSearch__chip").forEach((c) => c.classList.toggle("is-active", c === chip));
        this.renderList();
      });
      const listAgentChipsEl = document.getElementById("campaignLeadsAgentChips");
      if(listAgentChipsEl) on(listAgentChipsEl, "click", (ev) => {
        const chip = ev.target.closest("[data-cl-list-agent]");
        if(!chip) return;
        this.agentFilter = chip.getAttribute("data-cl-list-agent") || "";
        listAgentChipsEl.querySelectorAll(".mcSearch__chip").forEach((c) => c.classList.toggle("is-active", c === chip));
        this.renderList();
      });
      if(this.els.tbody) on(this.els.tbody, "click", (ev) => {
        const reassignBtn = ev.target.closest("[data-cl-reassign-id]");
        if(reassignBtn){
          ev.stopPropagation();
          handleCampaignLeadReassignBtn(reassignBtn);
          return;
        }
        const noteBtn = ev.target.closest("[data-cl-note-id]");
        if(noteBtn){
          ev.stopPropagation();
          handleCampaignLeadAgentNoteBtn(noteBtn);
          return;
        }
        const row = ev.target.closest("[data-cl-id]");
        if(!row) return;
        this.selectLead(row.getAttribute("data-cl-id"));
        this.showPanel("form");
      });
      if(this.els.form) on(this.els.form, "submit", (ev) => { ev.preventDefault(); this.saveSelected(); });
      if(this.els.btnRefresh) on(this.els.btnRefresh, "click", () => void this.refresh(true));
      if(this.els.btnSimulate) on(this.els.btnSimulate, "click", () => void this.simulateInbound());
      if(this.els.btnContinueProposal){
        on(this.els.btnContinueProposal, "click", () => {
          const lead = this.getSelectedLead();
          if(lead) Wizard.openHealthWizardFromCampaignLead(lead);
        });
      }
      // ── Date filter inputs (form: month · list: day) ──
      this.els.dateFilter = document.getElementById("clDateFilter");
      this.els.dateFilter2 = document.getElementById("clDateFilter2");
      this.els.btnDateToday = document.getElementById("btnClDateToday");
      this.els.btnDateToday2 = document.getElementById("btnClDateToday2");
      this._syncMonthInputs();
      this._syncDayInput();
      if(this.els.dateFilter) on(this.els.dateFilter, "change", (e) => { this.setMonthFilter(e.target.value); });
      if(this.els.dateFilter2) on(this.els.dateFilter2, "change", (e) => { this.setDayFilter(e.target.value); });
      if(this.els.btnDateToday) on(this.els.btnDateToday, "click", () => this.setMonthFilter(""));
      if(this.els.btnDateToday2) on(this.els.btnDateToday2, "click", () => this.setDayFilter(""));
      try { CampaignLeadInsuranceDropdown.init(); } catch(_e) {}
    },

    // GI-GOLD-LEAD — init() runs before login, so permission must be re-checked
    // every time the screen is shown, not once at boot.
    syncGoldButtons(){
      const show = goldLeadCanUse() ? "" : "none";
      ["btnGoldLeadForm","btnGoldLeadList","btnGoldBoardForm","btnGoldBoardList"].forEach((id) => {
        const b = document.getElementById(id);
        if(b) b.style.display = show;
      });
    },

    showPanel(panel){
      this.syncGoldButtons();
      if(this.els.formPanel) this.els.formPanel.style.display = panel === "form" ? "" : "none";
      if(this.els.listPanel) this.els.listPanel.style.display = panel === "list" ? "" : "none";
      if(this.els.trackingPanel){
        if(panel === "tracking"){
          this.els.trackingPanel.hidden = false;
          this.els.trackingPanel.style.display = "";
        } else {
          this.els.trackingPanel.hidden = true;
          this.els.trackingPanel.style.display = "none";
        }
      }
      try { CampaignLeadInsuranceDropdown._close(); } catch(_e) {}
      // GI-GOLD-LEAD
      const goldPanel = document.getElementById("campaignLeadsGoldPanel");
      if(goldPanel) goldPanel.style.display = panel === "gold" ? "" : "none";
      if(panel === "list") this._syncDayInput();
      if(panel === "tracking") TrackingReportUI.render();
      if(panel === "gold"){
        const f = document.getElementById("goldBoardFrom");
        const t = document.getElementById("goldBoardTo");
        if(f && !f.value) f.value = GoldLeadBoard._activeFrom();
        if(t && !t.value) t.value = GoldLeadBoard._activeTo();
        GoldLeadBoard.render();
      }
    },

    showAlert(msg, tone = "warn"){
      if(!this.els.alert) return;
      if(!msg){ this.els.alert.hidden = true; this.els.alert.textContent = ""; return; }
      this.els.alert.hidden = false;
      this.els.alert.textContent = msg;
      this.els.alert.className = "lcCampaign__alert lcCampaign__alert--" + (tone === "err" ? "err" : tone === "ok" ? "ok" : "warn");
    },

    fillCampaignSelect(selectedId){
      if(!this.els.campaign) return;
      const lines = getCampaignLines().filter((l) => l.active);
      this.els.campaign.innerHTML = lines.map((l) =>
        `<option value="${escapeHtml(l.id)}">${escapeHtml(l.label)}</option>`
      ).join("");
      if(selectedId) this.els.campaign.value = selectedId;
    },

    fillAgentSelect(selectedId){
      if(!this.els.agent) return;
      const agents = getAssignableSalesAgents();
      // GI-ELDERLY-LEAD: אפשרות "לקוחות מבוגרים" מוצגת רק לסוקרת/מנהל/אדמין.
      const elderlyOpt = canUseElderlyLeadBucket()
        ? `<option value="${escapeHtml(ELDERLY_LEAD_AGENT_ID)}">${escapeHtml(ELDERLY_LEAD_AGENT_NAME)}</option>`
        : "";
      this.els.agent.innerHTML = '<option value="">— בחר נציג —</option>' + elderlyOpt + agents.map((a) =>
        `<option value="${escapeHtml(a.id)}">${escapeHtml(a.name)}</option>`
      ).join("");
      if(selectedId) this.els.agent.value = selectedId;
    },

    setFormErr(msg){
      if(!this.els.formErr) return;
      if(!msg){ this.els.formErr.style.display = "none"; this.els.formErr.textContent = ""; return; }
      this.els.formErr.style.display = "";
      this.els.formErr.textContent = msg;
    },

    getSelectedLead(){
      return CampaignLeadsStore.leads.find((l) => String(l.id) === String(this.selectedId)) || null;
    },

    selectLead(id){
      this.selectedId = safeTrim(id);
      const lead = this.getSelectedLead();
      goldLeadMarkOpened(lead);   // GI-GOLD-LEAD
      this.renderList();
      if(!lead){
        if(this.els.editorTitle) this.els.editorTitle.textContent = "בחר ליד מהרשימה";
        return;
      }
      const srcLabel = campaignLeadSourceLabel(lead.source);
      if(this.els.editorTitle){
        this.els.editorTitle.textContent = "ליד: " + (lead.phone || "—") + (srcLabel ? " · " + srcLabel : "");
      }
      if(this.els.phone){
        this.els.phone.value = lead.phone || "";
        this.els.phone.readOnly = lead.source === "call" || lead.source === "webhook";
        this.els.phone.disabled = false;
      }
      if(this.els.customerName) this.els.customerName.value = lead.customerName || "";
      if(this.els.idNumber) this.els.idNumber.value = lead.idNumber || "";
      if(this.els.idIssueDate) this.els.idIssueDate.value = lead.idIssueDate || "";
      if(this.els.birthDate) this.els.birthDate.value = lead.birthDate || "";
      if(this.els.description) this.els.description.value = lead.descriptionDisplay || stripCampaignLeadPayloadMarker(lead.description) || "";
      try { CampaignLeadInsuranceDropdown.setValue(lead.insuranceCompany || ""); } catch(_e) {}
      if(this.els.btnContinueProposal){
        const canContinue = lead.source === "landing_page" && agentCanOpenCampaignLead(lead) && !!safeTrim(lead.idNumber);
        this.els.btnContinueProposal.hidden = !canContinue;
      }
      this.fillCampaignSelect(lead.campaignId);
      this.fillAgentSelect(lead.assignedAgentId);
      if(this.els.status) this.els.status.value = lead.status || "new";
      this.setFormErr("");
      if(lead.source === "landing_page" && lead.status === "new" && !safeTrim(lead.assignedAgentId)){
        this.showAlert("ליד מדף נחיתה (בריאות וסיכונים) — יש לשייך נציג ולשמור", "warn");
      } else {
        this.showAlert("");
      }
    },

    filteredLeads(){
      // GI-ELDERLY-LEAD: כל סוקרת רואה רק את המבוגרים שהיא שייכה.
      let list = scopeElderlyCampaignLeads(goldLeadFilterForViewer(this._leadsForDay(CampaignLeadsStore.leads, this._activeDayIL())));
      const agents = Array.isArray(State.data?.agents) ? State.data.agents : [];
      if(this.agentFilter){
        list = list.filter((l) => campaignLeadMatchesAgentFilter(l, this.agentFilter, agents));
      }
      if(this.filter && this.filter !== "all"){
        list = list.filter((l) => safeTrim(l.status) === this.filter);
      }
      return list;
    },

    splitFilteredLeads(){
      // GI-ELDERLY-LEAD
      let list = scopeElderlyCampaignLeads(goldLeadFilterForViewer(this._leadsForToday(CampaignLeadsStore.leads)));
      if(this.splitFilter !== "all") list = list.filter((l) => campaignLeadIsOpenInInbox(l.status));
      const q = (this.splitSearch || "").toLowerCase();
      if(q){
        list = list.filter((l) =>
          (l.customerName || "").toLowerCase().includes(q) ||
          (l.phone || "").includes(q) ||
          (l.idNumber || "").includes(q)
        );
      }
      return list;
    },

    renderSplitLeads(){
      const container = this.els.splitList;
      if(!container) return;
      const rows = this.splitFilteredLeads();
      if(this.els.splitCount) this.els.splitCount.textContent = rows.length + " לידים";
      if(!rows.length){
        container.innerHTML = '<div class="lcSplitLeads__empty"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" width="32" height="32"><path d="M17 21v-2a4 4 0 0 0-4-4H5a4 4 0 0 0-4 4v2"/><circle cx="9" cy="7" r="4"/><path d="M23 21v-2a4 4 0 0 0-3-3.87"/><path d="M16 3.13a4 4 0 0 1 0 7.75"/></svg><span>אין לידים להצגה</span></div>';
        return;
      }
      const agents = Array.isArray(State.data?.agents) ? State.data.agents : [];
      container.innerHTML = rows.map((lead) => {
        const isActive = String(lead.id) === String(this.selectedId);
        const statusKey = lead.status || "new";
        const statusLabel = campaignLeadStatusLabel(statusKey);
        const agentName = campaignLeadAgentsDisplay(lead, agents);
        let dateStr = "";
        try {
          const d = new Date(lead.createdAt);
          if(!isNaN(d.getTime())){
            dateStr = d.toLocaleDateString("he-IL", { timeZone:"Asia/Jerusalem", day:"2-digit", month:"2-digit", year:"2-digit" });
          }
        } catch(_e){}
        const name = escapeHtml(safeTrim(lead.customerName) || "—");
        const phone = escapeHtml(lead.phone || "—");
        const tz = escapeHtml(lead.idNumber || "—");
        const phoneIcon = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linecap="round" stroke-linejoin="round" width="12" height="12"><path d="M6.6 10.8c1.4 2.8 3.8 5.1 6.6 6.6l2.2-2.2c.3-.3.7-.4 1-.2 1.1.4 2.3.6 3.6.6.6 0 1 .4 1 1V20c0 .6-.4 1-1 1C10.6 21 3 13.4 3 4c0-.6.4-1 1-1h3.5c.6 0 1 .4 1 1 0 1.3.2 2.5.6 3.6.1.3 0 .7-.2 1L6.6 10.8Z"/></svg>';
        const tzIcon = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linecap="round" stroke-linejoin="round" width="12" height="12"><path d="M20 21v-2a4 4 0 0 0-4-4H8a4 4 0 0 0-4 4v2"/><circle cx="12" cy="7" r="4"/></svg>';
        const agentIcon = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linecap="round" stroke-linejoin="round" width="12" height="12"><path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2"/><circle cx="9" cy="7" r="4"/><path d="M22 21v-2a4 4 0 0 0-3-3.87"/><path d="M16 3.13a4 4 0 0 1 0 7.75"/></svg>';
        const calIcon = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linecap="round" stroke-linejoin="round" width="12" height="12"><rect x="3" y="4" width="18" height="18" rx="2"/><path d="M16 2v4M8 2v4M3 10h18"/></svg>';
        const agentHtml = agentName && agentName !== "—"
          ? `<span class="lcSplitCard__val lcSplitCard__agent">${escapeHtml(agentName)}</span>`
          : `<span class="lcSplitCard__val lcSplitCard__agentUnassigned">לא שויך נציג</span>`;
        return `<div class="lcSplitCard${isActive ? " is-active" : ""}" data-split-cl-id="${escapeHtml(String(lead.id))}" data-status="${escapeHtml(statusKey)}" role="button" tabindex="0">
  <div class="lcSplitCard__top">
    <div class="lcSplitCard__name">${name}${campaignLeadGoldBadgeHtml(lead)}</div>
    <span class="lcSplitCard__statusPill lcSplitCard__statusPill--${escapeHtml(statusKey)}">${escapeHtml(statusLabel)}</span>
  </div>
  <div class="lcSplitCard__rows">
    <div class="lcSplitCard__row">
      ${phoneIcon}
      <span class="lcSplitCard__rowLabel">טלפון</span>
      <span class="lcSplitCard__val lcSplitCard__phone" dir="ltr">${phone}</span>
    </div>
    <div class="lcSplitCard__row">
      ${tzIcon}
      <span class="lcSplitCard__rowLabel">ת״ז</span>
      <span class="lcSplitCard__val lcSplitCard__tz" dir="ltr">${tz}</span>
    </div>
    <div class="lcSplitCard__row">
      ${agentIcon}
      <span class="lcSplitCard__rowLabel">נציג</span>
      ${agentHtml}
    </div>
    <div class="lcSplitCard__row">
      ${calIcon}
      <span class="lcSplitCard__rowLabel">תאריך</span>
      <span class="lcSplitCard__val lcSplitCard__date">${escapeHtml(dateStr)}</span>
    </div>
  </div>
  <div class="lcSplitCard__actions">${campaignLeadReassignBtnHtml(lead.id)}</div>
</div>`;
      }).join("");
    },

    renderList(){
      if(this.els.tbody){
        const rows = this.filteredLeads();
        if(this.els.badge) this.els.badge.textContent = rows.length + " לידים";
        if(!rows.length){
          this.els.tbody.innerHTML = '<tr><td colspan="9" class="muted">אין לידים בסינון הנוכחי</td></tr>';
        } else {
          const agents = Array.isArray(State.data?.agents) ? State.data.agents : [];
          this.els.tbody.innerHTML = rows.map((lead) => {
            const active = String(lead.id) === String(this.selectedId) ? ' class="is-selected"' : "";
            const timeRaw = safeTrim(lead.createdAt);
            let time = "";
            try {
              const d = new Date(timeRaw);
              if(!isNaN(d.getTime())){
                time = d.toLocaleString("he-IL", { timeZone:"Asia/Jerusalem", day:"2-digit", month:"2-digit", year:"numeric", hour:"2-digit", minute:"2-digit" });
              }
            } catch(_e){ time = timeRaw.slice(0,16).replace("T"," "); }
            const lastModRaw = safeTrim(lead.lastModifiedAt || lead.updatedAt);
            let lastMod = "";
            try {
              const dm = new Date(lastModRaw);
              if(!isNaN(dm.getTime())){
                lastMod = dm.toLocaleString("he-IL", { timeZone:"Asia/Jerusalem", day:"2-digit", month:"2-digit", year:"numeric", hour:"2-digit", minute:"2-digit" });
              }
            } catch(_e){ lastMod = lastModRaw ? lastModRaw.slice(0,16).replace("T"," ") : ""; }
            const srcBadge = lead.source === "landing_page"
              ? '<span class="lcCampaign__srcBadge">דף נחיתה</span>'
              : (lead.source === "call" ? '<span class="lcCampaign__srcBadge lcCampaign__srcBadge--call">שיחה</span>' : "");
            let agentName = campaignLeadAgentsDisplay(lead, agents);
            const leadName = safeTrim(lead.customerName) || "—";
            let statusDisplay = escapeHtml(campaignLeadStatusLabel(lead.status));
            if(lead.status === "closed" && safeTrim(lead.closedAt)){
              try {
                const dc = new Date(lead.closedAt);
                if(!isNaN(dc.getTime())){
                  statusDisplay += ' <span class="muted small">(' + escapeHtml(dc.toLocaleDateString("he-IL", { timeZone:"Asia/Jerusalem", day:"2-digit", month:"2-digit", year:"numeric" })) + ')</span>';
                }
              } catch(_e){}
            }
            statusDisplay += campaignLeadAgentNoteBtnHtml(lead);
            return `<tr data-cl-id="${escapeHtml(lead.id)}"${active}>
              <td>${escapeHtml(leadName)}</td>
              <td dir="ltr">${escapeHtml(lead.phone)}</td>
          <td class="lcCampaign__agentCell">${escapeHtml(agentName)}</td>
          <td>${escapeHtml(lead.campaignLabel)}${srcBadge}</td>
          <td>${escapeHtml(safeTrim(lead.insuranceCompany) || "—")}</td>
          <td>${statusDisplay}</td>
              <td>${escapeHtml(time)}</td>
              <td>${escapeHtml(lastMod)}</td>
              <td class="lcCampaign__actions">${campaignLeadReassignBtnHtml(lead.id)}</td>
            </tr>`;
          }).join("");
        }
      }
      this.renderSplitLeads();
      this._renderAgentSummary();
      const dayScopedLeads = this._leadsForDay(CampaignLeadsStore.leads, this._activeDayIL());
      this._buildListAgentChips(dayScopedLeads);
    },

    beginNewLead(options = {}){
      this.selectedId = null;
      if(this.els.editorTitle) this.els.editorTitle.textContent = "ליד חדש — הזן פרטים";
      if(this.els.phone){
        this.els.phone.value = "";
        this.els.phone.readOnly = false;
        this.els.phone.disabled = false;
      }
      if(this.els.customerName) this.els.customerName.value = "";
      if(this.els.idNumber) this.els.idNumber.value = "";
      if(this.els.idIssueDate) this.els.idIssueDate.value = "";
      if(this.els.birthDate) this.els.birthDate.value = "";
      if(this.els.description) this.els.description.value = "";
      try { CampaignLeadInsuranceDropdown.clear(); } catch(_e) {}
      if(this.els.btnContinueProposal) this.els.btnContinueProposal.hidden = true;
      this.fillCampaignSelect(getLandingCampaignLine().id);
      this.fillAgentSelect("");
      if(this.els.status) this.els.status.value = "new";
      this.setFormErr("");
      this.showAlert("");
      if(options.skipListRender !== true) this.renderList();
      try { this.els.phone?.focus?.(); } catch(_e) {}
    },

    scheduleListRender(){
      window.requestAnimationFrame(() => {
        try { this.renderList(); } catch(_e) {}
      });
    },

    clearForm(){
      this.beginNewLead();
    },

    async refresh(showToast, options = {}){
      this.showAlert(CampaignLeadsStore.tableReady ? "" : "יש להריץ את supabase/campaign-leads-schema.sql ב-Supabase (טבלה campaign_leads)", CampaignLeadsStore.tableReady ? "ok" : "warn");
      const retries = Math.max(1, Number(options.retries) || 1);
      let r = { ok: false };
      for(let attempt = 0; attempt < retries; attempt++){
        r = await CampaignLeadsStore.fetchAll({ scope: "all" });
        if(r.ok) break;
        if(attempt < retries - 1){
          await new Promise((resolve) => window.setTimeout(resolve, 700 * (attempt + 1)));
        }
      }
      if(!r.ok) this.showAlert("לא נטענו לידים: " + (r.error || ""), "err");
      this.renderList();
      if(this.selectedId) this.selectLead(this.selectedId);
      if(showToast && typeof toast === "function" && r.ok) toast("רשימת לידים עודכנה");
    },

    async render(){
      if(!Auth.canAccessCampaignLeadsInbox()) return;
      if(this.els.btnSimulate) this.els.btnSimulate.hidden = !(Auth.isAdmin() || Auth.isManager());
      this.showPanel("form");
      this.fillCampaignSelect();
      this.fillAgentSelect();

      /* GI-PERF 2026-07-31 (שלב ו'): קודם היה כאן
             await this.refresh(false, { retries: 4 });
         לפני renderList. כלומר המסך נשאר ריק לאורך כל שרשרת הרשת:
         loadCampaignLeadRows שולף select("*") בעמודים של 1000 עד 25,000 שורות,
         בקשות סדרתיות, ומעליו עד 4 ניסיונות עם המתנה של 700/1400/2100ms.
         במקרה הגרוע המשתמש בוהה במסך ריק עשרות שניות. זה מה שנראה כתקיעה.
         עכשיו: צובעים מהמטמון, הטופס שמיש מיד, והרענון רץ ברקע. */
      try { CampaignLeadsStore.hydrateFromCacheIfEmpty(); } catch(_e) {}
      try { this.renderList(); } catch(_e) {}
      if(!this.selectedId) this.beginNewLead();
      this._renderAgentSummary();
      this.scheduleMidnightReset();
      this.startPoll();

      void this.refresh(false, { retries: 4 })
        .then(() => {
          if(LiveRefresh?.getCurrentView?.() !== "campaignLeads") return;
          try { this._renderAgentSummary(); } catch(_e) {}
        })
        .catch(() => {});
    },

    startPoll(){
      this.stopPoll();
      this.pollTimer = window.setInterval(() => {
        if(LiveRefresh?.getCurrentView?.() !== "campaignLeads") return;
        if(LiveRefresh?.hasBlockingFlow?.()) return;
        void CampaignLeadsStore.fetchAll({ scope: "all" }).then(() => this.renderList());
      }, 60000);
    },

    stopPoll(){
      if(this.pollTimer){ window.clearInterval(this.pollTimer); this.pollTimer = null; }
    },

    saveSelected(){
      const existing = this.getSelectedLead();
      const phone = normalizePhoneValue(this.els.phone?.value || existing?.phone);
      if(!isValidIsraeliPhone(phone)){ this.setFormErr("יש להזין מספר טלפון תקין"); return; }
      const agentId = safeTrim(this.els.agent?.value);
      // GI-ELDERLY-LEAD: הדלי אינו נציג אמיתי, ולכן עוקף את חיפוש הנציג.
      const isElderlyPick = agentId === ELDERLY_LEAD_AGENT_ID && canUseElderlyLeadBucket();
      let targetAgent;
      if(isElderlyPick){
        targetAgent = { id: ELDERLY_LEAD_AGENT_ID, name: ELDERLY_LEAD_AGENT_NAME };
      } else {
        const agent = getAssignableSalesAgents().find((a) => String(a.id) === agentId);
        if(!agent){ this.setFormErr("יש לבחור נציג לשיוך"); return; }
        targetAgent = resolveCampaignLeadTargetAgent(agent);
      }
      const campaignId = safeTrim(this.els.campaign?.value);
      const line = getCampaignLines().find((c) => String(c.id) === campaignId) || getDefaultCampaignLine();
      const stamp = nowISO();
      const prevAgentId = safeTrim(existing?.assignedAgentId);
      const prevStatus = safeTrim(existing?.status);
      const assignedChanged = String(prevAgentId || "") !== String(targetAgent.id);
      // שיוך מחדש של ליד "לא רלוונטי" לנציג אחר → הנציג החדש מקבל ליד חדש (סטטוס new)
      const resetIrrelevantForNewAgent = !!(assignedChanged && prevAgentId && prevStatus === "irrelevant");
      const leadStatus = resetIrrelevantForNewAgent
        ? "new"
        : (prevAgentId
          ? (safeTrim(this.els.status?.value) || prevStatus || "in_progress")
          : (safeTrim(this.els.status?.value) || "new"));
      const next = normalizeCampaignLead({
        ...(existing || {}),
        id: existing?.id || ("cl_" + Date.now().toString(36) + Math.random().toString(16).slice(2, 6)),
        phone,
        customerName: safeTrim(this.els.customerName?.value),
        idNumber: normalizeIdValue(this.els.idNumber?.value),
        idIssueDate: safeTrim(this.els.idIssueDate?.value),
        birthDate: safeTrim(this.els.birthDate?.value),
        insuranceCompany: CampaignLeadInsuranceDropdown.getValue(),
        description: safeTrim(this.els.description?.value),
        campaignId: line.id,
        campaignLabel: line.label,
        assignedAgentId: targetAgent.id,
        assignedAgentName: targetAgent.name,
        // GI-ELDERLY-LEAD: חותמים את הסוקרת הבעלים כדי שרק היא תראה את הרשומה.
        elderlyOwnerId: isElderlyPick
          ? (safeTrim(existing?.elderlyOwnerId) || safeTrim(Auth?.current?.id))
          : "",
        elderlyOwnerName: isElderlyPick
          ? (safeTrim(existing?.elderlyOwnerName) || safeTrim(Auth?.current?.name))
          : "",
        status: leadStatus,
        irrelevantNote: resetIrrelevantForNewAgent ? "" : (existing?.irrelevantNote || ""),
        source: existing?.source || "manual",
        createdAt: existing?.createdAt || stamp,
        updatedAt: stamp,
        lastModifiedAt: stamp,
        createdByName: existing?.createdByName || safeTrim(Auth?.current?.name) || "רפרנטית",
        updatedByName: safeTrim(Auth?.current?.name) || ""
      });
      if(!safeTrim(next.customerName)){ this.setFormErr("יש להזין שם לקוח"); return; }
      if(!safeTrim(next.description)){ this.setFormErr("יש להזין סיבת פנייה"); return; }
      const previousLead = existing ? { ...existing } : null;
      const leadId = next.id;

      // Reset immediately so the referent can enter the next lead while save runs in background.
      this.beginNewLead({ skipListRender: true });

      CampaignLeadsStore.pendingRemoteSaveIds.add(String(leadId));
      CampaignLeadsStore.applyLocal(next);
      this.scheduleListRender();

      void CampaignLeadsStore.persistRemote(next).then((save) => {
        CampaignLeadsStore.pendingRemoteSaveIds.delete(String(leadId));
        if(!save.ok){
          if(previousLead){
            CampaignLeadsStore.applyLocal(previousLead);
          } else {
            CampaignLeadsStore.applyLocal(next);
            this.selectLead(leadId);
            this.showPanel("form");
            this.setFormErr(save.error || "הליד לא נשמר בשרת — נסה שוב");
          }
          this.scheduleListRender();
          showCampaignLeadToast("שגיאה בשמירה", save.error || "הליד לא נשמר בשרת — נסה שוב", "err");
          return;
        }
        this.scheduleListRender();
        if(assignedChanged){
          try { CampaignLeadAssignInbox.forgetDelivered(next.id, targetAgent.id); } catch(_e) {}
          void AgentActivityLog.logLead("lead_assigned", next, {
            agent: { id: targetAgent.id, name: targetAgent.name },
            detailText: resetIrrelevantForNewAgent
              ? `שויך מחדש כליד חדש (אחרי לא רלוונטי) על ידי ${safeTrim(Auth?.current?.name) || "מערכת"}`
              : `שויך על ידי ${safeTrim(Auth?.current?.name) || "מערכת"}`
          });
          void CampaignLeadAssignInbox.syncAssignNotice({
            targetAgentId: targetAgent.id,
            targetAgentName: targetAgent.name,
            fromName: safeTrim(Auth?.current?.name) || "מערכת",
            leadId: next.id,
            customerName: next.customerName,
            phone: next.phone,
            campaignLabel: next.campaignLabel
          });
        }
      });
    },

    async simulateInbound(){
      if(!(Auth.isAdmin() || Auth.isManager())) return;
      const phone = "05" + String(Math.floor(10000000 + Math.random() * 89999999));
      const r = await CampaignLeadsStore.createInboundCallLead(phone, getDefaultCampaignLine().id);
      if(!r.ok){
        if(typeof toast === "function") toast(r.error || "שגיאה", "", "err");
        return;
      }
      if(typeof toast === "function") toast("ליד בדיקה נוצר", phone);
      await this.refresh(false);
      this.selectLead(r.lead.id);
    }
  };

  const CampaignAgentLeadWatcher = {
    intervalMs: 60000,
    // GI-LEADNOTIFY 2026-08-02: טיק קל (probe בלבד) — זול מספיק ל-15 שניות.
    lightIntervalMs: 15000,
    timer: null,
    lightTimer: null,
    busy: false,
    lightBusy: false,
    _lastSeenMetaStamp: "",
    _watchdogInstalled: false,
    _realtimeChannel: null,

    startRealtime(){
      this.stopRealtime();
      if(!Auth.canAccessCampaignMyLeads()) return;
      try {
        const client = Storage.getClient();
        if(!client?.channel) return;
        const channelName = `gi-campaign-leads-${safeTrim(Auth.current?.id) || "agent"}-${APP_SESSION_ID.slice(-6)}`;
        this._realtimeChannel = client
          .channel(channelName)
          .on("postgres_changes", {
            event: "INSERT",
            schema: "public",
            table: SUPABASE_TABLES.campaignLeads
          }, (payload) => {
            try { CampaignLeadAssignInbox.handleRealtimeDbRow(payload?.new); } catch(_e) {}
          })
          .on("postgres_changes", {
            event: "UPDATE",
            schema: "public",
            table: SUPABASE_TABLES.campaignLeads
          }, (payload) => {
            const row = payload?.new;
            if(!row || !safeTrim(row.assigned_agent_id)) return;
            const oldAgentId = safeTrim(payload?.old?.assigned_agent_id);
            const newAgentId = safeTrim(row.assigned_agent_id);
            const localLead = CampaignLeadsStore.leads.find((l) => String(l.id) === String(row.id));
            const prevAgentId = oldAgentId || safeTrim(localLead?.assignedAgentId);
            if(prevAgentId === newAgentId) return;
            try { CampaignLeadAssignInbox.handleRealtimeDbRow(row, { prevAgentId }); } catch(_e) {}
          })
          .on("postgres_changes", {
            event: "UPDATE",
            schema: "public",
            table: SUPABASE_TABLES.meta,
            filter: "key=eq.global"
          }, (payload) => {
            try {
              const row = payload?.new;
              if(!row || safeTrim(row.key) !== "global") return;
              applyRemoteMetaInboxScopes(Storage.mapMeta(row));
            } catch(_e) {}
          })
          .subscribe((status) => {
            // GI-LEADNOTIFY 2026-08-02: קודם קראנו ל-subscribe() בלי callback.
            // כשהערוץ נפל (רשת, שינה של הלפטופ, מעבר סלולר↔wifi) הוא מת בשקט
            // והנציג נשאר תלוי בפולינג של 60 שניות — זה מקור הדילאי.
            if(status === "SUBSCRIBED"){
              this._realtimeRetry = 0;
              // ייתכן שהוחמצו אירועים בזמן הניתוק — משלימים מיד
              void this.tick();
              return;
            }
            if(status === "CHANNEL_ERROR" || status === "TIMED_OUT" || status === "CLOSED"){
              this.scheduleRealtimeReconnect();
            }
          });
      } catch(err) {
        console.warn("CAMPAIGN_LEAD_REALTIME_FAILED:", err);
        this.scheduleRealtimeReconnect();
      }
    },

    /** GI-LEADNOTIFY 2026-08-02: חיבור מחדש עם השהיה מתגברת (2s → 30s). */
    _realtimeRetry: 0,
    _realtimeRetryTimer: null,
    scheduleRealtimeReconnect(){
      if(this._realtimeRetryTimer) return;
      if(!Auth.canAccessCampaignMyLeads()) return;
      const attempt = Math.min(this._realtimeRetry++, 4);
      const delay = Math.min(2000 * Math.pow(2, attempt), 30000);
      this._realtimeRetryTimer = window.setTimeout(() => {
        this._realtimeRetryTimer = null;
        if(!Auth.canAccessCampaignMyLeads()) return;
        this.startRealtime();
      }, delay);
    },

    /** GI-LEADNOTIFY 2026-08-02: חזרה לרשת / לטאב — בודקים שהערוץ חי ומשלימים פערים. */
    installRealtimeWatchdog(){
      if(this._watchdogInstalled) return;
      this._watchdogInstalled = true;
      const revive = () => {
        if(!Auth.canAccessCampaignMyLeads()) return;
        if(!this._realtimeChannel) this.startRealtime();
        void this.tick();
      };
      try {
        window.addEventListener("online", revive);
        window.addEventListener("focus", revive);
        document.addEventListener("visibilitychange", () => {
          if(!document.hidden) revive();
        });
      } catch(_e) {}
    },

    stopRealtime(){
      // GI-LEADNOTIFY 2026-08-02: מבטלים גם ניסיון חיבור מחדש ממתין,
      // אחרת אחרי התנתקות משתמש נפתח ערוץ יתום.
      if(this._realtimeRetryTimer){
        window.clearTimeout(this._realtimeRetryTimer);
        this._realtimeRetryTimer = null;
      }
      if(!this._realtimeChannel) return;
      try { Storage.getClient()?.removeChannel(this._realtimeChannel); } catch(_e) {}
      this._realtimeChannel = null;
    },

    start(){
      this.stop();
      if(!Auth.canAccessCampaignMyLeads()) return;
      try { void DesktopNotifications.ensurePermission(); } catch(_e) {}
      this._realtimeRetry = 0;
      this.startRealtime();
      this.installRealtimeWatchdog();
      this.timer = window.setInterval(() => { void this.tick(); }, this.intervalMs);
      // GI-LEADNOTIFY 2026-08-02: טיק קל כל 15 שניות. הוא לא מוריד את שורת ה-meta
      // הכבדה (~3MB) אלא רק בודק updated_at (כמה בתים), ולכן אפשר להריץ אותו
      // בתדירות גבוהה בלי להכביד. זה מקצר את חלון ההמתנה כשה-Realtime מפספס.
      this.lightTimer = window.setInterval(() => { void this.lightTick(); }, this.lightIntervalMs);
      void this.tick();
    },

    stop(){
      this.stopRealtime();
      if(this.timer){
        window.clearInterval(this.timer);
        this.timer = null;
      }
      if(this.lightTimer){
        window.clearInterval(this.lightTimer);
        this.lightTimer = null;
      }
    },

    /**
     * GI-LEADNOTIFY 2026-08-02 — טיק קל.
     * שאילתת updated_at בלבד. אם החותמת לא זזה — אין מה לעשות, עלות אפסית.
     * אם היא זזה — מריצים טיק מלא. בנוסף, מנקזים תור התראות שכבר קיים
     * מקומית גם בלי גישה לרשת, כדי שהתראה שנתקעה לא תמתין לסבב הכבד.
     */
    async lightTick(){
      if(this.busy || this.lightBusy) return;
      if(!Auth.canAccessCampaignMyLeads()) return;
      this.lightBusy = true;
      try {
        try { await CampaignLeadAssignInbox.flushForCurrentUser(); } catch(_e) {}
        const probe = await Storage.probeMetaUpdatedAt();
        if(!probe?.ok) return;
        const stamp = safeTrim(probe.updatedAt);
        if(!stamp) return;
        if(stamp === this._lastSeenMetaStamp) return;
        this._lastSeenMetaStamp = stamp;
        await this.tick();
      } catch(_e) {
      } finally {
        this.lightBusy = false;
      }
    },

    async tick(){
      if(this.busy || !Auth.canAccessCampaignMyLeads()) return;
      // GI-LEADNOTIFY 2026-08-02: קודם יצאנו כאן לגמרי, וכל התראה ממתינה נדחתה
      // בסבב שלם (60 שניות) בכל פעם שרץ סנכרון כבד או תהליך חוסם.
      // עכשיו מדלגים רק על החלק היקר (רשת), אבל עדיין מנקזים את התור המקומי.
      if(LiveRefresh?.hasBlockingFlow?.() || HeavySyncGate.isBusy()){
        try { await CampaignLeadAssignInbox.flushForCurrentUser(); } catch(_e) {}
        return;
      }
      this.busy = true;
      try {
        const metaRes = await Storage.loadMetaRowCached();
        if(metaRes?.ok){
          const remoteMeta = Storage.mapMeta(metaRes.data || {});
          try { applyRemoteMetaInboxScopes(remoteMeta); } catch(_e) {}
        }
        // קודם טוענים לידים — ואז מנקים/מתריעים (בלי התראה ריקה)
        const r = await CampaignLeadsStore.fetchAll({ scope: "mine" });
        if(r.ok){
          try { CampaignMyLeadsUI.renderList(); } catch(_e) {}
        }
        await CampaignLeadAssignInbox.flushForCurrentUser();
      } finally {
        this.busy = false;
      }
    }
  };

  function showLeadTransferAnimation(agentName, options = {}){
    const fast = options.fast === true;
    const sendMs = fast ? 350 : 1500;
    const doneMs = fast ? 450 : 1200;
    const outMs = fast ? 180 : 450;
    return new Promise((resolve) => {
      const overlay = document.createElement("div");
      overlay.className = "lcTransferOverlay";
      overlay.innerHTML = `
        <div class="lcTransferOverlay__card">
          <div class="lcTransferOverlay__icon lcTransferOverlay__icon--sending" id="lcTransferIcon">➤</div>
          <div class="lcTransferOverlay__title" id="lcTransferTitle">מעביר ליד ל</div>
          <div class="lcTransferOverlay__agent" id="lcTransferAgent">${escapeHtml(agentName)}</div>
          <div class="lcTransferOverlay__sub" id="lcTransferSub">אנא המתן...</div>
        </div>`;
      document.body.appendChild(overlay);

      setTimeout(() => {
        const icon = document.getElementById("lcTransferIcon");
        const title = document.getElementById("lcTransferTitle");
        const sub = document.getElementById("lcTransferSub");
        if(icon){
          icon.className = "lcTransferOverlay__icon lcTransferOverlay__icon--done";
          icon.textContent = "✓";
        }
        if(title) title.textContent = "עבר בהצלחה!";
        if(sub) sub.textContent = "הליד שויך ל" + agentName;

        setTimeout(() => {
          overlay.classList.add("lcTransferOverlay--out");
          setTimeout(() => {
            overlay.remove();
            resolve();
          }, outMs);
        }, doneMs);
      }, sendMs);
    });
  }

  const TrackingReportUI = {
    els: {},
    filter: "all",
    search: "",
    monthFilter: "",    // YYYY-MM; empty = current month
    agentFilter: "",   // agent name; empty = all agents

    _currentMonthIL(){
      return currentCampaignLeadMonthIL();
    },

    _activeMonthIL(){
      return this.monthFilter || this._currentMonthIL();
    },

    _leadsForMonth(list, monthStr){
      const target = safeTrim(monthStr);
      if(!target || target === "ALL") return list || [];
      return (list || []).filter((l) => campaignLeadMatchesMonthIL(l, target));
    },

    _getAgentName(lead, agents){
      return campaignLeadAgentsDisplay(lead, agents);
    },

    _buildAgentChips(monthScopedLeads){
      const agentSelectEl = document.getElementById("trackingAgentSelect");
      const agentFilterEl = document.getElementById("trackingAgentFilter");
      if(!agentSelectEl) return;
      const agents = Array.isArray(State.data?.agents) ? State.data.agents : [];
      // רק נציגים שמופיעים בפועל על לידים בתקופה — לא כל משתמשי המערכת
      const namesSet = new Set();
      // GI-ELDERLY-LEAD: המבוגרים אינם נציג — נספרים בנפרד ולא נכנסים לרשימת השמות.
      let elderlyCount = 0;
      (monthScopedLeads || []).forEach((l) => {
        if(isGoldMirrorCampaignLead(l)) return;
        if(isElderlyCampaignLead(l)){
          if(elderlyLeadVisibleToSession(l)) elderlyCount += 1;
          return;
        }
        campaignLeadAllAgentNames(l, agents).forEach((n) => {
          if(n && n !== "—") namesSet.add(n);
        });
      });
      const names = Array.from(namesSet).sort((a,b) => a.localeCompare(b, "he"));
      if(agentFilterEl) agentFilterEl.style.display = "";

      const prev = safeTrim(this.agentFilter);
      // מאפסים רק נציג ספציפי שנעלם מהתקופה — לא את בחירת "הכל" ולא את דלי המבוגרים
      if(prev && prev !== "__ALL__" && prev !== ELDERLY_LEAD_AGENT_ID && !names.includes(prev)) this.agentFilter = "";
      if(prev === ELDERLY_LEAD_AGENT_ID && !elderlyCount) this.agentFilter = "";

      const cur = safeTrim(this.agentFilter);
      const elderlyOpt = elderlyCount
        ? `<option value="${escapeHtml(ELDERLY_LEAD_AGENT_ID)}"${cur === ELDERLY_LEAD_AGENT_ID ? " selected" : ""}>${escapeHtml(ELDERLY_LEAD_AGENT_NAME)} (${elderlyCount})</option>`
        : "";
      agentSelectEl.innerHTML =
        `<option value="">— בחר נציג —</option>` +
        `<option value="__ALL__"${cur === "__ALL__" ? " selected" : ""}>הכל</option>` +
        elderlyOpt +
        names.map((n) =>
          `<option value="${escapeHtml(n)}"${n === cur ? " selected" : ""}>${escapeHtml(n)}</option>`
        ).join("");
      // שומרים את הערך ב-DOM אחרי rebuild (חשוב ל-__ALL__)
      agentSelectEl.value = cur || "";
    },

    _isAgentFilterActive(){
      return !!safeTrim(this.agentFilter);
    },

    _wantsAllAgents(){
      return safeTrim(this.agentFilter) === "__ALL__";
    },

    _selectedAgentName(){
      const v = safeTrim(this.agentFilter);
      if(!v || v === "__ALL__" || v === ELDERLY_LEAD_AGENT_ID) return "";
      return v;
    },

    // GI-ELDERLY-LEAD
    _wantsElderly(){
      return safeTrim(this.agentFilter) === ELDERLY_LEAD_AGENT_ID;
    },

    _renderAgentCard(agentLeads){
      // Legacy card kept hidden — stats rendered in slim bar (_renderStatsBar)
      const card = document.getElementById("trackingAgentCard");
      if(card){
        card.style.display = "none";
        card.hidden = true;
      }
    },

    _renderStatsBar(baseLeads, rowsCount, dateLabel){
      const bar = document.getElementById("trackingStatsBar");
      if(!bar) return;
      if(!this._isAgentFilterActive()){
        bar.hidden = true;
        bar.innerHTML = "";
        return;
      }
      const statuses = [
        { key:"new", label:"חדש", tone:"new" },
        { key:"in_progress", label:"בטיפול", tone:"progress" },
        { key:"no_answer", label:"אין מענה", tone:"noanswer" },
        { key:"agent_appointment", label:"מינוי סוכן", tone:"appt" },
        { key:"closed", label:"נסגר", tone:"closed" },
        { key:"irrelevant", label:"לא רלוונטי", tone:"irr" }
      ];
      const pills = statuses.map((s) => {
        const n = (baseLeads || []).filter((l) => l.status === s.key).length;
        return `<span class="lcTrackStatPill lcTrackStatPill--${s.tone}"><strong>${n}</strong> ${s.label}</span>`;
      }).join("");
      bar.innerHTML =
        `<span class="lcTrackScreen__statsTotal">${escapeHtml(dateLabel)} · סה״כ <strong>${(baseLeads || []).length}</strong> לידים · מוצגים: <strong>${rowsCount}</strong></span>` +
        `<span class="lcTrackScreen__statsPills">${pills}</span>`;
      bar.hidden = false;
    },

    init(){
      this.els.tbody = document.getElementById("trackingTbody");
      this.els.search = document.getElementById("trackingSearch");
      this.els.filters = document.getElementById("trackingFilters");
      this.els.summary = document.getElementById("trackingSummary");
      this.els.btnRefresh = document.getElementById("btnTrackingRefresh");
      this.els.dateFilter = document.getElementById("trackingDateFilter");
      this.els.btnDateToday = document.getElementById("btnTrackingDateToday");
      this.els.btnDateAll = document.getElementById("btnTrackingDateAll");

      if(this.els.search) on(this.els.search, "input", perfDebounce(() => {
        this.search = safeTrim(this.els.search.value);
        this.renderList();
      }, 200));

      if(this.els.filters) on(this.els.filters, "click", (ev) => {
        const chip = ev.target.closest("[data-track-filter]");
        if(!chip) return;
        this.filter = chip.getAttribute("data-track-filter") || "all";
        this.els.filters.querySelectorAll(".mcSearch__chip").forEach((c) => c.classList.toggle("is-active", c === chip));
        this.renderList();
      });

      // Agent select — בחירת נציג במקום צ'יפים של כל המערכת
      const agentSelectEl = document.getElementById("trackingAgentSelect");
      if(agentSelectEl) on(agentSelectEl, "change", () => {
        this.agentFilter = safeTrim(agentSelectEl.value);
        this.renderList();
      });

      // Month filter — לא מאפסים בחירת נציג (כולל "הכל")
      if(this.els.dateFilter) on(this.els.dateFilter, "change", (e) => {
        this.monthFilter = safeTrim(e.target.value);
        this.renderList();
      });
      if(this.els.btnDateToday) on(this.els.btnDateToday, "click", () => {
        this.monthFilter = "";
        if(this.els.dateFilter) this.els.dateFilter.value = this._currentMonthIL();
        this.renderList();
      });
      if(this.els.btnDateAll) on(this.els.btnDateAll, "click", () => {
        this.monthFilter = "ALL";
        if(this.els.dateFilter) this.els.dateFilter.value = "";
        this.renderList();
      });

      if(this.els.btnRefresh) on(this.els.btnRefresh, "click", () => this.refresh());

      if(this.els.tbody) on(this.els.tbody, "click", (ev) => {
        const reassignBtn = ev.target.closest("[data-cl-reassign-id]");
        if(reassignBtn){
          ev.stopPropagation();
          handleCampaignLeadReassignBtn(reassignBtn);
          return;
        }
        const noteBtn = ev.target.closest("[data-cl-note-id]");
        if(noteBtn){
          ev.stopPropagation();
          handleCampaignLeadAgentNoteBtn(noteBtn);
        }
      });
    },

    getFilteredLeads(){
      const monthStr = this.monthFilter === "ALL" ? "ALL" : this._activeMonthIL();
      let list = this._leadsForMonth(CampaignLeadsStore.leads || [], monthStr)
        .filter((l) => !isGoldMirrorCampaignLead(l));
      // בלי בחירת נציג — לא מציגים את כל רשומות המערכת
      if(!this._isAgentFilterActive()) return [];
      const agents = Array.isArray(State.data?.agents) ? State.data.agents : [];
      // GI-ELDERLY-LEAD: הדלי הוא בחירה נפרדת. בכל בחירה אחרת (כולל "הכל")
      // המבוגרים מוסתרים, כדי שלא יזלגו לרשימות של נציגים אמיתיים.
      if(this._wantsElderly()){
        list = list.filter((l) => elderlyLeadVisibleToSession(l));
      } else {
        list = list.filter((l) => !isElderlyCampaignLead(l));
      }
      const agentName = this._selectedAgentName();
      if(agentName){
        list = list.filter((l) => campaignLeadMatchesAgentFilter(l, agentName, agents));
      }
      // Step 3: status filter
      if(this.filter === "closed") list = list.filter((l) => l.status === "closed");
      else if(this.filter === "irrelevant") list = list.filter((l) => l.status === "irrelevant");
      else if(this.filter === "no_answer") list = list.filter((l) => l.status === "no_answer");
      else if(this.filter === "agent_appointment") list = list.filter((l) => l.status === "agent_appointment");
      else if(this.filter === "in_progress") list = list.filter((l) => l.status === "in_progress");
      // Step 4: text search
      if(this.search){
        const q = this.search.toLowerCase();
        list = list.filter((l) => {
          const name = (l.customerName || "").toLowerCase();
          const phone = (l.phone || "").replace(/[-\s]/g, "");
          const idNum = (l.idNumber || "");
          const insCo = (l.insuranceCompany || "").toLowerCase();
          return name.includes(q) || phone.includes(q) || idNum.includes(q) || insCo.includes(q);
        });
      }
      return list;
    },

    renderList(){
      if(!this.els.tbody) return;
      const monthStr = this.monthFilter === "ALL" ? "ALL" : this._activeMonthIL();
      const monthScopedLeads = this._leadsForMonth(CampaignLeadsStore.leads || [], monthStr)
        .filter((l) => !isGoldMirrorCampaignLead(l));
      const agents = Array.isArray(State.data?.agents) ? State.data.agents : [];
      const selectedAgent = this._selectedAgentName();
      const agentScopedLeads = selectedAgent
        ? monthScopedLeads.filter((l) => campaignLeadMatchesAgentFilter(l, selectedAgent, agents))
        : [];
      const rows = this.getFilteredLeads();
      const base = this._isAgentFilterActive()
        ? (selectedAgent ? agentScopedLeads : monthScopedLeads)
        : [];
      const dateLabel = formatCampaignLeadMonthLabel(monthStr);
      if(this.els.summary){
        this.els.summary.hidden = true;
        this.els.summary.textContent = "";
      }

      // Build agent select from date-scoped leads
      this._buildAgentChips(monthScopedLeads);

      // Agent card (hidden) + slim stats bar
      this._renderAgentCard(agentScopedLeads);
      this._renderStatsBar(base, rows.length, dateLabel);

      if(!this._isAgentFilterActive()){
        this.els.tbody.innerHTML = '<tr><td colspan="11" class="muted">בחר נציג כדי להציג את הלידים</td></tr>';
        return;
      }

      if(!rows.length){
        this.els.tbody.innerHTML = '<tr><td colspan="11" class="muted">אין לידים בסינון הנוכחי</td></tr>';
        return;
      }

      this.els.tbody.innerHTML = rows.map((lead) => {
        const timeRaw = safeTrim(lead.createdAt);
        let time = "";
        try {
          const d = new Date(timeRaw);
          if(!isNaN(d.getTime())){
            time = d.toLocaleString("he-IL", { timeZone:"Asia/Jerusalem", day:"2-digit", month:"2-digit", year:"numeric", hour:"2-digit", minute:"2-digit" });
          }
        } catch(_e){ time = timeRaw.slice(0,16).replace("T"," "); }
        const lastModRaw = safeTrim(lead.lastModifiedAt || lead.updatedAt);
        let lastMod = "";
        try {
          const dm = new Date(lastModRaw);
          if(!isNaN(dm.getTime())){
            lastMod = dm.toLocaleString("he-IL", { timeZone:"Asia/Jerusalem", day:"2-digit", month:"2-digit", year:"numeric", hour:"2-digit", minute:"2-digit" });
          }
        } catch(_e){ lastMod = lastModRaw ? lastModRaw.slice(0,16).replace("T"," ") : ""; }
        const agentName = this._getAgentName(lead, agents);
        const leadName = safeTrim(lead.customerName) || "—";
        const statusKey = safeTrim(lead.status);
        const statusTone = campaignLeadStatusTone(statusKey);
        const rowClass = campaignLeadRowStatusClass(statusKey);
        let statusExtra = "";
        if(statusKey === "closed" && safeTrim(lead.closedAt)){
          try {
            const dc = new Date(lead.closedAt);
            if(!isNaN(dc.getTime())){
              statusExtra = ' <span class="lcTrackBadge__sub">(' + escapeHtml(dc.toLocaleDateString("he-IL", { timeZone:"Asia/Jerusalem", day:"2-digit", month:"2-digit", year:"numeric" })) + ')</span>';
            }
          } catch(_e){}
        }
        statusExtra += campaignLeadAgentNoteBtnHtml(lead);
        const desc = safeTrim(lead.descriptionDisplay || lead.description || "").slice(0, 40);
        return `<tr class="lcTrackRow ${rowClass}" data-cl-track-status="${escapeHtml(statusKey)}">
          <td><span class="lcTrackRow__name">${escapeHtml(leadName)}</span>${campaignLeadGoldBadgeHtml(lead)}</td>
          <td dir="ltr"><span class="lcTrackRow__phone">${escapeHtml(lead.phone || "—")}</span></td>
          <td dir="ltr">${escapeHtml(lead.idNumber || "—")}</td>
          <td class="lcCampaign__agentCell">${escapeHtml(agentName)}</td>
          <td>${escapeHtml(lead.campaignLabel || "—")}</td>
          <td>${escapeHtml(safeTrim(lead.insuranceCompany) || "—")}</td>
          <td>${escapeHtml(desc) || "—"}</td>
          <td><span class="lcTrackBadge lcTrackBadge--${statusTone}">${escapeHtml(campaignLeadStatusLabel(statusKey))}${statusExtra}</span></td>
          <td>${escapeHtml(time)}</td>
          <td>${escapeHtml(lastMod)}</td>
          <td class="lcCampaign__actions">${campaignLeadReassignBtnHtml(lead.id)}</td>
        </tr>`;
      }).join("");
    },

    async refresh(){
      await CampaignLeadsStore.fetchAll({ scope: "all" });
      this.renderList();
      if(typeof toast === "function") toast("דו\"ח מעקב עודכן");
    },

    render(){
      if(!this.monthFilter){
        this.monthFilter = "";
        if(this.els.dateFilter) this.els.dateFilter.value = this._currentMonthIL();
      }
      this.renderList();
    }
  };

  function giCopyToast(title, text, variant){
    try {
      window.showToast?.({ title, text: text || "", variant: variant || "ok", durationMs: 2800 });
    } catch(_e){}
  }

  function giResolveCopyText(el){
    if(!el) return "";
    const attr = el.getAttribute("data-copy-text");
    if(attr != null && safeTrim(attr) !== "") return safeTrim(attr);
    const valSpan = el.querySelector(".lcLeadDetails__value");
    if(valSpan) return safeTrim(valSpan.textContent);
    return safeTrim(el.textContent);
  }

  /** סנכרוני — שומר user-gesture אחרי דאבל-קליק (clipboard.async נכשל לעיתים) */
  function giCopyToClipboard(text, label){
    const val = safeTrim(text);
    if(!val || val === "—"){
      giCopyToast("אין ערך להעתקה", "", "warn");
      return false;
    }
    let ok = false;
    try {
      const ta = document.createElement("textarea");
      ta.value = val;
      ta.setAttribute("readonly", "");
      ta.style.cssText = "position:fixed;left:-9999px;top:0;opacity:0";
      document.body.appendChild(ta);
      ta.focus();
      ta.select();
      ok = document.execCommand("copy");
      ta.remove();
    } catch(_e){ ok = false; }
    if(ok){
      giCopyToast("הועתק ללוח", label || val.slice(0, 60), "ok");
      return true;
    }
    if(navigator.clipboard?.writeText){
      navigator.clipboard.writeText(val).then(() => {
        giCopyToast("הועתק ללוח", label || "", "ok");
      }).catch(() => giCopyToast("לא ניתן להעתיק", "", "err"));
      return true;
    }
    giCopyToast("לא ניתן להעתיק", "", "err");
    return false;
  }

  function campaignMyLeadFieldCopyValue(lead, field){
    if(!lead || !field) return "";
    if(field === "description") return safeTrim(lead.descriptionDisplay || stripCampaignLeadPayloadMarker(lead.description));
    if(field === "status") return campaignLeadStatusLabel(lead.status);
    return safeTrim(lead[field]);
  }

  const MY_LEAD_ICON_DETAILS = '<svg class="lcMyLeadIconBtn__icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M14 3H7a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h10a2 2 0 0 0 2-2V8Z"/><path d="M14 3v5h5"/><path d="M9 13h6"/><path d="M9 17h4"/></svg>';
  const MY_LEAD_ICON_CALL_NOTE = '<svg class="lcMyLeadIconBtn__icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M22 16.92v3a2 2 0 0 1-2.18 2 19.79 19.79 0 0 1-8.63-3.07 19.5 19.5 0 0 1-6-6 19.79 19.79 0 0 1-3.07-8.67A2 2 0 0 1 4.11 2h3a2 2 0 0 1 2 1.72c.13.96.36 1.9.7 2.81a2 2 0 0 1-.45 2.11L8.09 9.91a16 16 0 0 0 6 6l1.27-1.27a2 2 0 0 1 2.11-.45c.91.34 1.85.57 2.81.7A2 2 0 0 1 22 16.92z"/><path d="M15 3h6v6"/><path d="M21 3l-9 9"/></svg>';
  const MY_LEAD_ICON_COLOR = '<svg class="lcMyLeadIconBtn__icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M12 22a10 10 0 0 0 10-10c0-5-4-8-8-8a6 6 0 0 0-6 6c0 3 2 4 2 6a2 2 0 0 0 2 2Z"/><circle cx="13.5" cy="7.5" r="1.1" fill="currentColor" stroke="none"/><circle cx="17.2" cy="10.2" r="1.1" fill="currentColor" stroke="none"/><circle cx="9.2" cy="9.8" r="1.1" fill="currentColor" stroke="none"/></svg>';
  const MY_LEAD_ICON_REMINDER = '<svg class="lcMyLeadIconBtn__icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M6 8a6 6 0 0 1 12 0c0 7 3 9 3 9H3s3-2 3-9"/><path d="M10.3 21a1.94 1.94 0 0 0 3.4 0"/></svg>';

  const CampaignMyLeadsUI = {
    els: {},
    search: "",
    pendingHighlightId: null,
    dayFilter: "",      // YYYY-MM-DD; empty = today; "ALL" = all time
    statusFilter: "all",
    _midnightTimer: null,

    _currentDayIL(){
      return currentCampaignLeadDateIL();
    },

    _activeDayIL(){
      return this.dayFilter || this._currentDayIL();
    },

    _leadsForDay(list, dayStr){
      const target = safeTrim(dayStr);
      if(!target || target === "ALL") return list || [];
      // לידים שהתקבלו/נוצרו באותו יום (שעון ישראל) — לא לפי סגירה/עדכון
      return (list || []).filter((l) => parseCampaignLeadStampDateIL(l?.createdAt) === target);
    },

    _syncDayInput(){
      if(this.dayFilter === "ALL"){
        if(this.els.dateFilter) this.els.dateFilter.value = "";
        return;
      }
      const val = this._activeDayIL();
      if(this.els.dateFilter) this.els.dateFilter.value = val;
    },

    setDayFilter(val){
      this.dayFilter = val || "";
      this._syncDayInput();
      this.renderList();
    },

    scheduleMidnightReset(){
      if(this._midnightTimer) clearTimeout(this._midnightTimer);
      const ilNow = new Date(new Date().toLocaleString("en-US", { timeZone: "Asia/Jerusalem" }));
      const ilMidnight = new Date(ilNow);
      ilMidnight.setHours(24, 0, 0, 0);
      const ms = Math.max(1000, ilMidnight - ilNow);
      this._midnightTimer = setTimeout(() => {
        this.dayFilter = "";
        this._syncDayInput();
        this.renderList();
        this.scheduleMidnightReset();
      }, ms);
    },

    init(){
      this.els.tbody = document.getElementById("campaignMyLeadsTbody");
      this.els.badge = document.getElementById("campaignMyLeadsCountBadge");
      this.els.alert = document.getElementById("campaignMyLeadsTableAlert");
      this.els.search = document.getElementById("campaignMyLeadsSearch");
      this.els.btnRefresh = document.getElementById("btnCampaignMyLeadsRefresh");
      this.els.dateFilter = document.getElementById("myLeadsDateFilter");
      this.els.btnDateToday = document.getElementById("btnMyLeadsDateToday");
      this.els.btnDateAll = document.getElementById("btnMyLeadsDateAll");
      this.els.statusFilters = document.getElementById("myLeadsStatusFilters");

      // Day picker
      if(this.els.dateFilter) on(this.els.dateFilter, "change", (e) => {
        this.dayFilter = safeTrim(e.target.value);
        this.renderList();
      });
      if(this.els.btnDateToday) on(this.els.btnDateToday, "click", () => this.setDayFilter(""));
      if(this.els.btnDateAll) on(this.els.btnDateAll, "click", () => {
        this.dayFilter = "ALL";
        if(this.els.dateFilter) this.els.dateFilter.value = "";
        this.renderList();
      });

      // Status filter chips
      if(this.els.statusFilters) on(this.els.statusFilters, "click", (ev) => {
        const chip = ev.target.closest("[data-my-status-filter]");
        if(!chip) return;
        this.statusFilter = chip.getAttribute("data-my-status-filter") || "all";
        this.els.statusFilters.querySelectorAll(".mcSearch__chip").forEach((c) => c.classList.toggle("is-active", c === chip));
        this.renderList();
      });

      if(this.els.search) on(this.els.search, "input", () => {
        this.search = safeTrim(this.els.search.value).toLowerCase();
        this.renderList();
      });
      if(this.els.btnRefresh) on(this.els.btnRefresh, "click", () => void this.refresh(true));
      if(this.els.tbody) on(this.els.tbody, "dblclick", (ev) => {
        if(ev.target.closest("button")) return;
        const cell = ev.target.closest("[data-copy-field]");
        if(!cell) return;
        const row = cell.closest("tr[data-cl-my-id]");
        if(!row) return;
        ev.preventDefault();
        ev.stopPropagation();
        const id = row.getAttribute("data-cl-my-id");
        const lead = CampaignLeadsStore.leads.find((l) => String(l.id) === String(id));
        if(!lead) return;
        const field = cell.getAttribute("data-copy-field");
        const label = cell.getAttribute("data-copy-label") || field;
        giCopyToClipboard(campaignMyLeadFieldCopyValue(lead, field), label);
      });
      if(this.els.tbody) on(this.els.tbody, "click", (ev) => {
        const noteBtn = ev.target.closest("[data-cl-note-id]");
        if(noteBtn){
          ev.stopPropagation();
          handleCampaignLeadAgentNoteBtn(noteBtn);
          return;
        }
        const callNoteBtn = ev.target.closest("[data-cl-call-note-id]");
        if(callNoteBtn){
          ev.stopPropagation();
          const id = callNoteBtn.getAttribute("data-cl-call-note-id");
          const lead = CampaignLeadsStore.leads.find((l) => String(l.id) === String(id));
          if(lead) CampaignCallNoteModal.open(lead);
          return;
        }
        const continueBtn = ev.target.closest("[data-cl-continue-proposal]");
        if(continueBtn){
          const id = continueBtn.getAttribute("data-cl-id");
          const lead = CampaignLeadsStore.leads.find((l) => String(l.id) === String(id));
          if(lead) Wizard.openHealthWizardFromCampaignLead(lead);
          return;
        }
        const colorBtn = ev.target.closest("[data-cl-color-id]");
        if(colorBtn){
          ev.stopPropagation();
          const id = colorBtn.getAttribute("data-cl-color-id");
          const lead = CampaignLeadsStore.leads.find((l) => String(l.id) === String(id));
          if(lead) CampaignLeadColorPicker.open(lead, colorBtn);
          return;
        }
        const openBtn = ev.target.closest("[data-cl-open-id]");
        if(openBtn){
          ev.stopPropagation();
          const id = openBtn.getAttribute("data-cl-open-id");
          const lead = CampaignLeadsStore.leads.find((l) => String(l.id) === String(id));
          if(lead) LeadDetailsModal.open(lead);
          return;
        }
        const reminderBtn = ev.target.closest("[data-cl-reminder-id]");
        if(reminderBtn){
          ev.stopPropagation();
          const id = reminderBtn.getAttribute("data-cl-reminder-id");
          const lead = CampaignLeadsStore.leads.find((l) => String(l.id) === String(id));
          if(lead) try { ReminderUI.openForLead(lead); } catch(_e) {}
          return;
        }
      });
      if(this.els.tbody) on(this.els.tbody, "change", (ev) => {
        const sel = ev.target.closest("[data-cl-my-status-select]");
        if(!sel) return;
        const id = sel.getAttribute("data-cl-status-id");
        const status = safeTrim(sel.value);
        if(!status) return;
        void this.updateStatus(id, status, sel);
      });
    },

    myAgentKey(){
      const rec = getCurrentAgentRecord();
      return { id: safeTrim(rec?.id || Auth?.current?.id), name: safeTrim(rec?.name || Auth?.current?.name) };
    },

    myLeads(){
      const me = getCurrentAgentRecord() || Auth?.current || {};
      return (CampaignLeadsStore.leads || []).filter((l) => campaignLeadAgentAccess(l, me));
    },

    showAlert(msg, tone = "warn"){
      if(!this.els.alert) return;
      if(!msg){ this.els.alert.hidden = true; return; }
      this.els.alert.hidden = false;
      this.els.alert.textContent = msg;
      this.els.alert.className = "lcCampaign__alert lcCampaign__alert--" + (tone === "err" ? "err" : "ok");
    },

    filtered(){
      const q = this.search;
      const dayStr = this.dayFilter === "ALL" ? "ALL" : this._activeDayIL();
      let list = this._leadsForDay(this.myLeads(), dayStr);
      // Status filter
      if(this.statusFilter && this.statusFilter !== "all"){
        list = list.filter((l) => l.status === this.statusFilter);
      }
      // Text search
      if(q) list = list.filter((l) => {
        const blob = [l.phone, l.customerName, l.description, l.campaignLabel, l.insuranceCompany].join(" ").toLowerCase();
        return blob.includes(q);
      });
      return list;
    },

    renderMyLeadStatusSelect(lead){
      const current = safeTrim(lead.status);
      const isAgentStatus = CAMPAIGN_LEAD_AGENT_SELECT_STATUSES.some((s) => s.value === current);
      const options = CAMPAIGN_LEAD_AGENT_SELECT_STATUSES.map((s) =>
        `<option value="${escapeHtml(s.value)}"${current === s.value ? " selected" : ""}>${escapeHtml(s.label)}</option>`
      ).join("");
      const placeholder = `<option value="" disabled${!isAgentStatus ? " selected" : ""}>בחר סטטוס</option>`;
      return `<select class="input lcMyLeadStatusSelect" data-cl-my-status-select data-cl-status-id="${escapeHtml(lead.id)}" aria-label="סטטוס ליד">${placeholder}${options}</select>`;
    },

    renderList(){
      if(!this.els.tbody) return;
      const rows = this.filtered();
      if(this.els.badge) this.els.badge.textContent = rows.length + " לידים";
      if(!rows.length){
        const emptyMsg = this.dayFilter === "ALL"
          ? "אין לידים משויכים אליך"
          : "אין לידים לתאריך זה";
        this.els.tbody.innerHTML = `<tr><td colspan="10" class="muted">${emptyMsg}</td></tr>`;
        return;
      }
      this.els.tbody.innerHTML = rows.map((lead) => {
        const desc = safeTrim(lead.descriptionDisplay || stripCampaignLeadPayloadMarker(lead.description));
        const short = desc.length > 48 ? desc.slice(0, 48) + "…" : desc;
        const highlight = String(lead.id) === String(this.pendingHighlightId) ? " is-highlight" : "";
        const rowClass = campaignLeadRowStatusClass(lead.status);
        const statusTone = campaignLeadStatusTone(lead.status);
        const callNoteTitle = safeTrim(lead.callNote) ? "עריכת תיעוד שיחה" : "תיעוד שיחה";
        const isGold = isGoldMirrorCampaignLead(lead);
        const campaignCell = isGold
          ? `<span class="lcGoldLeadBadge" title="ליד זהב · שיקוף אלמנטרי">ליד זהב</span>`
          : escapeHtml(lead.campaignLabel);
        // צבע שורה ידני — מבטל את צבע הסטטוס אם הנציג בחר צבע
        const customColor = safeTrim(lead.rowColor);
        const rowStyle = customColor ? ` style="--lead-custom-color:${escapeHtml(customColor)}"` : "";
        const rowColorClass = customColor ? " lcLeadRow--custom-color" : "";
        const goldContinue = isGold && lead.status !== "closed"
          ? `<button class="btn btn--small btn--primary lcMyLeadProposeBtn" type="button" data-cl-continue-proposal="1" data-cl-id="${escapeHtml(lead.id)}" title="הקמת הצעה בריאות וסיכונים">הקמת הצעה</button>`
          : "";
        return `<tr data-cl-my-id="${escapeHtml(lead.id)}" class="${rowClass}${rowColorClass}${highlight}${isGold ? " lcLeadRow--gold" : ""}"${rowStyle}>
          <td class="lcMyLeadCopy" data-copy-field="customerName" data-copy-label="שם לקוח" title="דאבל-קליק להעתקה">${escapeHtml(lead.customerName || "—")}</td>
          <td class="lcMyLeadCopy" data-copy-field="idNumber" data-copy-label="תעודת זהות" dir="ltr" title="דאבל-קליק להעתקה">${escapeHtml(lead.idNumber || "—")}</td>
          <td class="lcMyLeadCopy" data-copy-field="birthDate" data-copy-label="תאריך לידה" dir="ltr" title="דאבל-קליק להעתקה">${escapeHtml(lead.birthDate || "—")}</td>
          <td class="lcMyLeadCopy" data-copy-field="idIssueDate" data-copy-label="תאריך הנפקת ת״ז" dir="ltr" title="דאבל-קליק להעתקה">${escapeHtml(lead.idIssueDate || "—")}</td>
          <td class="lcMyLeadCopy" data-copy-field="phone" data-copy-label="טלפון" dir="ltr" title="דאבל-קליק להעתקה">${escapeHtml(lead.phone)}</td>
          <td class="lcMyLeadCopy" data-copy-field="campaignLabel" data-copy-label="קמפיין" title="דאבל-קליק להעתקה">${campaignCell}</td>
          <td class="lcMyLeadCopy" data-copy-field="insuranceCompany" data-copy-label="חברת ביטוח" title="דאבל-קליק להעתקה">${escapeHtml(safeTrim(lead.insuranceCompany) || "—")}</td>
          <td class="lcMyLeadCopy" data-copy-field="description" data-copy-label="תיאור" title="דאבל-קליק להעתקה — ${escapeHtml(desc)}">${escapeHtml(short)}</td>
          <td class="lcMyLeadCopy" data-copy-field="status" data-copy-label="סטטוס" title="דאבל-קליק להעתקה"><span class="lcTrackBadge lcTrackBadge--${statusTone}">${escapeHtml(campaignLeadStatusLabel(lead.status))}</span></td>
          <td class="lcCampaign__actions lcMyLeadActions">
            ${goldContinue}
            <div class="lcMyLeadActions__tools" role="group" aria-label="פעולות ליד">
              <button class="lcMyLeadIconBtn" type="button" data-cl-open-id="${escapeHtml(lead.id)}" title="פרטי ליד" aria-label="פרטי ליד">${MY_LEAD_ICON_DETAILS}</button>
              <button class="lcMyLeadIconBtn" type="button" data-cl-call-note-id="${escapeHtml(lead.id)}" title="${escapeHtml(callNoteTitle)}" aria-label="${escapeHtml(callNoteTitle)}">${MY_LEAD_ICON_CALL_NOTE}</button>
              <button class="lcMyLeadIconBtn lcLeadColorBtn" type="button" data-cl-color-id="${escapeHtml(lead.id)}" title="צבע שורה" aria-label="בחר צבע לשורה">${MY_LEAD_ICON_COLOR}</button>
              <button class="lcMyLeadIconBtn" type="button" data-cl-reminder-id="${escapeHtml(lead.id)}" title="צור תזכורת" aria-label="צור תזכורת">${MY_LEAD_ICON_REMINDER}</button>
            </div>
            ${this.renderMyLeadStatusSelect(lead)}
          </td>
        </tr>`;
      }).join("");
      this.applyHighlight();
    },

    applyHighlight(){
      const id = safeTrim(this.pendingHighlightId);
      if(!id || !this.els.tbody) return;
      const row = this.els.tbody.querySelector(`[data-cl-my-id="${CSS.escape(id)}"]`);
      if(row){
        row.classList.add("is-highlight");
        try { row.scrollIntoView({ block: "nearest", behavior: "smooth" }); } catch(_e) {}
        window.setTimeout(() => {
          try { row.classList.remove("is-highlight"); } catch(_e) {}
        }, 8000);
      }
      this.pendingHighlightId = null;
    },

    async refresh(showToast){
      const r = await CampaignLeadsStore.fetchAll({ scope: "mine" });
      if(!r.ok) this.showAlert(r.error || "שגיאה בטעינה", "err");
      else this.showAlert("");
      this.renderList();
      if(showToast && typeof toast === "function" && r.ok) toast("עודכן");
    },

    async render(){
      if(!Auth.canAccessCampaignMyLeads()) return;
      if(!this.dayFilter && this.dayFilter !== "ALL"){
        this._syncDayInput();
      }
      this.scheduleMidnightReset();
      await this.refresh(false);
      this.applyHighlight();
    },

    async updateStatus(id, status, selectEl){
      const lead = CampaignLeadsStore.leads.find((l) => String(l.id) === String(id));
      if(!lead) return;
      const nextStatus = safeTrim(status);
      if(!nextStatus || nextStatus === safeTrim(lead.status)) return;
      const stamp = nowISO();
      const abortSelect = () => {
        try { void this.renderList(); } catch(_e) {}
      };

      if(nextStatus === "irrelevant"){
        CampaignIrrelevantModal.open(lead, { onAbort: abortSelect });
        return;
      }

      if(nextStatus === "closed"){
        CampaignClosedLeadFlow.start(lead, { onAbort: abortSelect });
        return;
      }

      const save = await CampaignLeadsStore.upsert({
        ...lead,
        status: nextStatus,
        lastModifiedAt: stamp,
        updatedAt: stamp
      });
      if(!save.ok){
        showCampaignLeadToast("שגיאה בשמירה", save.error || "לא ניתן לעדכן את סטטוס הליד", "warn");
        if(selectEl) abortSelect();
        return;
      }
      try { void AgentActivityLog.logLead("lead_status", lead, { detailText: campaignLeadStatusLabel(nextStatus) }); } catch(_e) {}
      showCampaignLeadToast("הליד עודכן", "הסטטוס עודכן ל-" + campaignLeadStatusLabel(nextStatus), "ok");
      await this.refresh(false);
    }
  };

  const CampaignLeadReassignAgent = {
    _overlay: null,
    _lead: null,
    _busy: false,

    open(lead){
      if(!Auth.canAccessCampaignLeadsInbox() || !lead) return;
      this.close();
      this._lead = lead;
      const agents = getCampaignLeadReassignAgents();
      const currentId = safeTrim(lead.assignedAgentId);
      const items = agents.map((a) => {
        const isPrimary = String(a.id) === String(currentId);
        const isAdditional = campaignLeadHasAdditionalAgentId(lead, a.id);
        const isAssigned = isPrimary || isAdditional;
        const isInactive = a.active === false;
        const tag = isPrimary
          ? '<span class="lcLeadReassign__itemTag">נציג ראשי</span>'
          : (isAdditional
            ? '<span class="lcLeadReassign__itemTag">שיוך נוסף</span>'
            : (isInactive ? '<span class="lcLeadReassign__itemTag lcLeadReassign__itemTag--inactive">לא פעיל</span>' : ""));
        return `<button type="button" class="lcLeadReassign__item${isAssigned ? " is-current" : ""}${isInactive ? " is-inactive" : ""}" data-reassign-agent-id="${escapeHtml(a.id)}"${isAssigned ? " disabled" : ""}>
          <span class="lcLeadReassign__itemName">${escapeHtml(a.name)}</span>
          ${tag}
        </button>`;
      }).join("");
      const primaryName = campaignLeadResolveAgentName(lead, agents);
      const extraNames = normalizeCampaignLeadAdditionalAgents(lead.additionalAgents)
        .map((a) => safeTrim(a.name) || safeTrim(agents.find((x) => String(x.id) === String(a.id))?.name))
        .filter(Boolean);
      const assignHint = extraNames.length
        ? `נציג ראשי: ${primaryName !== "—" ? primaryName : "—"} · שיוכים נוספים: ${extraNames.join(", ")}`
        : (primaryName !== "—" ? `נציג ראשי: ${primaryName}` : "טרם שויך נציג — הבחירה תהיה שיוך ראשון");
      const overlay = document.createElement("div");
      overlay.className = "lcLeadReassign__overlay";
      overlay.innerHTML = `
        <div class="lcLeadReassign__panel" role="dialog" aria-modal="true" aria-label="שיוך לנציג נוסף" dir="rtl">
          <div class="lcLeadReassign__head">
            <div>
              <div class="lcLeadReassign__title">שיוך לנציג נוסף</div>
              <div class="lcLeadReassign__sub">${escapeHtml(lead.customerName || "ליד")} · <span dir="ltr">${escapeHtml(lead.phone || "—")}</span></div>
              <div class="lcLeadReassign__sub muted small">${escapeHtml(assignHint)}</div>
            </div>
            <button type="button" class="iconBtn lcLeadReassign__close" aria-label="סגור">✕</button>
          </div>
          <div class="lcLeadReassign__list" role="listbox" aria-label="בחר נציג">
            ${items || '<div class="muted small lcLeadReassign__empty">אין נציגים במערכת</div>'}
          </div>
        </div>`;
      document.body.appendChild(overlay);
      this._overlay = overlay;
      on(overlay.querySelector(".lcLeadReassign__close"), "click", () => this.close());
      on(overlay, "click", (ev) => { if(ev.target === overlay) this.close(); });
      overlay.querySelectorAll("[data-reassign-agent-id]").forEach((btn) => {
        on(btn, "click", () => {
          const agentId = btn.getAttribute("data-reassign-agent-id");
          if(agentId) void this.assign(agentId);
        });
      });
    },

    async assign(agentId){
      if(this._busy) return;
      const lead = this._lead;
      if(!lead) return;
      const agent = getCampaignLeadReassignAgents().find((a) => String(a.id) === String(agentId));
      if(!agent) return;
      const targetAgent = resolveCampaignLeadTargetAgent(agent);
      const hasPrimary = !!safeTrim(lead.assignedAgentId);
      if(hasPrimary){
        if(String(lead.assignedAgentId) === String(targetAgent.id) || campaignLeadHasAdditionalAgentId(lead, targetAgent.id)){
          this.close();
          return;
        }
      } else if(String(lead.assignedAgentId) === String(targetAgent.id)){
        this.close();
        return;
      }
      this._busy = true;
      const previousLead = { ...lead };
      const stamp = nowISO();
      // שיוך של ליד "לא רלוונטי" לנציג נוסף/אחר → איפוס לליד חדש כדי שהנציג לא יקבל סטטוס ישן
      const resetIrrelevantForNewAgent = safeTrim(lead.status) === "irrelevant";
      const irrelevantResetPatch = resetIrrelevantForNewAgent
        ? { status: "new", irrelevantNote: "" }
        : {};
      let next;
      let detailText;
      let toastText;
      if(!hasPrimary){
        next = normalizeCampaignLead({
          ...lead,
          ...irrelevantResetPatch,
          assignedAgentId: targetAgent.id,
          assignedAgentName: targetAgent.name,
          updatedAt: stamp,
          lastModifiedAt: stamp,
          updatedByName: safeTrim(Auth?.current?.name) || ""
        });
        detailText = resetIrrelevantForNewAgent
          ? `שויך כליד חדש (אחרי לא רלוונטי) ל${targetAgent.name} על ידי ${safeTrim(Auth?.current?.name) || "סוקרת"}`
          : `שויך ל${targetAgent.name} על ידי ${safeTrim(Auth?.current?.name) || "סוקרת"}`;
        toastText = resetIrrelevantForNewAgent
          ? `שויך כליד חדש ל${targetAgent.name}`
          : `שויך ל${targetAgent.name}`;
      } else {
        const additional = normalizeCampaignLeadAdditionalAgents(lead.additionalAgents);
        additional.push({ id: targetAgent.id, name: targetAgent.name, assignedAt: stamp });
        next = normalizeCampaignLead({
          ...lead,
          ...irrelevantResetPatch,
          additionalAgents: additional,
          updatedAt: stamp,
          lastModifiedAt: stamp,
          updatedByName: safeTrim(Auth?.current?.name) || ""
        });
        detailText = resetIrrelevantForNewAgent
          ? `שויך נוסף כליד חדש (אחרי לא רלוונטי) ל${targetAgent.name} על ידי ${safeTrim(Auth?.current?.name) || "סוקרת"}`
          : `שויך נוסף ל${targetAgent.name} (נציג ראשי נשאר ${campaignLeadResolveAgentName(lead, getCampaignLeadReassignAgents())}) על ידי ${safeTrim(Auth?.current?.name) || "סוקרת"}`;
        toastText = resetIrrelevantForNewAgent
          ? `נוסף שיוך כליד חדש ל${targetAgent.name}`
          : `נוסף שיוך ל${targetAgent.name}`;
      }
      this.close();
      CampaignLeadsStore.pendingRemoteSaveIds.add(String(next.id));
      CampaignLeadsStore.applyLocal(next);
      try { CampaignLeadsUI.scheduleListRender(); } catch(_e) {}
      if(String(CampaignLeadsUI.selectedId) === String(next.id) && !hasPrimary){
        try { CampaignLeadsUI.fillAgentSelect(targetAgent.id); } catch(_e) {}
      }
      const save = await CampaignLeadsStore.persistRemote(next);
      CampaignLeadsStore.pendingRemoteSaveIds.delete(String(next.id));
      this._busy = false;
      if(!save.ok){
        CampaignLeadsStore.applyLocal(previousLead);
        try { CampaignLeadsUI.scheduleListRender(); } catch(_e) {}
        showCampaignLeadToast("שגיאה בשמירה", save.error || "לא ניתן לעדכן שיוך", "err");
        return;
      }
      try {
        void AgentActivityLog.logLead("lead_assigned", next, {
          agent: { id: targetAgent.id, name: targetAgent.name },
          detailText
        });
      } catch(_e) {}
      try { CampaignLeadAssignInbox.forgetDelivered(next.id, targetAgent.id); } catch(_e) {}
      void CampaignLeadAssignInbox.syncAssignNotice({
        targetAgentId: targetAgent.id,
        targetAgentName: targetAgent.name,
        fromName: safeTrim(Auth?.current?.name) || "מערכת",
        leadId: next.id,
        customerName: next.customerName,
        phone: next.phone,
        campaignLabel: next.campaignLabel
      });
      try { CampaignLeadsUI.scheduleListRender(); } catch(_e) {}
      try { TrackingReportUI.renderList(); } catch(_e) {}
      try { void CampaignMyLeadsUI.refresh?.(false); } catch(_e) {}
      showCampaignLeadToast("הליד עודכן", toastText, "ok");
    },

    close(){
      if(this._overlay){
        this._overlay.remove();
        this._overlay = null;
      }
      this._lead = null;
    }
  };

  // ===== בוחר צבע לשורת ליד =====
  const CampaignLeadColorPicker = {
    _overlay: null,
    _lead: null,

    COLORS: [
      { value: "#dbeafe", label: "כחול בהיר" },
      { value: "#bfdbfe", label: "כחול" },
      { value: "#93c5fd", label: "כחול כהה" },
      { value: "#d1fae5", label: "ירוק בהיר" },
      { value: "#6ee7b7", label: "ירוק" },
      { value: "#34d399", label: "ירוק כהה" },
      { value: "#fef3c7", label: "צהוב בהיר" },
      { value: "#fde68a", label: "צהוב" },
      { value: "#fcd34d", label: "צהוב כהה" },
      { value: "#fee2e2", label: "אדום בהיר" },
      { value: "#fca5a5", label: "אדום" },
      { value: "#f87171", label: "אדום כהה" },
      { value: "#ede9fe", label: "סגול בהיר" },
      { value: "#c4b5fd", label: "סגול" },
      { value: "#a78bfa", label: "סגול כהה" },
      { value: "#fce7f3", label: "ורוד בהיר" },
      { value: "#f9a8d4", label: "ורוד" },
      { value: "#f472b6", label: "ורוד כהה" },
      { value: "#ffedd5", label: "כתום בהיר" },
      { value: "#fed7aa", label: "כתום" },
      { value: "#fb923c", label: "כתום כהה" },
      { value: "#ecfeff", label: "טורקיז בהיר" },
      { value: "#a5f3fc", label: "טורקיז" },
      { value: "#22d3ee", label: "טורקיז כהה" },
      { value: "#f0fdf4", label: "ירוק מנטה" },
      { value: "#e0f2fe", label: "שמים" },
      { value: "#f5f3ff", label: "לבנדר" },
      { value: "#fff7ed", label: "שמנת" },
      { value: "#f8fafc", label: "אפור בהיר" },
      { value: "#e2e8f0", label: "אפור" }
    ],

    open(lead, anchorBtn){
      this.close();
      this._lead = lead;
      const currentColor = safeTrim(lead.rowColor);

      const overlay = document.createElement("div");
      overlay.className = "lcColorPicker__overlay";
      overlay.innerHTML = `
        <div class="lcColorPicker__panel" role="dialog" aria-modal="true" aria-label="בחר צבע לשורה" dir="rtl">
          <div class="lcColorPicker__head">
            <span class="lcColorPicker__title">🎨 צבע שורה — ${escapeHtml(lead.customerName || "ליד")}</span>
            <button class="lcColorPicker__closeBtn" type="button" aria-label="סגור">✕</button>
          </div>
          <div class="lcColorPicker__grid">
            ${this.COLORS.map(c => `
              <button class="lcColorPicker__swatch${currentColor === c.value ? " is-selected" : ""}"
                type="button"
                data-color="${escapeHtml(c.value)}"
                title="${escapeHtml(c.label)}"
                style="background:${escapeHtml(c.value)}"
                aria-label="${escapeHtml(c.label)}">
                ${currentColor === c.value ? '<span class="lcColorPicker__check">✓</span>' : ""}
              </button>`).join("")}
          </div>
          <div class="lcColorPicker__foot">
            <button class="btn lcColorPicker__clearBtn" type="button" data-color="">🚫 הסר צבע</button>
          </div>
        </div>`;

      document.body.appendChild(overlay);
      this._overlay = overlay;

      // מיקום ליד הכפתור שנלחץ — עם בדיקת גבולות מסך
      if(anchorBtn){
        try{
          const rect = anchorBtn.getBoundingClientRect();
          const panel = overlay.querySelector(".lcColorPicker__panel");
          panel.style.position = "fixed";
          panel.style.top = (rect.bottom + 6) + "px";
          panel.style.right = "";
          panel.style.left = "";
          // חישוב אחרי שהפאנל ב-DOM כדי לדעת את רוחבו
          requestAnimationFrame(() => {
            try {
              const panelW = panel.offsetWidth || 280;
              const viewW = window.innerWidth;
              // מנסים ליישר לימין הכפתור (כמו קודם)
              let desiredRight = viewW - rect.right;
              // אם זה גורם לחריגה משמאל — מזיזים
              let desiredLeft = rect.right - panelW;
              if(desiredLeft < 8){ desiredLeft = 8; }
              if(desiredLeft + panelW > viewW - 8){ desiredLeft = viewW - panelW - 8; }
              panel.style.left = desiredLeft + "px";
              panel.style.right = "";
            } catch(_e2){}
          });
        }catch(_e){}
      }

      overlay.querySelector(".lcColorPicker__closeBtn").addEventListener("click", () => this.close());
      overlay.addEventListener("click", (ev) => {
        const swatch = ev.target.closest("[data-color]");
        if(swatch) void this._applyColor(swatch.getAttribute("data-color"));
      });
      // סגירה בלחיצה מחוץ לפאנל
      overlay.addEventListener("mousedown", (ev) => {
        if(ev.target === overlay) this.close();
      });
    },

    async _applyColor(color){
      const lead = this._lead;
      if(!lead) return;
      this.close();
      const stamp = nowISO();
      const save = await CampaignLeadsStore.upsert({
        ...lead,
        rowColor: safeTrim(color) || null,
        lastModifiedAt: stamp,
        updatedAt: stamp
      });
      if(!save.ok){
        showCampaignLeadToast("שגיאה בשמירה", save.error || "לא ניתן לשמור את הצבע", "warn");
        return;
      }
      const label = color ? (this.COLORS.find(c => c.value === color)?.label || "צבע") : "ברירת מחדל";
      showCampaignLeadToast("הצבע עודכן", color ? `השורה צוּבּעה: ${label}` : "הצבע הוסר מהשורה", "ok");
      await CampaignMyLeadsUI.refresh(false);
    },

    close(){
      if(this._overlay){ this._overlay.remove(); this._overlay = null; }
      this._lead = null;
    }
  };
  // ===== סוף בוחר צבע =====

  const CampaignCallNoteModal = {
    _lead: null,
    _overlay: null,

    open(lead){
      this._lead = lead;
      this._createOverlay();
    },

    _createOverlay(){
      if(this._overlay) this._overlay.remove();
      const lead = this._lead;
      const name = safeTrim(lead?.customerName) || "ליד";
      const phone = safeTrim(lead?.phone);
      const overlay = document.createElement("div");
      overlay.className = "gi-modal-overlay gi-modal-overlay--active";
      overlay.innerHTML = `
        <div class="gi-modal gi-modal--callNote lcLeadCardModal">
          <div class="gi-modal__header lcLeadCardModal__header">
            <div class="lcLeadCardModal__headerMain">
              <div class="lcLeadCardModal__kicker">תיעוד שיחה</div>
              <h3 class="gi-modal__title lcLeadCardModal__title">${escapeHtml(name)}</h3>
              ${phone ? `<div class="lcLeadCardModal__meta" dir="ltr">${escapeHtml(phone)}</div>` : ""}
            </div>
            <button class="iconBtn lcLeadCardModal__close" type="button" id="btnCallNoteCancelX" aria-label="סגור">✕</button>
          </div>
          <div class="gi-modal__body lcLeadCardModal__body">
            <p class="lcLeadCardModal__hint">רשום מה סיכמת עם הלקוח או מה דיברת — לשימוש בשיחה הבאה.</p>
            <label class="lcLeadCardModal__fieldLabel" for="clCallNoteText">תיעוד</label>
            <textarea class="input gi-modal__textarea lcLeadCardModal__textarea" id="clCallNoteText" rows="7" placeholder="תיעוד שיחה (אופציונלי)..." dir="rtl"></textarea>
            <div class="gi-modal__error" id="clCallNoteError" style="display:none"></div>
          </div>
          <div class="gi-modal__footer lcLeadCardModal__footer">
            <button class="btn" type="button" id="btnCallNoteCancel">ביטול</button>
            <button class="btn btn--primary" type="button" id="btnCallNoteSave">שמירה</button>
          </div>
        </div>
      `;
      document.body.appendChild(overlay);
      this._overlay = overlay;

      const textarea = overlay.querySelector("#clCallNoteText");
      if(textarea) textarea.value = safeTrim(lead?.callNote);
      const btnSave = overlay.querySelector("#btnCallNoteSave");
      const btnCancel = overlay.querySelector("#btnCallNoteCancel");
      const btnCancelX = overlay.querySelector("#btnCallNoteCancelX");
      const errEl = overlay.querySelector("#clCallNoteError");

      on(btnCancel, "click", () => this.close());
      on(btnCancelX, "click", () => this.close());
      on(overlay, "click", (ev) => { if(ev.target === overlay) this.close(); });
      on(btnSave, "click", async () => {
        btnSave.disabled = true;
        btnSave.textContent = "שומר...";
        const stamp = nowISO();
        const save = await CampaignLeadsStore.upsert({
          ...this._lead,
          callNote: safeTrim(textarea?.value),
          lastModifiedAt: stamp,
          updatedAt: stamp
        });
        if(!save.ok){
          errEl.style.display = "";
          errEl.textContent = save.error || "שגיאה בשמירה";
          btnSave.disabled = false;
          btnSave.textContent = "שמירה";
          showCampaignLeadToast("שגיאה בשמירה", save.error || "לא ניתן לשמור את תיעוד השיחה", "warn");
          return;
        }
        showCampaignLeadToast("נשמר", "תיעוד השיחה נשמר", "ok");
        try { void AgentActivityLog.logLead("lead_call_note", this._lead, { detailText: "נשמר תיעוד שיחה" }); } catch(_e) {}
        this.close();
        await CampaignMyLeadsUI.refresh(false);
      });

      try { textarea.focus(); } catch(_e){}
    },

    close(){
      if(this._overlay){
        this._overlay.remove();
        this._overlay = null;
      }
      this._lead = null;
    }
  };

  const CampaignIrrelevantModal = {
    _lead: null,
    _overlay: null,

    open(lead, options = {}){
      this._lead = lead;
      this._onAbort = typeof options.onAbort === "function" ? options.onAbort : null;
      this._createOverlay();
    },

    _createOverlay(){
      if(this._overlay) this._overlay.remove();
      const overlay = document.createElement("div");
      overlay.className = "gi-modal-overlay gi-modal-overlay--active";
      overlay.innerHTML = `
        <div class="gi-modal gi-modal--irrelevant">
          <div class="gi-modal__header">
            <h3 class="gi-modal__title">סיכום שיחה — לא רלוונטי</h3>
          </div>
          <div class="gi-modal__body">
            <p class="gi-modal__hint">יש לתעד סיכום שיחה עם הלקוח לפני סגירת הליד כלא רלוונטי:</p>
            <textarea class="input gi-modal__textarea" id="clIrrelevantNote" rows="5" placeholder="תיעוד סיכום שיחה (חובה)..." dir="rtl"></textarea>
            <div class="gi-modal__error" id="clIrrelevantError" style="display:none"></div>
          </div>
          <div class="gi-modal__footer">
            <button class="btn" type="button" id="btnIrrelevantCancel">ביטול</button>
            <button class="btn btn--primary" type="button" id="btnIrrelevantSave">שמירה</button>
          </div>
        </div>
      `;
      document.body.appendChild(overlay);
      this._overlay = overlay;

      const textarea = overlay.querySelector("#clIrrelevantNote");
      const btnSave = overlay.querySelector("#btnIrrelevantSave");
      const btnCancel = overlay.querySelector("#btnIrrelevantCancel");
      const errEl = overlay.querySelector("#clIrrelevantError");

      on(btnCancel, "click", () => {
        try { this._onAbort?.(); } catch(_e) {}
        this.close();
      });
      on(btnSave, "click", async () => {
        const note = safeTrim(textarea?.value);
        if(!note){
          errEl.style.display = "";
          errEl.textContent = "חובה לתעד סיכום שיחה";
          return;
        }
        btnSave.disabled = true;
        btnSave.textContent = "שומר...";
        const stamp = nowISO();
        const save = await CampaignLeadsStore.upsert({
          ...this._lead,
          status: "irrelevant",
          irrelevantNote: note,
          lastModifiedAt: stamp,
          updatedAt: stamp
        });
        if(!save.ok){
          errEl.style.display = "";
          errEl.textContent = save.error || "שגיאה בשמירה";
          btnSave.disabled = false;
          btnSave.textContent = "שמירה";
          showCampaignLeadToast("שגיאה בשמירה", save.error || "לא ניתן לסמן את הליד כלא רלוונטי", "warn");
          return;
        }
        showCampaignLeadToast("הליד עודכן", "הליד סומן כלא רלוונטי", "ok");
        try { void AgentActivityLog.logLead("lead_irrelevant", this._lead, { detailText: "סומן כלא רלוונטי" }); } catch(_e) {}
        const leadId = safeTrim(this._lead?.id);
        CampaignMyLeadsUI.statusFilter = "all";
        CampaignMyLeadsUI.pendingHighlightId = leadId;
        if(CampaignMyLeadsUI.els.statusFilters){
          CampaignMyLeadsUI.els.statusFilters.querySelectorAll(".mcSearch__chip").forEach((c) => {
            c.classList.toggle("is-active", (c.getAttribute("data-my-status-filter") || "all") === "all");
          });
        }
        this.close();
        await CampaignMyLeadsUI.refresh(false);
      });

      try { textarea.focus(); } catch(_e){}
    },

    close(){
      if(this._overlay){
        this._overlay.remove();
        this._overlay = null;
      }
      this._lead = null;
      this._onAbort = null;
    }
  };

  const CampaignNoteViewer = {
    _overlay: null,

    open(lead, options = {}){
      this.close();
      const kind = safeTrim(options.kind) || "irrelevant";
      const name = safeTrim(lead.customerName) || "ליד";
      const note = kind === "closed"
        ? (safeTrim(lead.closedNote) || "—")
        : kind === "call"
          ? (safeTrim(lead.callNote) || "—")
          : (safeTrim(lead.irrelevantNote) || "—");
      const modalTitle = kind === "closed"
        ? `תיעוד מכירה — ${name}`
        : kind === "call"
          ? `תיעוד שיחה — ${name}`
          : `תיעוד נציג (לא רלוונטי) — ${name}`;
      const agentName = (() => {
        const aid = safeTrim(lead.assignedAgentId);
        if(!aid) return "";
        const agents = Array.isArray(State.data?.agents) ? State.data.agents : [];
        const ag = agents.find((a) => String(a?.id) === aid);
        return safeTrim(ag?.name) || safeTrim(lead.assignedAgentName) || "";
      })();
      let modDate = "";
      const raw = kind === "closed"
        ? (safeTrim(lead.closedAt) || safeTrim(lead.lastModifiedAt || lead.updatedAt))
        : safeTrim(lead.lastModifiedAt || lead.updatedAt);
      if(raw){
        try {
          const d = new Date(raw);
          if(!isNaN(d.getTime())) modDate = d.toLocaleString("he-IL", { timeZone:"Asia/Jerusalem", day:"2-digit", month:"2-digit", year:"numeric", hour:"2-digit", minute:"2-digit" });
        } catch(_e){}
      }

      const overlay = document.createElement("div");
      overlay.className = "gi-modal-overlay gi-modal-overlay--active";
      overlay.innerHTML = `
        <div class="gi-modal gi-modal--noteViewer">
          <div class="gi-modal__header">
            <h3 class="gi-modal__title">${escapeHtml(modalTitle)}</h3>
          </div>
          <div class="gi-modal__body">
            ${agentName ? `<div class="lcNoteViewer__meta"><svg class="lcNoteViewer__metaIcon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="M12 13a5 5 0 1 0 0-10 5 5 0 0 0 0 10Z"/><path d="M5 21v-2a4 4 0 0 1 4-4h6a4 4 0 0 1 4 4v2"/></svg><span>נציג: <strong>${escapeHtml(agentName)}</strong></span></div>` : ""}
            ${modDate ? `<div class="lcNoteViewer__meta"><svg class="lcNoteViewer__metaIcon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"/><path d="M12 6v6l4 2"/></svg><span>תאריך: ${escapeHtml(modDate)}</span></div>` : ""}
            <div class="lcNoteViewer__noteBox">${escapeHtml(note).replace(/\n/g, "<br/>")}</div>
          </div>
          <div class="gi-modal__footer">
            <button class="btn btn--primary" type="button" id="btnNoteViewerClose">סגור</button>
          </div>
        </div>
      `;
      document.body.appendChild(overlay);
      this._overlay = overlay;

      on(overlay.querySelector("#btnNoteViewerClose"), "click", () => this.close());
      on(overlay, "click", (ev) => { if(ev.target === overlay) this.close(); });
    },

    close(){
      if(this._overlay){
        this._overlay.remove();
        this._overlay = null;
      }
    }
  };


  const LeadDetailsModal = {
    _overlay: null,
    _windows: Object.create(null),

    _formatDate(raw){
      const s = safeTrim(raw);
      if(!s) return "—";
      try {
        const d = new Date(s);
        if(!isNaN(d.getTime())) return d.toLocaleDateString("he-IL", { day:"2-digit", month:"2-digit", year:"numeric" });
      } catch(_e){}
      return s;
    },

    _fieldHtml(label, value, copyRaw){
      const display = value || "—";
      const copyVal = safeTrim(copyRaw !== undefined ? copyRaw : value);
      return `<div class="lcLeadDetails__row lcMyLeadCopy" data-copy-text="${escapeHtml(copyVal)}" data-copy-label="${escapeHtml(label)}" title="דאבל-קליק להעתקה"><span class="lcLeadDetails__label">${escapeHtml(label)}</span><span class="lcLeadDetails__value">${escapeHtml(display)}</span></div>`;
    },

    _buildCardInnerHtml(lead){
      const sourceLabels = { manual:"ידני", landing:"לנדינג", campaign:"קמפיין" };
      const sourceLabel = sourceLabels[safeTrim(lead.source)] || safeTrim(lead.source) || "—";
      const desc = safeTrim(lead.descriptionDisplay || stripCampaignLeadPayloadMarker(lead.description)) || "—";
      const statusLabel = campaignLeadStatusLabel(lead.status);
      const statusTone = campaignLeadStatusTone(lead.status);
      const phone = safeTrim(lead.phone);
      const phoneDigits = phone.replace(/[^\d+]/g, "");
      const row = (label, value, copyRaw) => this._fieldHtml(label, value, copyRaw);

      return `
        <div class="lcLeadFloatCard" data-lead-id="${escapeHtml(String(lead.id || ""))}">
          <div class="lcLeadFloatCard__header">
            <div class="lcLeadFloatCard__headerMain">
              <div class="lcLeadFloatCard__kicker">תיעוד ליד</div>
              <h3 class="lcLeadFloatCard__title">${escapeHtml(lead.customerName || "ליד")}</h3>
              <span class="lcTrackBadge lcTrackBadge--${statusTone} lcLeadFloatCard__badge">${escapeHtml(statusLabel)}</span>
            </div>
            <button class="lcLeadFloatCard__close" type="button" data-lead-float-close="1" aria-label="סגור">✕</button>
          </div>
          <div class="lcLeadFloatCard__body">
            <div class="lcLeadDetails__grid">
              ${row("שם לקוח", lead.customerName)}
              ${row("טלפון", lead.phone)}
              ${row("תעודת זהות", lead.idNumber)}
              ${row("תאריך לידה", this._formatDate(lead.birthDate), lead.birthDate)}
              ${row("תאריך הנפקת ת״ז", this._formatDate(lead.idIssueDate), lead.idIssueDate)}
              ${row("שם קמפיין", lead.campaignLabel)}
              ${row("חברת ביטוח", lead.insuranceCompany)}
              ${row("מקור הליד", sourceLabel)}
              ${row("נציג משויך", lead.assignedAgentName)}
              ${row("תאריך יצירה", this._formatDate(lead.createdAt), lead.createdAt)}
              ${row("עדכון אחרון", this._formatDate(lead.lastModifiedAt || lead.updatedAt), lead.lastModifiedAt || lead.updatedAt)}
            </div>
            <div class="lcLeadDetails__descSection">
              <div class="lcLeadDetails__descLabel">תיאור מלא</div>
              <div class="lcLeadDetails__descBox lcMyLeadCopy" data-copy-text="${escapeHtml(desc === "—" ? "" : desc)}" data-copy-label="תיאור מלא" title="דאבל-קליק להעתקה">${escapeHtml(desc).replace(/\n/g, "<br/>")}</div>
            </div>
            ${safeTrim(lead.irrelevantNote) ? `
            <div class="lcLeadDetails__descSection">
              <div class="lcLeadDetails__descLabel lcLeadDetails__descLabel--warn">הערת נציג (לא רלוונטי)</div>
              <div class="lcLeadDetails__descBox lcLeadDetails__descBox--warn lcMyLeadCopy" data-copy-text="${escapeHtml(safeTrim(lead.irrelevantNote))}" data-copy-label="הערת נציג" title="דאבל-קליק להעתקה">${escapeHtml(safeTrim(lead.irrelevantNote)).replace(/\n/g, "<br/>")}</div>
            </div>` : ""}
            ${safeTrim(lead.closedNote) ? `
            <div class="lcLeadDetails__descSection">
              <div class="lcLeadDetails__descLabel lcLeadDetails__descLabel--success">תיעוד מכירה (נסגר)</div>
              <div class="lcLeadDetails__descBox lcLeadDetails__descBox--success lcMyLeadCopy" data-copy-text="${escapeHtml(safeTrim(lead.closedNote))}" data-copy-label="תיעוד מכירה" title="דאבל-קליק להעתקה">${escapeHtml(safeTrim(lead.closedNote)).replace(/\n/g, "<br/>")}</div>
            </div>` : ""}
            ${safeTrim(lead.callNote) ? `
            <div class="lcLeadDetails__descSection">
              <div class="lcLeadDetails__descLabel">תיעוד שיחה</div>
              <div class="lcLeadDetails__descBox lcMyLeadCopy" data-copy-text="${escapeHtml(safeTrim(lead.callNote))}" data-copy-label="תיעוד שיחה" title="דאבל-קליק להעתקה">${escapeHtml(safeTrim(lead.callNote)).replace(/\n/g, "<br/>")}</div>
            </div>` : ""}
          </div>
          <div class="lcLeadFloatCard__footer">
            ${phoneDigits ? `<a class="lcLeadFloatCard__btn lcLeadFloatCard__btn--primary" href="tel:${escapeHtml(phoneDigits)}">התקשר</a>` : ""}
            <button class="lcLeadFloatCard__btn" type="button" data-lead-float-close="1">סגור</button>
          </div>
        </div>`;
    },

    _floatCardCss(){
      return `
        :root{ --gi-text:#0F172A; --gi-muted:#647287; --gi-border:#E5E7EB; --gi-bg:#F8FAFC; --gi-primary:#2563EB; --gi-primary-soft:#EFF6FF; }
        *{box-sizing:border-box}
        html,body{margin:0;padding:0;background:#EEF2F6;color:var(--gi-text);font-family:Heebo,Arial,Helvetica,sans-serif}
        body{padding:14px;min-height:100vh}
        .lcLeadFloatCard{background:#fff;border:1px solid var(--gi-border);border-radius:16px;box-shadow:0 8px 28px rgba(15,23,42,.08);overflow:hidden;max-width:520px;margin:0 auto;display:flex;flex-direction:column;min-height:calc(100vh - 28px)}
        .lcLeadFloatCard__header{display:flex;align-items:flex-start;justify-content:space-between;gap:12px;padding:16px 18px;border-bottom:1px solid var(--gi-border);background:#fff}
        .lcLeadFloatCard__headerMain{display:flex;flex-direction:column;gap:4px;min-width:0}
        .lcLeadFloatCard__kicker{font-size:11px;font-weight:700;color:var(--gi-muted);letter-spacing:.04em}
        .lcLeadFloatCard__title{margin:0;font-size:20px;font-weight:800;line-height:1.25;color:var(--gi-text)}
        .lcLeadFloatCard__badge{margin-top:4px;display:inline-block;align-self:flex-start}
        .lcLeadFloatCard__close{width:32px;height:32px;border-radius:8px;border:1px solid var(--gi-border);background:#fff;color:var(--gi-muted);cursor:pointer;font-size:14px;line-height:1;flex-shrink:0}
        .lcLeadFloatCard__close:hover{background:var(--gi-bg);color:var(--gi-text)}
        .lcLeadFloatCard__body{padding:16px 18px 8px;flex:1;overflow:auto}
        .lcLeadDetails__grid{display:grid;grid-template-columns:1fr 1fr;gap:0;margin-bottom:16px;border:1px solid var(--gi-border);border-radius:12px;overflow:hidden;background:#fff}
        .lcLeadDetails__row{display:flex;flex-direction:column;gap:3px;padding:10px 12px;border-bottom:1px solid var(--gi-border);border-inline-end:1px solid var(--gi-border);background:#fff}
        .lcLeadDetails__row:nth-child(2n){border-inline-end:none}
        .lcLeadDetails__label{font-size:11px;font-weight:700;color:var(--gi-muted)}
        .lcLeadDetails__value{font-size:14px;font-weight:600;color:var(--gi-text);word-break:break-word}
        .lcMyLeadCopy{cursor:copy}
        .lcMyLeadCopy:hover{background:rgba(37,99,235,.04)}
        .lcLeadDetails__descSection{margin-bottom:14px}
        .lcLeadDetails__descLabel{font-size:12px;font-weight:700;color:var(--gi-text);margin-bottom:6px}
        .lcLeadDetails__descLabel--warn{color:#B91C1C}
        .lcLeadDetails__descLabel--success{color:#166534}
        .lcLeadDetails__descBox{padding:12px 14px;border-radius:10px;background:var(--gi-bg);border:1px solid var(--gi-border);font-size:14px;line-height:1.7;white-space:pre-wrap;word-break:break-word;min-height:48px;max-height:220px;overflow:auto}
        .lcLeadDetails__descBox--warn{background:#FEF2F2;border-color:#FECACA}
        .lcLeadDetails__descBox--success{background:#ECFDF5;border-color:#A7F3D0}
        .lcLeadFloatCard__footer{display:flex;justify-content:flex-start;gap:8px;padding:14px 18px;border-top:1px solid var(--gi-border);background:#fff}
        .lcLeadFloatCard__btn{display:inline-flex;align-items:center;justify-content:center;min-height:36px;padding:0 14px;border-radius:8px;border:1px solid var(--gi-border);background:#fff;color:var(--gi-text);font:inherit;font-size:13px;font-weight:700;text-decoration:none;cursor:pointer}
        .lcLeadFloatCard__btn:hover{background:var(--gi-bg)}
        .lcLeadFloatCard__btn--primary{background:var(--gi-primary);border-color:var(--gi-primary);color:#fff}
        .lcLeadFloatCard__btn--primary:hover{background:#1D4ED8;border-color:#1D4ED8;color:#fff}
        .lcTrackBadge{display:inline-flex;align-items:center;padding:3px 8px;border-radius:6px;font-size:11px;font-weight:700}
        .lcTrackBadge--blue{background:rgba(59,130,246,.15);color:#1d4ed8;border:1px solid rgba(59,130,246,.28)}
        .lcTrackBadge--green{background:rgba(22,163,74,.14);color:#15803d;border:1px solid rgba(22,163,74,.25)}
        .lcTrackBadge--yellow{background:rgba(234,179,8,.14);color:#92400e;border:1px solid rgba(234,179,8,.30)}
        .lcTrackBadge--red{background:rgba(239,68,68,.12);color:#991b1b;border:1px solid rgba(239,68,68,.22)}
        .lcTrackBadge--orange{background:rgba(249,115,22,.14);color:#9a3412;border:1px solid rgba(249,115,22,.28)}
        .lcTrackBadge--purple{background:rgba(147,51,234,.14);color:#6b21a8;border:1px solid rgba(147,51,234,.26)}
        .lcTrackBadge--neutral{background:rgba(15,25,45,.06);color:#647287;border:1px solid rgba(15,25,45,.10)}
        .gi-toast{position:fixed;bottom:16px;left:50%;transform:translateX(-50%);background:#0F172A;color:#fff;padding:8px 14px;border-radius:8px;font-size:13px;font-weight:600;z-index:9;opacity:0;transition:opacity .15s}
        .gi-toast.is-on{opacity:1}
        @media (max-width:420px){ .lcLeadDetails__grid{grid-template-columns:1fr} .lcLeadDetails__row{border-inline-end:none} }
      `;
    },

    _buildPopupDocument(lead){
      const title = safeTrim(lead.customerName) || "פרטי ליד";
      const inner = this._buildCardInnerHtml(lead);
      return `<!doctype html><html lang="he" dir="rtl"><head><meta charset="utf-8"><title>${escapeHtml(title)} · פרטי ליד</title>
<meta name="viewport" content="width=device-width,initial-scale=1">
<link href="https://fonts.googleapis.com/css2?family=Heebo:wght@400;500;600;700;800&display=swap" rel="stylesheet"/>
<style>${this._floatCardCss()}</style></head><body>
${inner}
<script>
(function(){
  function toast(msg){
    var el = document.querySelector(".gi-toast");
    if(!el){ el = document.createElement("div"); el.className = "gi-toast"; document.body.appendChild(el); }
    el.textContent = msg || "הועתק";
    el.classList.add("is-on");
    clearTimeout(el._t);
    el._t = setTimeout(function(){ el.classList.remove("is-on"); }, 1800);
  }
  function copyText(text, label){
    var val = String(text || "").trim();
    if(!val || val === "—"){ toast("אין ערך להעתקה"); return; }
    try{
      var ta = document.createElement("textarea");
      ta.value = val; ta.setAttribute("readonly",""); ta.style.cssText="position:fixed;left:-9999px;top:0;opacity:0";
      document.body.appendChild(ta); ta.select();
      var ok = document.execCommand("copy");
      ta.remove();
      if(ok) toast((label ? label + " הועתק" : "הועתק"));
      else toast("ההעתקה נכשלה");
    }catch(e){ toast("ההעתקה נכשלה"); }
  }
  document.addEventListener("click", function(ev){
    if(ev.target && ev.target.closest && ev.target.closest("[data-lead-float-close]")){
      window.close();
    }
  });
  document.addEventListener("dblclick", function(ev){
    var block = ev.target && ev.target.closest && ev.target.closest(".lcMyLeadCopy");
    if(!block) return;
    ev.preventDefault();
    var raw = block.getAttribute("data-copy-text");
    var text = (raw != null && String(raw).trim() !== "") ? String(raw).trim() : String(block.textContent || "").trim();
    copyText(text, block.getAttribute("data-copy-label") || "");
  });
})();
<\/script>
</body></html>`;
    },

    _bindInAppCard(root, lead){
      if(!root) return;
      const close = () => this.close();
      root.querySelectorAll("[data-lead-float-close]").forEach((btn) => on(btn, "click", close));
      on(root, "dblclick", (ev) => {
        if(ev.target.closest("button,a")) return;
        const block = ev.target.closest(".lcMyLeadCopy");
        if(!block) return;
        ev.preventDefault();
        ev.stopPropagation();
        giCopyToClipboard(giResolveCopyText(block), block.getAttribute("data-copy-label") || "");
      });
    },

    _openInAppFallback(lead){
      this._closeOverlayOnly();
      const overlay = document.createElement("div");
      overlay.className = "gi-modal-overlay gi-modal-overlay--active lcLeadFloatOverlay";
      overlay.innerHTML = `<div class="gi-modal gi-modal--leadDetails lcLeadCardModal">${this._buildCardInnerHtml(lead)}</div>`;
      document.body.appendChild(overlay);
      this._overlay = overlay;
      const modal = overlay.querySelector(".gi-modal--leadDetails");
      this._bindInAppCard(modal, lead);
      on(overlay, "click", (ev) => { if(ev.target === overlay) this.close(); });
    },

    _closeOverlayOnly(){
      if(this._overlay){
        this._overlay.remove();
        this._overlay = null;
      }
    },

    _windowNameFor(lead){
      return "giLeadCard_" + String(lead?.id || "tmp").replace(/[^\w\-]/g, "_");
    },

    open(lead){
      if(!lead) return;
      try { void AgentActivityLog.logLead("lead_open", lead); } catch(_e) {}

      const winName = this._windowNameFor(lead);
      let win = null;
      try {
        win = window.open("", winName, "popup=yes,width=500,height=760,resizable=yes,scrollbars=yes");
      } catch(_e) { win = null; }

      if(win){
        this._closeOverlayOnly();
        try {
          win.document.open();
          win.document.write(this._buildPopupDocument(lead));
          win.document.close();
          try { win.focus(); } catch(_e2) {}
          this._windows[String(lead.id)] = win;
          return;
        } catch(_e) {
          try { win.close(); } catch(_e2) {}
        }
      }

      this._openInAppFallback(lead);
      try {
        if(typeof toast === "function") toast("נפתח במסך המערכת", "אם נחסמו חלונות קופצים — אפשר אותם כדי לפתוח כרטיסייה צפה מחוץ למערכת");
      } catch(_e) {}
    },

    close(){
      this._closeOverlayOnly();
    }
  };

  const CampaignClosedLeadFlow = {
    _lead: null,
    _overlay: null,

    start(lead, options = {}){
      this._lead = lead;
      this._onAbort = typeof options.onAbort === "function" ? options.onAbort : null;
      this._showSaleNoteModal();
    },

    _showSaleNoteModal(){
      if(this._overlay) this._overlay.remove();
      const overlay = document.createElement("div");
      overlay.className = "gi-modal-overlay gi-modal-overlay--active";
      overlay.innerHTML = `
        <div class="gi-modal gi-modal--saleNote">
          <div class="gi-modal__header">
            <h3 class="gi-modal__title">סגירת ליד — תיעוד מכירה</h3>
          </div>
          <div class="gi-modal__body">
            <p class="gi-modal__hint">יש לתעד מה נמכר ללקוח לפני סגירת הליד:</p>
            <textarea class="input gi-modal__textarea" id="clSaleNoteTextarea" rows="5" placeholder="פרט את המוצרים שנמכרו, חברות, פרמיות וכל פרט רלוונטי..." dir="rtl"></textarea>
            <div class="gi-modal__error" id="clSaleNoteError" style="display:none"></div>
          </div>
          <div class="gi-modal__footer">
            <button class="btn" type="button" id="btnSaleNoteCancel">ביטול</button>
            <button class="btn btn--primary" type="button" id="btnSaleNoteSave">שמור וסגור ליד</button>
          </div>
        </div>
      `;
      document.body.appendChild(overlay);
      this._overlay = overlay;

      const textarea = overlay.querySelector("#clSaleNoteTextarea");
      const btnSave = overlay.querySelector("#btnSaleNoteSave");
      const btnCancel = overlay.querySelector("#btnSaleNoteCancel");
      const errEl = overlay.querySelector("#clSaleNoteError");

      on(btnCancel, "click", () => {
        try { this._onAbort?.(); } catch(_e) {}
        this._removeOverlay();
        this._lead = null;
        this._onAbort = null;
      });

      on(btnSave, "click", async () => {
        const note = safeTrim(textarea?.value);
        if(!note){
          errEl.style.display = "";
          errEl.textContent = "חובה לתעד מה נמכר ללקוח";
          return;
        }
        btnSave.disabled = true;
        btnSave.textContent = "שומר...";
        await this._processClose(note);
      });

      try { textarea.focus(); } catch(_e){}
    },

    async _processClose(closedNote){
      const lead = this._lead;
      if(!lead) return;

      const stamp = nowISO();
      const save = await CampaignLeadsStore.upsert({
        ...lead,
        status: "closed",
        closedAt: stamp,
        closedNote: safeTrim(closedNote),
        lastModifiedAt: stamp,
        updatedAt: stamp
      });

      if(!save.ok){
        const errEl = this._overlay?.querySelector?.("#clSaleNoteError");
        const btnSave = this._overlay?.querySelector?.("#btnSaleNoteSave");
        if(errEl){
          errEl.style.display = "";
          errEl.textContent = save.error || "שגיאה בשמירה";
        }
        if(btnSave){
          btnSave.disabled = false;
          btnSave.textContent = "שמור וסגור ליד";
        }
        showCampaignLeadToast("שגיאה בשמירה", save.error || "לא ניתן לסגור את הליד כעת", "warn");
        return;
      }

      this._removeOverlay();
      this._lead = null;
      showCampaignLeadToast("הליד עודכן", "הליד נסגר בהצלחה", "ok");
      try { void AgentActivityLog.logLead("lead_closed", lead, { detailText: "ליד נסגר" }); } catch(_e) {}
      await CampaignMyLeadsUI.refresh(false);

      try {
        this._openWizardWithLeadData(lead);
      } catch(err){
        console.error("CampaignClosedLeadFlow wizard error:", err);
        showCampaignLeadToast("הליד נסגר", "התיעוד נשמר. לא הצלחנו לפתוח את האשף אוטומטית — ניתן להמשיך ידנית מהתפריט.", "warn");
      }
    },

    _openWizardWithLeadData(lead){
      const customerName = safeTrim(lead.customerName);
      const nameParts = customerName.split(/\s+/).filter(Boolean);
      const firstName = nameParts[0] || "";
      const lastName = nameParts.length > 1 ? nameParts.slice(1).join(" ") : "";

      const prefillPayload = {
        fullName: customerName,
        firstName,
        lastName,
        idNumber: safeTrim(lead.idNumber),
        phone: safeTrim(lead.phone),
        birthDate: safeTrim(lead.birthDate),
        idIssueDate: safeTrim(lead.idIssueDate),
        insuranceTypes: lead.insuranceTypes || [],
        insuranceTypeLabels: lead.insuranceTypeLabels || []
      };

      try {
        Wizard._campaignLeadId = safeTrim(lead.id);
        prepareInteractiveWizardOpen();
        Wizard.reset();

        const ins = Wizard.insureds?.[0];
        if(ins?.data){
          if(firstName) ins.data.firstName = firstName;
          if(lastName) ins.data.lastName = lastName;
          if(prefillPayload.idNumber) ins.data.idNumber = normalizeIdValue(prefillPayload.idNumber);
          if(prefillPayload.phone) ins.data.phone = normalizePhoneValue(prefillPayload.phone);
          if(prefillPayload.birthDate) ins.data.birthDate = prefillPayload.birthDate;
          if(prefillPayload.idIssueDate) ins.data.idIssueDate = prefillPayload.idIssueDate;
        }

        Wizard.open();
        Wizard.setHint("פרטי הליד נטענו אוטומטית — המשיכו באשף בריאות וסיכונים.");
      } catch(err){
        console.error("CampaignClosedLeadFlow wizard error:", err);
        throw err;
      }
    },

    _removeOverlay(){
      if(this._overlay){
        this._overlay.remove();
        this._overlay = null;
      }
    }
  };

